# =========================================================================
# memory  -  Gedächtnis, Ebene 0 - Notizen, Kontakte, Kennzahlen, offene Punkte, Protokoll.
# 
# Alles liegt lokal in einer SQLite-Datei. Supabase wird, falls konfiguriert,
# nur zusätzlich gespiegelt: Die Wahrheit steht immer auf dem Rechner des Nutzers.
# =========================================================================

#!/usr/bin/env python3
# -*- coding: utf-8 -*-



_DB_SPERRE = threading.Lock()

SCHEMA_MEMORY = """
CREATE TABLE IF NOT EXISTS notizen (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    text TEXT NOT NULL,
    kategorie TEXT DEFAULT 'allgemein',
    angelegt TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS kontakte (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    firma TEXT DEFAULT '',
    telefon TEXT DEFAULT '',
    email TEXT DEFAULT '',
    adresse TEXT DEFAULT '',
    notiz TEXT DEFAULT '',
    angelegt TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS kennzahlen (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    wert REAL NOT NULL,
    einheit TEXT DEFAULT '',
    datum TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS offene_punkte (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    text TEXT NOT NULL,
    faellig TEXT DEFAULT '',
    erledigt INTEGER DEFAULT 0,
    angelegt TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS aktionen (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    werkzeug TEXT NOT NULL,
    argumente TEXT DEFAULT '',
    ergebnis TEXT DEFAULT '',
    status TEXT DEFAULT 'ok',
    zeit TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS verlauf (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    rolle TEXT NOT NULL,
    text TEXT NOT NULL,
    zeit TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_notizen_text ON notizen(text);
CREATE INDEX IF NOT EXISTS idx_verlauf_zeit ON verlauf(zeit);
"""


def zeitstempel() -> str:
    """Aktuelle Zeit als ``JJJJ-MM-TT HH:MM:SS``."""
    return datetime.now().strftime("%Y-%m-%d %H:%M:%S")


def heute_datum() -> str:
    """Heutiges Datum als ``JJJJ-MM-TT``."""
    return datetime.now().strftime("%Y-%m-%d")


def db_verbindung(pfad: str = None) -> sqlite3.Connection:
    """Öffnet eine SQLite-Verbindung mit Zeilen-Zugriff über Spaltennamen."""
    verbindung = sqlite3.connect(pfad or DB_PFAD, timeout=15,
                                 check_same_thread=False)
    verbindung.row_factory = sqlite3.Row
    verbindung.execute("PRAGMA journal_mode=WAL")
    return verbindung


def db_schema_anlegen(schema: str, pfad: str = None):
    """Legt die Tabellen eines Moduls an, falls sie noch fehlen."""
    with _DB_SPERRE:
        verbindung = db_verbindung(pfad)
        try:
            verbindung.executescript(schema)
            verbindung.commit()
        finally:
            verbindung.close()


def zeilen_zu_liste(zeilen) -> list:
    """Wandelt SQLite-Zeilen in gewöhnliche Wörterbücher um."""
    return [dict(zeile) for zeile in zeilen]


class Memory:
    """Das Kurzzeit- und Sachgedächtnis: Notizen, Kontakte, Zahlen, Protokoll."""

    def __init__(self, db_pfad: str = None):
        self.db_pfad = db_pfad or DB_PFAD
        db_schema_anlegen(SCHEMA_MEMORY, self.db_pfad)

    # -- Grundlagen ---------------------------------------------------------

    def _schreiben(self, sql: str, werte: tuple = ()) -> int:
        with _DB_SPERRE:
            verbindung = db_verbindung(self.db_pfad)
            try:
                zeiger = verbindung.execute(sql, werte)
                verbindung.commit()
                return zeiger.lastrowid
            finally:
                verbindung.close()

    def _lesen(self, sql: str, werte: tuple = ()) -> list:
        verbindung = db_verbindung(self.db_pfad)
        try:
            return zeilen_zu_liste(verbindung.execute(sql, werte).fetchall())
        finally:
            verbindung.close()

    # -- Notizen ------------------------------------------------------------

    def notiz_speichern(self, text: str, kategorie: str = "allgemein") -> dict:
        """Hält eine Notiz fest und gibt sie mit ihrer Nummer zurück."""
        text = (text or "").strip()
        if not text:
            return {"ok": False, "fehler": "Die Notiz ist leer."}
        nummer = self._schreiben(
            "INSERT INTO notizen (text, kategorie, angelegt) VALUES (?,?,?)",
            (text, kategorie or "allgemein", zeitstempel()))
        self._spiegeln("notizen", {"text": text, "kategorie": kategorie})
        return {"ok": True, "id": nummer, "text": text, "kategorie": kategorie}

    def notizen_suchen(self, begriff: str, limit: int = 20) -> list:
        """Sucht Notizen, deren Text den Begriff enthält."""
        begriff = (begriff or "").strip()
        if not begriff:
            return self.notizen_letzte(limit)
        return self._lesen(
            "SELECT * FROM notizen WHERE text LIKE ? OR kategorie LIKE ? "
            "ORDER BY id DESC LIMIT ?",
            ("%%%s%%" % begriff, "%%%s%%" % begriff, limit))

    def notizen_letzte(self, limit: int = 10) -> list:
        """Die zuletzt angelegten Notizen."""
        return self._lesen("SELECT * FROM notizen ORDER BY id DESC LIMIT ?", (limit,))

    def notiz_loeschen(self, nummer: int) -> bool:
        """Löscht eine Notiz anhand ihrer Nummer."""
        vorher = self._lesen("SELECT id FROM notizen WHERE id=?", (nummer,))
        if not vorher:
            return False
        self._schreiben("DELETE FROM notizen WHERE id=?", (nummer,))
        return True

    # -- Kontakte -----------------------------------------------------------

    def kontakt_anlegen(self, name: str, firma: str = "", telefon: str = "",
                        email: str = "", adresse: str = "", notiz: str = "") -> dict:
        """Legt einen Kontakt an oder ergänzt einen bereits vorhandenen."""
        name = (name or "").strip()
        if not name:
            return {"ok": False, "fehler": "Ohne Namen kann ich keinen Kontakt anlegen."}
        vorhanden = self._lesen(
            "SELECT * FROM kontakte WHERE lower(name)=lower(?) LIMIT 1", (name,))
        if vorhanden:
            alt = vorhanden[0]
            neu = {
                "firma": firma or alt["firma"],
                "telefon": telefon or alt["telefon"],
                "email": email or alt["email"],
                "adresse": adresse or alt["adresse"],
                "notiz": (alt["notiz"] + " | " + notiz).strip(" |") if notiz else alt["notiz"],
            }
            self._schreiben(
                "UPDATE kontakte SET firma=?, telefon=?, email=?, adresse=?, notiz=? "
                "WHERE id=?",
                (neu["firma"], neu["telefon"], neu["email"], neu["adresse"],
                 neu["notiz"], alt["id"]))
            return {"ok": True, "id": alt["id"], "name": name, "aktualisiert": True}
        nummer = self._schreiben(
            "INSERT INTO kontakte (name, firma, telefon, email, adresse, notiz, angelegt) "
            "VALUES (?,?,?,?,?,?,?)",
            (name, firma, telefon, email, adresse, notiz, zeitstempel()))
        self._spiegeln("kontakte", {"name": name, "firma": firma})
        return {"ok": True, "id": nummer, "name": name, "aktualisiert": False}

    def kontakt_suchen(self, begriff: str, limit: int = 20) -> list:
        """Sucht Kontakte über Name, Firma, Telefon, E-Mail oder Notiz."""
        begriff = (begriff or "").strip()
        if not begriff:
            return self._lesen("SELECT * FROM kontakte ORDER BY name LIMIT ?", (limit,))
        muster = "%%%s%%" % begriff
        return self._lesen(
            "SELECT * FROM kontakte WHERE name LIKE ? OR firma LIKE ? OR telefon LIKE ? "
            "OR email LIKE ? OR notiz LIKE ? ORDER BY name LIMIT ?",
            (muster, muster, muster, muster, muster, limit))

    def kontakte_alle(self) -> list:
        """Alle Kontakte, alphabetisch."""
        return self._lesen("SELECT * FROM kontakte ORDER BY name")

    # -- Kennzahlen ---------------------------------------------------------

    def kennzahl_setzen(self, name: str, wert: float, einheit: str = "") -> dict:
        """Hält eine Kennzahl mit Datum fest (Verlauf bleibt erhalten)."""
        try:
            wert = float(wert)
        except (TypeError, ValueError):
            return {"ok": False, "fehler": "Der Wert ist keine Zahl."}
        nummer = self._schreiben(
            "INSERT INTO kennzahlen (name, wert, einheit, datum) VALUES (?,?,?,?)",
            (name, wert, einheit, heute_datum()))
        return {"ok": True, "id": nummer, "name": name, "wert": wert, "einheit": einheit}

    def kennzahlen(self, limit: int = 30) -> list:
        """Der jeweils jüngste Stand jeder Kennzahl."""
        return self._lesen(
            "SELECT name, wert, einheit, datum FROM kennzahlen k WHERE id = "
            "(SELECT max(id) FROM kennzahlen WHERE name = k.name) "
            "ORDER BY name LIMIT ?", (limit,))

    # -- Offene Punkte ------------------------------------------------------

    def punkt_anlegen(self, text: str, faellig: str = "") -> dict:
        """Merkt sich etwas, das noch zu erledigen ist."""
        text = (text or "").strip()
        if not text:
            return {"ok": False, "fehler": "Der offene Punkt ist leer."}
        nummer = self._schreiben(
            "INSERT INTO offene_punkte (text, faellig, erledigt, angelegt) VALUES (?,?,0,?)",
            (text, faellig, zeitstempel()))
        return {"ok": True, "id": nummer, "text": text, "faellig": faellig}

    def punkte_offen(self, tage: int = 14, limit: int = 25) -> list:
        """Offene Punkte der letzten ``tage`` Tage."""
        grenze = (datetime.now() - timedelta(days=tage)).strftime("%Y-%m-%d 00:00:00")
        return self._lesen(
            "SELECT * FROM offene_punkte WHERE erledigt=0 AND angelegt>=? "
            "ORDER BY id DESC LIMIT ?", (grenze, limit))

    def punkt_erledigen(self, nummer: int) -> bool:
        """Hakt einen offenen Punkt ab."""
        vorher = self._lesen("SELECT id FROM offene_punkte WHERE id=? AND erledigt=0",
                             (nummer,))
        if not vorher:
            return False
        self._schreiben("UPDATE offene_punkte SET erledigt=1 WHERE id=?", (nummer,))
        return True

    # -- Protokoll ----------------------------------------------------------

    def aktion_protokollieren(self, werkzeug: str, argumente=None, ergebnis: str = "",
                              status: str = "ok") -> int:
        """Schreibt jede ausgeführte Aktion mit - Grundlage für das Dashboard."""
        try:
            argument_text = json.dumps(argumente, ensure_ascii=False)[:2000]
        except (TypeError, ValueError):
            argument_text = str(argumente)[:2000]
        return self._schreiben(
            "INSERT INTO aktionen (werkzeug, argumente, ergebnis, status, zeit) "
            "VALUES (?,?,?,?,?)",
            (werkzeug, argument_text, str(ergebnis)[:2000], status, zeitstempel()))

    def protokoll(self, limit: int = 30) -> list:
        """Die zuletzt ausgeführten Aktionen."""
        return self._lesen("SELECT * FROM aktionen ORDER BY id DESC LIMIT ?", (limit,))

    # -- Gesprächsverlauf ---------------------------------------------------

    def verlauf_anhaengen(self, rolle: str, text: str) -> int:
        """Hängt eine Äußerung an den dauerhaften Verlauf an."""
        return self._schreiben(
            "INSERT INTO verlauf (rolle, text, zeit) VALUES (?,?,?)",
            (rolle, (text or "")[:8000], zeitstempel()))

    def verlauf_letzte(self, limit: int = 20) -> list:
        """Die letzten Äußerungen, in zeitlicher Reihenfolge."""
        zeilen = self._lesen("SELECT * FROM verlauf ORDER BY id DESC LIMIT ?", (limit,))
        return list(reversed(zeilen))

    def aeusserungen_suchen(self, begriff: str, limit: int = 8) -> list:
        """Sucht in früheren Äußerungen des Nutzers."""
        begriff = (begriff or "").strip()
        if not begriff:
            return []
        return self._lesen(
            "SELECT * FROM verlauf WHERE rolle='user' AND text LIKE ? "
            "ORDER BY id DESC LIMIT ?", ("%%%s%%" % begriff, limit))

    # -- Übersicht ----------------------------------------------------------

    def statistik(self) -> dict:
        """Zählt, was im Gedächtnis liegt."""
        ergebnis = {}
        for tabelle in ("notizen", "kontakte", "kennzahlen", "aktionen", "verlauf"):
            try:
                zeilen = self._lesen("SELECT count(*) AS n FROM %s" % tabelle)
                ergebnis[tabelle] = zeilen[0]["n"] if zeilen else 0
            except sqlite3.Error:
                ergebnis[tabelle] = 0
        ergebnis["offene_punkte"] = len(self.punkte_offen())
        return ergebnis

    # -- Optionale Spiegelung ----------------------------------------------

    def _spiegeln(self, tabelle: str, daten: dict):
        """Spiegelt einen Datensatz nach Supabase - scheitert lautlos, nie blockierend."""
        if not (SUPABASE_URL and SUPABASE_KEY):
            return
        try:
            ziel = "%s/rest/v1/%s" % (SUPABASE_URL.rstrip("/"), tabelle)
            anfrage = urllib.request.Request(
                ziel, data=json.dumps(daten).encode("utf-8"), method="POST",
                headers={
                    "apikey": SUPABASE_KEY,
                    "Authorization": "Bearer %s" % SUPABASE_KEY,
                    "Content-Type": "application/json",
                    "Prefer": "return=minimal",
                })
            urllib.request.urlopen(anfrage, timeout=5).read()
        except (urllib.error.URLError, OSError, ValueError):
            pass


# =========================================================================
# router  -  Der Router - welches Gehirn antwortet, und was es gekostet hat.
# 
# Zwei Gehirne: **Gemini** ist schnell und im Free Tier gratis, **Claude** kann
# die Werkzeuge bedienen (Buchhaltung, Kalender, Post, Telefon ...) und denkt
# gründlicher. Der Router entscheidet pro Frage mit festen, nachvollziehbaren
# Regeln - kein Modell raten lassen, was ein Modell kosten darf.
# 
# **Im Zweifel Claude.** Gemini bekommt hier keine Werkzeuge und kein Gedächtnis
# für den Betrieb. Deshalb geht nur reiner Smalltalk an Gemini ("Hallo", "Danke",
# "Wie geht's?"). Alles andere - Angebote, Kunden, Programmieren, Fragen jeder Art -
# beantwortet Claude, der etwas tun kann. Vorher landete "Programmier mir einen
# Chatbot" bei Gemini, weil kein Stichwort passte, und die Antwort blieb leer.
# 
# **Antworten gehören dem, der gefragt hat.** Hat Claude gerade etwas gefragt
# oder getan, ist "Ja", "Genau" oder "Und morgen?" die Antwort darauf - das geht
# an Claude, der das Gespräch kennt. Nur ein reines "Danke" oder "Tschüss" nach
# einer fertigen Antwort darf noch an Gemini.
# 
# Jede Runde landet im **Gedankenlog** (``logs/gedankenlog.jsonl``): Frage,
# Gehirn, Dauer, Tokens, geschätzte Kosten. Daraus rechnet sich der
# Monatsverbrauch, an dem das Limit hängt.
# =========================================================================

#!/usr/bin/env python3
# -*- coding: utf-8 -*-



GEMINI_URL = "https://generativelanguage.googleapis.com/v1beta/models/%s:generateContent"
LOG_DATEI_NAME = "gedankenlog.jsonl"

# Wortstämme, hinter denen eine Handlung oder ein Datenzugriff stecken kann.
# Gemini kann das nicht ausführen - also geht es an Claude.
HANDLUNGSSTAEMME = (
    "termin", "kalender", "mail", "post", "nachricht", "sms", "anruf", "ruf ",
    "telefon", "telegram", "buch", "rechnung", "beleg", "quittung", "umsatz",
    "kasse", "steuer", "euro", "kunde", "kunden", "lead", "angebot", "auftrag",
    "aufgabe", "notiz", "merk", "vergiss", "speicher", "erinner", "lösch",
    "send", "schick", "schreib", "öffne", "browser", "such", "flug", "wetter",
    "bild", "kamera", "datei", "ordner", "dashboard", "briefing", "heute",
    "morgen", "woche", "offen", "mitarbeiter", "team",
)
# Smalltalk - nur wenn JEDES Wort von hier ist, antwortet Gemini.
# "Hallo, finde Firmen in Wien" ist kein Smalltalk, "Hallo Jarvis, wie geht's" schon.
SMALLTALK_WOERTER = {
    "hallo", "hi", "hey", "servus", "grüß", "gruess", "gott", "moin", "guten", "gute",
    "tag", "abend", "nacht", "danke", "dankeschön", "vielen", "dank", "wie",
    "geht", "gehts", "s", "es", "dir", "euch", "alles", "klar", "tschüss", "tschuess",
    "ciao", "bis", "später", "dann", "wer", "bist", "du", "erzähl", "erzähle", "mir",
    "einen", "witz", "super", "passt", "okay", "ok", "cool", "genau", "gut", "gemacht",
    "jarvis", "davis", "und", "ja", "nein", "schön", "toll", "bitte", "was", "machst",
    "na", "so", "lieber", "mein", "freund", "hab", "habe", "dich", "lieb",
}
# Nach einer Antwort von Claude geht nur noch an Gemini, was keine Antwort sein kann.
ABSCHLUSS_WOERTER = {
    "hallo", "hi", "hey", "servus", "danke", "dankeschön", "vielen", "dank", "tschüss",
    "tschuess", "ciao", "bis", "später", "gute", "nacht", "jarvis", "davis", "lieber",
    "mein", "freund", "dir", "sehr", "schön",
}
# Wörter, die auf echte Denkarbeit hindeuten.
DENKSTAEMME = (
    "plane", "planen", "analysier", "rechne", "berechne", "strategie",
    "vergleich", "kalkulier", "begründ", "warum", "denk gründlich",
    "denk gruendlich", "gründlich", "gruendlich",
)


def gehirn_waehlen(frage: str, gemini_da: bool = None, vorher: str = None) -> tuple:
    """Gibt ``(gehirn, grund)`` zurück: ``"gemini"`` oder ``"claude"``.

    ``vorher`` ist der Text der Claude-Antwort direkt davor (``None``: davor
    sprach nicht Claude). Fragte Claude etwas, gehört jede Antwort ihm.
    """
    if gemini_da is None:
        gemini_da = bool(GEMINI_API_KEY)
    text = (frage or "").strip().lower()
    if not gemini_da:
        return "claude", "kein Gemini-Schlüssel"
    if not text:
        return "claude", "leere Frage"
    # "Guten Morgen" ist ein Gruß, "Morgen" allein meint den Kalender.
    woerter = re.findall(r"[a-zäöüß0-9]+", re.sub(r"\bguten\s+morgen\b", "hallo", text))
    if vorher is not None and (vorher.rstrip().endswith("?")
                               or not all(w in ABSCHLUSS_WOERTER for w in woerter)):
        return "claude", "Antwort auf Claude"
    if woerter and len(woerter) <= ROUTER_MAX_WOERTER \
            and all(w in SMALLTALK_WOERTER for w in woerter):
        return "gemini", "Smalltalk"
    for stamm in DENKSTAEMME:
        if stamm in text:
            return "claude", "Denkarbeit (%s)" % stamm.strip()
    for stamm in HANDLUNGSSTAEMME:
        if stamm in text:
            return "claude", "braucht Werkzeuge (%s)" % stamm.strip()
    return "claude", "im Zweifel Claude"


# -- Gemini -----------------------------------------------------------------

def gemini_fragen(frage: str, systemtext: str, verlauf: list = None,
                  timeout: int = 30) -> dict:
    """Fragt Gemini. Rückgabe: ``{"ok", "text", "tokens_ein", "tokens_aus"}``.

    Der Verlauf ist die Claude-Liste; übernommen wird nur Text - auch der
    Text aus Claudes Antworten. Werkzeugaufrufe und Ergebnisse bleiben draußen.
    """
    if not GEMINI_API_KEY:
        return {"ok": False, "fehler": "Kein Gemini-Schlüssel hinterlegt."}
    inhalte = []
    for nachricht in (verlauf or [])[-10:]:
        text = nachricht.get("content")
        if isinstance(text, list) and nachricht.get("role") == "assistant":
            text = "\n".join(b.get("text", "") for b in text
                             if isinstance(b, dict) and b.get("type") == "text")
        if isinstance(text, str) and text.strip():
            rolle = "user" if nachricht.get("role") == "user" else "model"
            if inhalte and inhalte[-1]["role"] == rolle:
                inhalte[-1]["parts"][0]["text"] += "\n" + text
            else:
                inhalte.append({"role": rolle, "parts": [{"text": text}]})
    if inhalte and inhalte[-1]["role"] == "user":
        inhalte.pop()  # die aktuelle Frage kommt gleich noch einmal
    inhalte.append({"role": "user", "parts": [{"text": frage}]})
    while inhalte and inhalte[0]["role"] != "user":
        inhalte.pop(0)

    koerper = {"systemInstruction": {"parts": [{"text": systemtext}]},
               "contents": inhalte,
               "generationConfig": {"maxOutputTokens": GEMINI_MAX_TOKENS}}
    anfrage = urllib.request.Request(
        GEMINI_URL % GEMINI_MODELL, data=json.dumps(koerper).encode("utf-8"),
        method="POST", headers={"x-goog-api-key": GEMINI_API_KEY,
                                "content-type": "application/json"})
    try:
        with urllib.request.urlopen(anfrage, timeout=timeout) as antwort:
            daten = json.loads(antwort.read().decode("utf-8"))
    except urllib.error.HTTPError as fehler:
        return {"ok": False, "limit": fehler.code == 429,
                "fehler": "Gemini meldet Fehler %d." % fehler.code}
    except (urllib.error.URLError, OSError, ValueError) as fehler:
        return {"ok": False, "fehler": "Gemini nicht erreichbar: %s" % fehler}

    kandidaten = daten.get("candidates") or []
    teile = ((kandidaten[0].get("content") or {}).get("parts") or []) if kandidaten else []
    text = "".join(t.get("text", "") for t in teile).strip()
    if not text:
        return {"ok": False, "fehler": "Gemini hat nichts geantwortet."}
    nutzung = daten.get("usageMetadata") or {}
    return {"ok": True, "text": text,
            "tokens_ein": int(nutzung.get("promptTokenCount", 0)),
            "tokens_aus": int(nutzung.get("candidatesTokenCount", 0))}


def gemini_testen(schluessel: str) -> dict:
    """Prüft einen Gemini-Schlüssel mit einem echten Mini-Aufruf."""
    alt = GEMINI_API_KEY
    GEMINI_API_KEY = schluessel
    try:
        antwort = gemini_fragen("Sag nur: ok", "Antworte mit einem Wort.", timeout=30)
    finally:
        GEMINI_API_KEY = alt
    if antwort.get("ok"):
        return {"ok": True, "text": "Der Gemini-Schlüssel funktioniert."}
    fehler = antwort.get("fehler", "")
    if "400" in fehler or "403" in fehler:
        text = "Der Schlüssel wird abgelehnt. Bitte noch einmal vollständig kopieren."
    elif "404" in fehler:
        text = ("Das Modell %s kennt Google nicht (mehr). Trag in der Konfiguration "
                "ein anderes ein: GEMINI_MODELL." % GEMINI_MODELL)
    elif antwort.get("limit"):
        text = "Der Schlüssel stimmt, Google meldet aber gerade das Limit."
    else:
        text = fehler or "Die Prüfung ist fehlgeschlagen."
    return {"ok": False, "limit": bool(antwort.get("limit")), "text": text}


# -- Gedankenlog ------------------------------------------------------------

def claude_kosten(tokens_ein: int, tokens_aus: int, gelesen: int = 0, geschrieben: int = 0) -> float:
    """Geschätzte Kosten einer Claude-Anfrage in Euro.

    ``gelesen`` und ``geschrieben`` sind Tokens aus und in den Zwischenspeicher:
    gelesen hat einen eigenen Preis (``CLAUDE_PREIS_GELESEN``, bei Opus 5.5 ein
    Zwanzigstel), geschrieben kostet ein Viertel mehr als normal.
    """
    eingang = tokens_ein + 1.25 * geschrieben
    dollar = (eingang * CLAUDE_PREIS_EIN + gelesen * CLAUDE_PREIS_GELESEN
              + tokens_aus * CLAUDE_PREIS_AUS) / 1_000_000
    return round(dollar * DOLLAR_IN_EURO, 6)


class Gedankenlog:
    """Protokoll jeder Runde - und Quelle für Monatsverbrauch und Limit."""

    def __init__(self, datei=None):
        self.datei = datei or (LOG_VERZEICHNIS / LOG_DATEI_NAME)

    def eintragen(self, frage: str, gehirn: str, grund: str, dauer: float,
                  tokens_ein: int = 0, tokens_aus: int = 0, kosten: float = 0.0,
                  ausgewichen: bool = False) -> None:
        zeile = {"zeit": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
                 "frage": (frage or "")[:120], "gehirn": gehirn, "grund": grund,
                 "dauer": round(dauer, 2), "tokens_ein": tokens_ein,
                 "tokens_aus": tokens_aus, "kosten": round(kosten, 6),
                 "ausgewichen": ausgewichen}
        try:
            self.datei.parent.mkdir(parents=True, exist_ok=True)
            with open(self.datei, "a", encoding="utf-8") as datei:
                datei.write(json.dumps(zeile, ensure_ascii=False) + "\n")
        except OSError as fehler:
            print("[gedankenlog] nicht schreibbar: %s" % fehler)

    def zeilen(self, monat: str = "") -> list:
        """Alle Einträge, auf Wunsch nur die eines Monats (``2026-10``)."""
        ergebnis = []
        try:
            with open(self.datei, encoding="utf-8") as datei:
                for rohzeile in datei:
                    try:
                        zeile = json.loads(rohzeile)
                    except ValueError:
                        continue
                    if not monat or str(zeile.get("zeit", "")).startswith(monat):
                        ergebnis.append(zeile)
        except OSError:
            pass
        return ergebnis

    def monatsbilanz(self, monat: str = "") -> dict:
        """Anfragen und Kosten je Gehirn im Monat (Standard: der laufende)."""
        monat = monat or datetime.now().strftime("%Y-%m")
        bilanz = {"monat": monat, "kosten": 0.0, "anfragen": 0,
                  "gemini": 0, "claude": 0, "ausgewichen": 0}
        for zeile in self.zeilen(monat):
            bilanz["anfragen"] += 1
            gehirn = zeile.get("gehirn")
            if gehirn in ("gemini", "claude"):
                bilanz[gehirn] += 1
            bilanz["kosten"] += float(zeile.get("kosten", 0) or 0)
            bilanz["ausgewichen"] += 1 if zeile.get("ausgewichen") else 0
        bilanz["kosten"] = round(bilanz["kosten"], 4)
        return bilanz

    def limit_erreicht(self) -> bool:
        """Hat Claude das Monatslimit aufgebraucht?"""
        if MONATSLIMIT_EURO <= 0:
            return False
        return self.monatsbilanz()["kosten"] >= MONATSLIMIT_EURO


# =========================================================================
# recall  -  Gedächtnis, Ebene 1 und 2 - Tagesberichte und gezieltes Nachschlagen.
# 
# Warum zwei Ebenen? Ein Verlauf von Monaten passt in kein Kontextfenster und
# macht jede Antwort langsam und teuer. Deshalb:
# 
# * Ebene 1: Abends fasst Jarvis den Tag in wenigen Sätzen zusammen. Viele
#   solcher Berichte passen gleichzeitig in den Systemprompt.
# * Ebene 2: Vor jeder Antwort werden die tragenden Wörter der Frage in Notizen,
#   Kontakten, Tagesberichten und früheren Äußerungen nachgeschlagen. Nur die
#   Treffer werden beigelegt.
# =========================================================================

#!/usr/bin/env python3
# -*- coding: utf-8 -*-



SCHEMA_RECALL = """
CREATE TABLE IF NOT EXISTS tagesberichte (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    datum TEXT NOT NULL,
    zusammenfassung TEXT NOT NULL,
    entscheidungen TEXT DEFAULT '',
    offen TEXT DEFAULT '',
    angelegt TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_berichte_datum ON tagesberichte(datum);
"""

# Wörter, die in fast jedem Satz vorkommen und deshalb nichts einengen.
STOPPWOERTER_recall = {
    "aber", "alle", "allem", "allen", "aller", "alles", "also", "andere", "auch",
    "auf", "aus", "bei", "beim", "bin", "bis", "bist", "dann", "dass", "dein",
    "deine", "dem", "den", "denn", "der", "des", "dich", "die", "dies", "diese",
    "diesem", "diesen", "dieser", "dieses", "dir", "doch", "dort", "durch",
    "ein", "eine", "einem", "einen", "einer", "eines", "einfach", "etwas",
    "euch", "euer", "eure", "für", "fuer", "gegen", "gewesen", "hab", "habe",
    "haben", "hat", "hatte", "hatten", "hier", "hin", "ich", "ihm", "ihn",
    "ihnen", "ihr", "ihre", "immer", "ist", "jede", "jedem", "jeden", "jeder",
    "jetzt", "kann", "kannst", "können", "koennen", "machen", "mehr", "mein",
    "meine", "mich", "mir", "mit", "muss", "musst", "müssen", "muessen", "nach",
    "nicht", "noch", "nun", "nur", "oben", "oder", "ohne", "schon", "sehr",
    "sein", "seine", "seit", "sich", "sie", "sind", "soll", "sollen", "sondern",
    "sonst", "über", "ueber", "und", "uns", "unser", "unter", "vom", "von",
    "vor", "war", "waren", "warum", "was", "weg", "weil", "weiter", "welche",
    "wenn", "werde", "werden", "wie", "wieder", "will", "wir", "wird", "wirst",
    "wo", "wollen", "wurde", "wurden", "zum", "zur", "zwar", "zwischen",
    "steht", "gibt", "geht", "mach", "sage", "sagen", "bitte", "danke", "jarvis",
}


def schluesselwoerter(text: str, mindestlaenge: int = 4) -> list:
    """Zerlegt einen Satz in seine tragenden Wörter (ab 4 Zeichen, ohne Stoppwörter)."""
    if not text:
        return []
    roh = re.findall(r"[0-9A-Za-zÄÖÜäöüß_-]+", str(text).lower())
    treffer = []
    for wort in roh:
        if len(wort) < mindestlaenge:
            continue
        if wort in STOPPWOERTER_recall:
            continue
        if wort not in treffer:
            treffer.append(wort)
    return treffer[:12]


class Recall:
    """Langzeitgedächtnis: schreibt Tagesberichte und schlägt gezielt nach."""

    def __init__(self, memory: Memory = None):
        self.memory = memory or Memory()
        db_schema_anlegen(SCHEMA_RECALL, self.memory.db_pfad)

    # -- Ebene 1: Tagesberichte --------------------------------------------

    def tagesbericht_speichern(self, zusammenfassung: str, entscheidungen: str = "",
                               offen: str = "", datum: str = "") -> dict:
        """Legt den Bericht eines Tages ab (ein Bericht pro Datum)."""
        zusammenfassung = (zusammenfassung or "").strip()
        if not zusammenfassung:
            return {"ok": False, "fehler": "Der Tagesbericht ist leer."}
        datum = (datum or heute_datum()).strip()
        vorhanden = self.memory._lesen(
            "SELECT id FROM tagesberichte WHERE datum=? LIMIT 1", (datum,))
        if vorhanden:
            self.memory._schreiben(
                "UPDATE tagesberichte SET zusammenfassung=?, entscheidungen=?, offen=?, "
                "angelegt=? WHERE id=?",
                (zusammenfassung, entscheidungen, offen, zeitstempel(), vorhanden[0]["id"]))
            return {"ok": True, "id": vorhanden[0]["id"], "datum": datum, "ersetzt": True}
        nummer = self.memory._schreiben(
            "INSERT INTO tagesberichte (datum, zusammenfassung, entscheidungen, offen, angelegt) "
            "VALUES (?,?,?,?,?)",
            (datum, zusammenfassung, entscheidungen, offen, zeitstempel()))
        return {"ok": True, "id": nummer, "datum": datum, "ersetzt": False}

    def tagesberichte_letzte(self, anzahl: int = 7) -> list:
        """Die jüngsten Tagesberichte, neuester zuerst."""
        return self.memory._lesen(
            "SELECT * FROM tagesberichte ORDER BY datum DESC, id DESC LIMIT ?", (anzahl,))

    def tagesberichte_suchen(self, begriff: str, limit: int = 6) -> list:
        """Sucht in Tagesberichten nach einem Begriff."""
        begriff = (begriff or "").strip()
        if not begriff:
            return []
        muster = "%%%s%%" % begriff
        return self.memory._lesen(
            "SELECT * FROM tagesberichte WHERE zusammenfassung LIKE ? OR entscheidungen LIKE ? "
            "OR offen LIKE ? ORDER BY datum DESC LIMIT ?", (muster, muster, muster, limit))

    # -- Ebene 2: Nachschlagen ---------------------------------------------

    def nachschlagen(self, frage: str, pro_quelle: int = 4) -> dict:
        """Sucht die tragenden Wörter einer Frage in allen Gedächtnisquellen."""
        woerter = schluesselwoerter(frage)
        gefunden = {"woerter": woerter, "notizen": [], "kontakte": [],
                    "berichte": [], "aeusserungen": []}
        if not woerter:
            return gefunden
        gesehen = {"notizen": set(), "kontakte": set(), "berichte": set(),
                   "aeusserungen": set()}
        for wort in woerter:
            for notiz in self.memory.notizen_suchen(wort, pro_quelle):
                if notiz["id"] not in gesehen["notizen"]:
                    gesehen["notizen"].add(notiz["id"])
                    gefunden["notizen"].append(notiz)
            for kontakt in self.memory.kontakt_suchen(wort, pro_quelle):
                if kontakt["id"] not in gesehen["kontakte"]:
                    gesehen["kontakte"].add(kontakt["id"])
                    gefunden["kontakte"].append(kontakt)
            for bericht in self.tagesberichte_suchen(wort, pro_quelle):
                if bericht["id"] not in gesehen["berichte"]:
                    gesehen["berichte"].add(bericht["id"])
                    gefunden["berichte"].append(bericht)
            for zeile in self.memory.aeusserungen_suchen(wort, pro_quelle):
                if zeile["id"] not in gesehen["aeusserungen"]:
                    gesehen["aeusserungen"].add(zeile["id"])
                    gefunden["aeusserungen"].append(zeile)
        for schluessel in ("notizen", "kontakte", "berichte", "aeusserungen"):
            gefunden[schluessel] = gefunden[schluessel][:8]
        return gefunden

    def gedaechtnis_block(self, frage: str = "") -> str:
        """Baut den Gedächtnisteil des Systemprompts.

        Enthält immer die offenen Punkte der letzten 14 Tage und die letzten
        Tagesberichte, dazu die zur Frage passenden Treffer.
        """
        teile = []

        punkte = self.memory.punkte_offen(tage=14)
        if punkte:
            zeilen = ["Offene Punkte der letzten 14 Tage:"]
            for punkt in punkte[:12]:
                faellig = (" (fällig %s)" % punkt["faellig"]) if punkt["faellig"] else ""
                zeilen.append("- [%d] %s%s" % (punkt["id"], punkt["text"], faellig))
            teile.append("\n".join(zeilen))

        berichte = self.tagesberichte_letzte(7)
        if berichte:
            zeilen = ["Was an den letzten Tagen war:"]
            for bericht in berichte:
                satz = "- %s: %s" % (bericht["datum"], bericht["zusammenfassung"])
                if bericht["offen"]:
                    satz += " Noch offen: %s" % bericht["offen"]
                zeilen.append(satz)
            teile.append("\n".join(zeilen))

        treffer = self.treffer_block(frage) if frage else ""
        if treffer:
            teile.append(treffer)

        if not teile:
            return ""
        return "Das weißt du aus früheren Tagen:\n\n" + "\n\n".join(teile)

    def treffer_block(self, frage: str) -> str:
        """Was das Gedächtnis zu genau dieser Frage weiß - leer, wenn nichts passt.

        Gehört in die Nachricht, nicht in den Systemprompt: Der bleibt so von
        Frage zu Frage gleich, und der Zwischenspeicher kann ihn lesen.
        """
        if not frage:
            return ""
        treffer = self.nachschlagen(frage)
        zeilen = []
        for notiz in treffer["notizen"]:
            zeilen.append("- Notiz vom %s: %s" % (notiz["angelegt"][:10], notiz["text"]))
        for kontakt in treffer["kontakte"]:
            beschreibung = ", ".join(
                [t for t in (kontakt["firma"], kontakt["telefon"], kontakt["email"],
                             kontakt["notiz"]) if t])
            zeilen.append("- Kontakt %s: %s" % (kontakt["name"], beschreibung or "keine Details"))
        for bericht in treffer["berichte"]:
            zeilen.append("- Tagesbericht %s: %s" % (bericht["datum"],
                                                     bericht["zusammenfassung"]))
        for zeile in treffer["aeusserungen"]:
            zeilen.append("- Er sagte am %s: %s" % (zeile["zeit"][:10], zeile["text"][:200]))
        if not zeilen:
            return ""
        return "Passend zur aktuellen Frage:\n" + "\n".join(zeilen[:14])

    # -- Tag zusammenfassen -------------------------------------------------

    def tag_zusammenfassen(self, agent=None, datum: str = "") -> dict:
        """Fasst den heutigen Tag zusammen - mit Claude, sonst mechanisch."""
        datum = datum or heute_datum()
        beginn = "%s 00:00:00" % datum
        ende = "%s 23:59:59" % datum

        aeusserungen = self.memory._lesen(
            "SELECT rolle, text, zeit FROM verlauf WHERE zeit BETWEEN ? AND ? ORDER BY id",
            (beginn, ende))
        aktionen = self.memory._lesen(
            "SELECT werkzeug, status, zeit FROM aktionen WHERE zeit BETWEEN ? AND ? ORDER BY id",
            (beginn, ende))
        punkte = self.memory.punkte_offen(tage=1)

        if not aeusserungen and not aktionen:
            bericht = "An diesem Tag ist nichts festgehalten worden."
            self.tagesbericht_speichern(bericht, "", "", datum)
            return {"ok": True, "datum": datum, "zusammenfassung": bericht, "quelle": "leer"}

        rohtext = []
        for zeile in aeusserungen[-60:]:
            rohtext.append("%s: %s" % ("Er" if zeile["rolle"] == "user" else "Jarvis",
                                       zeile["text"][:400]))
        werkzeugliste = ", ".join(sorted({a["werkzeug"] for a in aktionen})) or "keine"

        if agent is not None and getattr(agent, "einsatzbereit", lambda: False)():
            auftrag = (
                "Fasse diesen Arbeitstag für dein eigenes Gedächtnis zusammen. "
                "Antworte als JSON mit den Schlüsseln zusammenfassung, entscheidungen, offen. "
                "zusammenfassung: drei bis fünf Sätze, worum es ging. "
                "entscheidungen: was entschieden wurde, ein Satz oder leer. "
                "offen: was offen blieb, ein Satz oder leer.\n\n"
                "Gespräche des Tages:\n%s\n\nBenutzte Werkzeuge: %s"
                % ("\n".join(rohtext) or "keine", werkzeugliste))
            antwort = agent.json_anfrage(auftrag)
            if antwort.get("ok"):
                daten = antwort["daten"]
                self.tagesbericht_speichern(
                    str(daten.get("zusammenfassung", "")).strip(),
                    str(daten.get("entscheidungen", "")).strip(),
                    str(daten.get("offen", "")).strip(), datum)
                return {"ok": True, "datum": datum, "quelle": "claude",
                        "zusammenfassung": daten.get("zusammenfassung", ""),
                        "entscheidungen": daten.get("entscheidungen", ""),
                        "offen": daten.get("offen", "")}

        # Rückfallebene ohne Claude: mechanisch, aber ehrlich.
        themen = []
        for zeile in aeusserungen:
            if zeile["rolle"] != "user":
                continue
            for wort in schluesselwoerter(zeile["text"])[:3]:
                if wort not in themen:
                    themen.append(wort)
        zusammenfassung = ("%d Gespräche, %d Aktionen. Themen: %s."
                           % (len([z for z in aeusserungen if z["rolle"] == "user"]),
                              len(aktionen), ", ".join(themen[:10]) or "keine erkennbaren"))
        offen_text = "; ".join(p["text"] for p in punkte[:5])
        self.tagesbericht_speichern(zusammenfassung, "", offen_text, datum)
        return {"ok": True, "datum": datum, "quelle": "mechanisch",
                "zusammenfassung": zusammenfassung, "entscheidungen": "", "offen": offen_text}

    def rueckblick(self, tage: int = 7) -> str:
        """Ein zusammenhängender Text über die letzten Tage - für den Wochenrückblick."""
        grenze = (datetime.now() - timedelta(days=tage)).strftime("%Y-%m-%d")
        berichte = self.memory._lesen(
            "SELECT * FROM tagesberichte WHERE datum>=? ORDER BY datum", (grenze,))
        if not berichte:
            return "Für die letzten %d Tage liegen noch keine Tagesberichte vor." % tage
        zeilen = []
        for bericht in berichte:
            zeilen.append("%s: %s" % (bericht["datum"], bericht["zusammenfassung"]))
            if bericht["entscheidungen"]:
                zeilen.append("   Entschieden: %s" % bericht["entscheidungen"])
            if bericht["offen"]:
                zeilen.append("   Offen: %s" % bericht["offen"])
        return "\n".join(zeilen)


# =========================================================================
# sprechtext  -  Sprechtext - aus geschriebenem Text wird Text, den ein Mensch so sagen würde.
# 
# Eine Stimme klingt nicht nur wegen des Klangs künstlich, sondern wegen dem,
# was sie vorliest. Wer "1.069,60 €" liest, sagt nicht "eins Punkt null sechs
# neun Komma sechzig Euro-Zeichen". Wer "z. B." liest, hält nicht an einem Punkt
# an. Und ein Text, der in einem Stück an die Sprachausgabe geht, stockt oder
# wiederholt sich gern mitten im Satz: lange Texte sind die häufigste Ursache
# für Aussetzer und Schleifen.
# 
# Deshalb drei Schritte, alle ohne Netz und ohne Abhängigkeiten:
# 
# 1. **Schreiben in Sprechen übersetzen**: Zahlen, Beträge, Daten, Uhrzeiten,
#    Einheiten und Abkürzungen werden ausgeschrieben, Markdown, Links und Code
#    fallen weg.
# 2. **In Atemabschnitte teilen**: kurze, in sich geschlossene Stücke, die an
#    Satzenden und Kommas trennen, nie mitten in einer Zahl.
# 3. **Schleifen abfangen**: ein Satz, der zweimal hintereinander kommt, oder
#    ein Wort, das dreimal hintereinander steht, wird einmal gesprochen.
# =========================================================================

#!/usr/bin/env python3
# -*- coding: utf-8 -*-


EINER = ["null", "ein", "zwei", "drei", "vier", "fünf", "sechs", "sieben", "acht",
         "neun", "zehn", "elf", "zwölf", "dreizehn", "vierzehn", "fünfzehn",
         "sechzehn", "siebzehn", "achtzehn", "neunzehn"]
ZEHNER = ["", "", "zwanzig", "dreißig", "vierzig", "fünfzig", "sechzig",
          "siebzig", "achtzig", "neunzig"]
MONATE = ["Januar", "Februar", "März", "April", "Mai", "Juni", "Juli", "August",
          "September", "Oktober", "November", "Dezember"]

ABKUERZUNGEN = [
    (r"\bz\.\s?B\.", "zum Beispiel"), (r"\bd\.\s?h\.", "das heißt"),
    (r"\bu\.\s?a\.", "unter anderem"), (r"\bu\.\s?U\.", "unter Umständen"),
    (r"\bv\.\s?a\.", "vor allem"), (r"\bs\.\s?o\.", "siehe oben"),
    (r"\busw\.", "und so weiter"), (r"\betc\.", "und so weiter"),
    (r"\bca\.", "circa"), (r"\bbzw\.", "beziehungsweise"),
    (r"\bevtl\.", "eventuell"), (r"\bggf\.", "gegebenenfalls"),
    (r"\binkl\.", "inklusive"), (r"\bexkl\.", "exklusive"),
    (r"\bmax\.", "maximal"), (r"\bNr\.", "Nummer"), (r"\bTel\.", "Telefon"),
    (r"\bStr\.", "Straße"), (r"\bMio\.", "Millionen"), (r"\bMrd\.", "Milliarden"),
    (r"\bvgl\.", "vergleiche"), (r"\bggü\.", "gegenüber"),
    (r"\bDr\.", "Doktor"), (r"\bProf\.", "Professor"), (r"\bHr\.", "Herr"),
    (r"\bFr\.", "Frau"),
]

# Einheit nach einer Zahl -> gesprochene Form. Nur direkt hinter Ziffern.
EINHEITEN = [
    (r"m²|m2|qm", "Quadratmeter", "Quadratmeter"), (r"km", "Kilometer", "Kilometer"),
    (r"kg", "Kilogramm", "Kilogramm"), (r"min", "Minuten", "Minute"),
    (r"Std\.?|h", "Stunden", "Stunde"), (r"cm", "Zentimeter", "Zentimeter"),
    (r"mm", "Millimeter", "Millimeter"), (r"l", "Liter", "Liter"),
]


# -- Zahlen -------------------------------------------------------------------

def _unter_hundert(n: int, eins_voll: bool) -> str:
    if n < 20:
        return "eins" if (n == 1 and eins_voll) else EINER[n]
    einer, zehner = n % 10, n // 10
    if einer == 0:
        return ZEHNER[zehner]
    return ("ein" if einer == 1 else EINER[einer]) + "und" + ZEHNER[zehner]


def _unter_tausend(n: int, eins_voll: bool) -> str:
    hunderter, rest = n // 100, n % 100
    teile = ""
    if hunderter:
        teile = ("ein" if hunderter == 1 else EINER[hunderter]) + "hundert"
    if rest:
        teile += _unter_hundert(rest, eins_voll)
    return teile


def zahl_wort(n: int) -> str:
    """Eine ganze Zahl als deutsches Zahlwort. ``1069`` -> ``eintausendneunundsechzig``."""
    n = int(n)
    if n < 0:
        return "minus " + zahl_wort(-n)
    if n == 0:
        return "null"
    teile = []
    for grenze, einzahl, mehrzahl in ((10**12, "eine Billion", "Billionen"),
                                      (10**9, "eine Milliarde", "Milliarden"),
                                      (10**6, "eine Million", "Millionen")):
        if n >= grenze:
            menge, n = divmod(n, grenze)
            teile.append(einzahl if menge == 1
                         else "%s %s" % (zahl_wort(menge), mehrzahl))
    text = " ".join(teile)
    tausend, rest = divmod(n, 1000)
    unten = ""
    if tausend:
        unten = ("ein" if tausend == 1 else _unter_tausend(tausend, False)) + "tausend"
    if rest:
        unten += _unter_tausend(rest, True)
    return (text + " " + unten).strip() if unten else text


def jahr_wort(jahr: int) -> str:
    """Jahreszahlen: 1985 -> neunzehnhundertfünfundachtzig, 2026 -> zweitausendsechsundzwanzig."""
    if 1100 <= jahr <= 1999:
        hundert, rest = divmod(jahr, 100)
        text = _unter_hundert(hundert, False) + "hundert"
        return text + (_unter_hundert(rest, True) if rest else "")
    return zahl_wort(jahr)


def tag_stamm(tag: int) -> str:
    """Stamm der Ordnungszahl: 1 -> erst, 3 -> dritt, 7 -> siebt, 20 -> zwanzigst."""
    sonder = {1: "erst", 3: "dritt", 7: "siebt", 8: "acht"}
    if tag in sonder:
        return sonder[tag]
    if tag < 20:
        return EINER[tag] + "t"
    return zahl_wort(tag) + "st"


def tag_wort(tag: int, davor: str = "") -> str:
    """Ein Datumstag gesprochen. Die Endung hängt vom Wort davor ab:
    "am sechsten", "der sechste", sonst "sechster"."""
    davor = (davor or "").lower().rstrip()
    if re.search(r"\b(am|vom|zum|dem|den|beim|ab|bis|zum|im)$", davor):
        endung = "en"
    elif re.search(r"\bder$", davor):
        endung = "e"
    else:
        endung = "er"
    return tag_stamm(tag) + endung


def _dezimal_wort(ganz: str, nachkomma: str) -> str:
    stellen = " ".join(EINER[int(z)] if z != "1" else "eins" for z in nachkomma)
    return "%s Komma %s" % (zahl_wort(int(ganz)), stellen)


def _zahl_aus(text: str) -> int:
    return int(text.replace(".", ""))


# -- Schreiben -> Sprechen --------------------------------------------------------

def _betrag(treffer) -> str:
    ganz = treffer.group("ganz")
    cent = treffer.group("cent")
    euro = _zahl_aus(ganz)
    wort = "%s Euro" % ("ein" if euro == 1 else zahl_wort(euro))
    if cent and int(cent):
        c = int(cent.ljust(2, "0")[:2])
        if euro == 0:
            return "%s Cent" % ("ein" if c == 1 else zahl_wort(c))
        return "%s %s" % (wort, zahl_wort(c))
    return wort


def _datum(treffer) -> str:
    tag, monat = int(treffer.group(1)), int(treffer.group(2))
    jahr = treffer.group(3)
    if not (1 <= tag <= 31 and 1 <= monat <= 12):
        return treffer.group(0)
    davor = treffer.string[max(0, treffer.start() - 12):treffer.start()]
    text = "%s %s" % (tag_wort(tag, davor), MONATE[monat - 1])
    if jahr:
        j = int(jahr)
        if j < 100:
            j += 1900 if j > 40 else 2000
        text += " " + jahr_wort(j)
        return text
    # "bis 12.10. Danach": der Punkt nach dem Monat war auch das Satzende.
    danach = treffer.string[treffer.end():]
    if not danach.strip() or re.match(r"\s+[A-ZÄÖÜ]", danach):
        text += "."
    return text


def _uhrzeit(treffer) -> str:
    stunde, minute = int(treffer.group(1)), int(treffer.group(2))
    if stunde > 24 or minute > 59:
        return treffer.group(0)
    text = "%s Uhr" % ("ein" if stunde == 1 else zahl_wort(stunde))
    return text + (" %s" % zahl_wort(minute) if minute else "")


def schreiben_zu_sprechen(text: str) -> str:
    """Wandelt Geschriebenes in Gesprochenes um. Siehe Modulkopf."""
    if not text:
        return ""
    t = str(text)

    # Code und Gliederung fallen weg
    t = re.sub(r"```.*?(```|$)", " Den Code zeige ich dir auf dem Bildschirm. ", t, flags=re.S)
    t = re.sub(r"`([^`]*)`", r"\1", t)
    t = re.sub(r"!\[[^\]]*\]\([^)]*\)", " ", t)
    t = re.sub(r"\[([^\]]*)\]\([^)]*\)", r"\1", t)
    t = re.sub(r"^\s{0,3}#{1,6}\s*", "", t, flags=re.M)
    t = re.sub(r"^\s*[-*•·]\s+", "", t, flags=re.M)
    t = re.sub(r"^\s*\d+[.)]\s+(?!(?:%s)\b)" % "|".join(MONATE), "", t, flags=re.M)
    t = re.sub(r"[*_~>]+", " ", t)
    t = re.sub(r"[\U0001F300-\U0001FAFF☀-➿️]", "", t)
    t = t.replace("|", ", ")
    # Jede Zeile ist ein eigener Gedanke: ohne Satzzeichen würde sie an die nächste kleben.
    zeilen = [z.strip() for z in t.splitlines() if z.strip()]
    t = " ".join(z if re.search(r"[.!?:;,]$", z) else z + "." for z in zeilen)

    # Links und Adressen
    t = re.sub(r"https?://(?:www\.)?([^\s/]+)\S*",
               lambda m: "ein Link zu " + m.group(1).replace(".", " Punkt "), t)
    t = re.sub(r"([\w.+-]+)@([\w-]+(?:\.[\w-]+)+)",
               lambda m: "%s ät %s" % (m.group(1).replace(".", " Punkt "),
                                      m.group(2).replace(".", " Punkt ")), t)

    # Daten, Uhrzeiten, Beträge, Prozent, Zahlen
    t = re.sub(r"\b(\d{1,2})\.(\d{1,2})\.(\d{4}|\d{2})?(?!\d)", _datum, t)
    # "3. März": ausgeschriebener Monat mit Ordnungszahl davor.
    t = re.sub(r"\b(\d{1,2})\.\s?(%s)\b" % "|".join(MONATE),
               lambda m: "%s %s" % (tag_wort(int(m.group(1)), m.string[max(0, m.start() - 12):m.start()]),
                                    m.group(2)) if 1 <= int(m.group(1)) <= 31 else m.group(0), t)
    t = re.sub(r"\b(\d{1,2}):(\d{2})(?:\s?Uhr)?\b", _uhrzeit, t)
    # "45 €/h", "130 km/h": der Schrägstrich ist ein "pro".
    pro = {"h": "Stunde", "std": "Stunde", "std.": "Stunde", "stunde": "Stunde", "m²": "Quadratmeter",
           "m2": "Quadratmeter", "qm": "Quadratmeter", "monat": "Monat", "tag": "Tag",
           "woche": "Woche", "stück": "Stück", "stk": "Stück", "stk.": "Stück"}
    t = re.sub(r"(\d)\s?km\s?/\s?h(?![\wäöüß])", r"\1 Kilometer pro Stunde", t)
    t = re.sub(r"(€|EUR|Euro)\s?/\s?(h|Std\.?|Stunde|m²|m2|qm|Monat|Tag|Woche|Stück|Stk\.?)(?![\wäöüß])",
               lambda m: "%s pro %s" % (m.group(1), pro.get(m.group(2).lower(), m.group(2))), t)
    # Ein Minus vor einem Betrag oder einer Prozentzahl wird gesprochen.
    t = re.sub(r"(?<![\w.,])[-−–]\s?(?=\d[\d.,]*\s?(?:€|EUR|Euro|%))", "minus ", t)
    betrag = r"(?P<ganz>\d{1,3}(?:\.\d{3})+|\d+)(?:,(?P<cent>\d{1,2}))?"
    t = re.sub(betrag + r"\s?(?:€|EUR|Euro)(?![\wäöüß])", _betrag, t)
    t = re.sub(r"(?:€|EUR)\s?" + betrag, _betrag, t)
    t = re.sub(r"(\d+(?:,\d+)?)\s?%",
               lambda m: re.sub(r"(\d+),(\d+)", lambda d: _dezimal_wort(d.group(1), d.group(2)),
                                m.group(1)) + " Prozent", t)
    for muster, mehrzahl, einzahl in EINHEITEN:
        t = re.sub(r"(?P<zahl>\d+(?:[.,]\d+)*)\s?(?:%s)(?![\wäöüß])" % muster,
                   lambda m, mz=mehrzahl, ez=einzahl: "%s %s" % (
                       m.group("zahl"), ez if m.group("zahl") == "1" else mz), t)
    t = re.sub(r"\b\d{1,3}(?:\.\d{3})+\b", lambda m: zahl_wort(_zahl_aus(m.group(0))), t)
    t = re.sub(r"\b(\d+),(\d+)\b", lambda m: _dezimal_wort(m.group(1), m.group(2)), t)

    # Abkürzungen und Zeichen
    for muster, wort in ABKUERZUNGEN:
        t = re.sub(muster, wort, t)
    # "usw." stand am Satzende: der Punkt gehört dann wieder dahin.
    t = re.sub(r"\bund so weiter(?=\s+[A-ZÄÖÜ])", "und so weiter.", t)
    t = t.replace("&", " und ").replace("€", " Euro ").replace("→", ", ").replace("->", ", ")
    t = re.sub(r"\s[–—-]\s", ", ", t)
    t = t.replace("…", ".").replace("...", ".")
    t = re.sub(r"[„“”\"»«]", "", t)
    t = re.sub(r"\s*[()\[\]]\s*", ", ", t)
    t = re.sub(r"\s*/\s*", " ", t)

    # Aufräumen: doppelte Zeichen, Leerzeichen vor Satzzeichen
    t = re.sub(r"\s+", " ", t)
    t = re.sub(r"\s+([,.;:!?])", r"\1", t)
    t = re.sub(r"([,;:])\s*([,;:.!?])", r"\2", t)
    t = re.sub(r"([.!?])\s*,", r"\1", t)
    t = re.sub(r"^[,;:\s]+", "", t)
    return t.strip()


# -- Schleifen ----------------------------------------------------------------------

def schleifen_entfernen(text: str) -> str:
    """Spricht Wiederholungen einmal: drei gleiche Wörter und doppelte Sätze."""
    t = re.sub(r"\b([\wäöüÄÖÜß]+)(?:[\s,]+\1\b){2,}", r"\1", text, flags=re.I)
    saetze = re.findall(r"[^.!?]+[.!?]*\s*", t)
    gesehen, behalten = set(), []
    for satz in saetze:
        schluessel = re.sub(r"\W+", " ", satz).strip().lower()
        if len(schluessel) > 15 and schluessel in gesehen:
            continue
        gesehen.add(schluessel)
        behalten.append(satz)
    return "".join(behalten).strip() if behalten else t.strip()


# -- Atemabschnitte ---------------------------------------------------------------------

def abschnitte(text: str, ziel: int = 170, maximum: int = 260) -> list:
    """Teilt gesprochenen Text in Stücke, die man in einem Atemzug sagt.

    Getrennt wird an Satzenden, zu lange Sätze an Kommas und Bindewörtern. Nie
    mitten in einem Wort. Sehr kurze Stücke werden mit dem nächsten verbunden,
    denn ein Stück mit zwei Wörtern klingt abgehackt.
    """
    text = (text or "").strip()
    if not text:
        return []
    saetze = [s.strip() for s in re.findall(r"[^.!?]+[.!?]*", text) if s.strip()]
    stuecke = []
    for satz in saetze:
        while len(satz) > maximum:
            fenster = satz[:maximum]
            schnitt = max(fenster.rfind(", "), fenster.rfind("; "), fenster.rfind(": "))
            if schnitt < ziel // 3:
                schnitt = max(fenster.rfind(" und "), fenster.rfind(" aber "),
                              fenster.rfind(" oder "), fenster.rfind(" weil "))
            if schnitt < ziel // 3:
                schnitt = fenster.rfind(" ")
            if schnitt <= 0:
                schnitt = maximum
            stuecke.append(satz[:schnitt + 1].strip())
            satz = satz[schnitt + 1:].strip()
        if satz:
            stuecke.append(satz)

    verbunden = []
    for stueck in stuecke:
        if verbunden and (len(verbunden[-1]) < 45 or len(stueck) < 25) \
                and len(verbunden[-1]) + 1 + len(stueck) <= ziel:
            verbunden[-1] += " " + stueck
        else:
            verbunden.append(stueck)
    return verbunden


def sprechtext(text: str) -> str:
    """Der ganze Text, zum Sprechen vorbereitet - in einem Stück."""
    return schleifen_entfernen(schreiben_zu_sprechen(text))


def sprechstuecke(text: str, ziel: int = 170) -> list:
    """Der Text, zum Sprechen vorbereitet und in Atemabschnitte geteilt."""
    return abschnitte(sprechtext(text), ziel)


# =========================================================================
# anzeige  -  Anzeige-Speicher - was die großen Bildschirme gerade zeigen sollen.
# 
# Ein einziger Speicher je Prozess (``Werkzeuge.anzeige``). Werkzeuge, Stimme
# und Telefon schreiben hinein, die Seiten (Zentrale, Gehirn, Hauptseite) holen
# es per Long-Poll ab: ``GET /api/anzeige?nach=buehne:7,stimme:31&warten=20``
# kommt zurück, sobald sich einer der genannten Kanäle geändert hat.
# 
# **Kanäle.** Jeder Kanal hat eine Versionsnummer, die nur wächst. Der Kanal
# ``buehne`` sagt, welche Ansicht die Zentrale gerade zeigt (``modus``), die
# anderen tragen laufende Inhalte: ``stimme`` den Pegel der Sprachausgabe,
# ``anruf`` das Telefonat, ``sicht`` Handruhe und Erholung, ``untertitel`` den
# Dolmetscher, ``hochfahren`` den Start.
# 
# **Nie im Weg.** Wer schreibt, fängt jede Ausnahme ab - eine kaputte Anzeige
# darf kein Werkzeug kaputt machen. Ungültiges wird mit ``-1`` abgewiesen und
# nur auf der Konsole gemeldet.
# 
# **Diskret.** Mit ``ANZEIGE_DISKRET`` verschwinden Nummern, Namen und Texte,
# bevor etwas den Speicher verlässt - damit im Raum niemand mitliest.
# 
# **Die Uhr.** Die eingespeiste Uhr (für Prüfungen) gilt nur für ``seit``,
# ``bis`` und ``start``. Wie lange ``warten`` wartet, misst immer die
# Monotonuhr - sonst stünde eine angehaltene Prüf-Uhr für immer still.
# =========================================================================

#!/usr/bin/env python3
# -*- coding: utf-8 -*-



# Die Kanäle der Anzeige. Der Name ist bewusst nicht "KANAELE" - so heißt
# schon die Liste der Versandwege im Messenger.
ANZEIGE_KANAELE = ("buehne", "stimme", "anruf", "sicht", "untertitel", "hochfahren")

# Die Ansichten der Bühne (Kanal "buehne", Feld "modus").
ANZEIGE_MODI = ("uebersicht", "globus", "folge", "maerkte", "kennzahlen", "anruf", "sicht",
                "untertitel", "hochfahren", "recherche", "inhalte")

# Mehr als 64 KB JSON je Eintrag braucht keine Ansicht - und jeder Long-Poll
# trägt es zu jeder Seite.
MAX_NUTZLAST = 65536


def anzeige_nach_lesen(text: str) -> dict:
    """Liest ``"buehne:7,anruf:2"`` als ``{"buehne": 7, "anruf": 2}``.

    Unbekannte Kanäle fallen weg, unlesbare Zahlen werden ``-1`` - dann gilt
    der Kanal als geändert und kommt sofort zurück.
    """
    ergebnis = {}
    for teil in str(text or "").split(","):
        name, _, wert = teil.partition(":")
        name = name.strip()
        if name not in ANZEIGE_KANAELE:
            continue
        try:
            ergebnis[name] = int(wert.strip())
        except ValueError:
            ergebnis[name] = -1
    return ergebnis


def _sicht_leeren(wert, schluessel: str = ""):
    """Gesundheitswerte im Diskretmodus: Zahlen und Texte weg, nur die Quelle bleibt."""
    if schluessel == "quelle":
        return wert
    if isinstance(wert, dict):
        return {k: _sicht_leeren(v, k) for k, v in wert.items()}
    if isinstance(wert, list):
        return [_sicht_leeren(v) for v in wert]
    if isinstance(wert, bool) or wert is None:
        return wert
    if isinstance(wert, (int, float)):
        return None
    if isinstance(wert, str):
        return ""
    return wert


def diskret_filtern(kanal: str, daten: dict) -> dict:
    """Entfernt, was im Raum niemand mitlesen soll. Gibt eine Kopie zurück.

    anruf: Nummer und Ziel weg, Mitschrift leer. untertitel: beide Texte leer.
    sicht: alle Zahlen und Texte leer, nur die Quelle bleibt. hochfahren: keine
    Begrüßung, Schritte nur mit ihrem Namen. Auf der Bühne verlieren Beiträge
    (inhalte) ihren Titel. Kennzahlen, Globus und Recherche bleiben - das sind
    Zahlen oder öffentliche Quellen. Die Stimme wird nie gefiltert, ihr Text
    wird nirgends angezeigt.
    """
    daten = copy.deepcopy(daten) if isinstance(daten, dict) else {}
    if kanal == "anruf":
        if "nummer" in daten:
            daten["nummer"] = ""
        if "ziel" in daten:
            daten["ziel"] = "Anruf"
        for zeile in daten.get("mitschrift") or []:
            if isinstance(zeile, dict):
                zeile["text"] = ""
        # Das Ergebnis nennt Namen und Wünsche - im Raum bleibt nur, ob es geklappt hat.
        ergebnis = daten.get("ergebnis")
        if isinstance(ergebnis, dict):
            daten["ergebnis"] = {k: v for k, v in ergebnis.items()
                                 if k in ("reserviert", "datum", "uhrzeit", "personen")}
        for feld in ("hinweise", "gegenvorschlag", "grund_ende", "auftrag"):
            if feld in daten:
                daten[feld] = ""
    elif kanal == "untertitel":
        for feld in ("original", "uebersetzung"):
            if feld in daten:
                daten[feld] = ""
    elif kanal == "sicht":
        daten = _sicht_leeren(daten)
    elif kanal == "hochfahren":
        if "begruessung" in daten:
            daten["begruessung"] = ""
        for schritt in daten.get("schritte") or []:
            if isinstance(schritt, dict):
                schritt["text"] = str(schritt.get("name") or "")
    elif kanal == "buehne":
        daten = _buehne_diskret(daten)
    return daten


# Auf diesen Ansichten können Titel und Standzeile Namen tragen (Anruf bei ...,
# Erholung von ...). Globus, Märkte, Kennzahlen und Recherche sind öffentlich oder Zahlen.
BUEHNE_PRIVAT = ("anruf", "sicht", "untertitel", "inhalte", "hochfahren")


def _buehne_diskret(daten: dict) -> dict:
    """Bühne im Diskretmodus: Beiträge ohne Titel, private Ansichten ohne Titelzeile."""
    if daten.get("modus") in BUEHNE_PRIVAT:
        for feld in ("titel", "stand"):
            if feld in daten:
                daten[feld] = ""
    if daten.get("modus") == "inhalte":
        for eintrag in daten.get("eintraege") or []:
            if isinstance(eintrag, dict) and "titel" in eintrag:
                eintrag["titel"] = "Beitrag"
    elif daten.get("modus") == "folge":
        for schritt in daten.get("schritte") or []:
            if isinstance(schritt, dict) and isinstance(schritt.get("ansicht"), dict):
                schritt["ansicht"] = _buehne_diskret(schritt["ansicht"])
    return daten


class Anzeige:
    """Der Speicher hinter den Bildschirmen - threadsicher, mit Warten auf Änderungen."""

    def __init__(self, uhr=None):
        self._uhr = uhr or time.time
        self._bed = threading.Condition()
        self._k = {k: {"version": 0, "daten": {}, "seit": 0.0, "bis": 0.0}
                   for k in ANZEIGE_KANAELE}
        self._letzte = {}
        # Ändert sich beim Neustart - die Seiten setzen dann alle Versionen zurück.
        self.start = self._uhr()

    # -- Schreiben ----------------------------------------------------------

    @staticmethod
    def _pruefen(kanal: str, daten) -> tuple:
        """Gibt ``(roh, fehler)`` zurück: das JSON oder warum es abgewiesen wird."""
        if kanal not in ANZEIGE_KANAELE:
            return None, "Den Anzeige-Kanal '%s' gibt es nicht." % kanal
        if not isinstance(daten, dict):
            return None, "Die Anzeige-Daten müssen ein Wörterbuch sein."
        try:
            # NaN und Unendlich sind kein JSON - der Browser könnte die Antwort nicht lesen.
            # Ohne default=str: Datum, Menge oder Bytes sind kein Anzeige-Inhalt.
            roh = json.dumps(daten, ensure_ascii=False, allow_nan=False)
        except (TypeError, ValueError, RecursionError) as fehler:
            return None, "Die Anzeige-Daten sind kein gültiges JSON (%s)." % fehler
        if len(roh.encode("utf-8")) > MAX_NUTZLAST:
            return None, "Die Anzeige-Daten sind zu groß."
        return roh, ""

    @staticmethod
    def _dauer(dauer_s) -> float:
        try:
            dauer = float(dauer_s or 0)
        except (TypeError, ValueError):
            return 0.0
        return dauer if dauer > 0 and dauer != float("inf") else 0.0

    def _ablegen(self, kanal: str, roh: str, dauer: float, modus: str = "") -> int:
        """Legt geprüfte Daten ab und weckt alle Wartenden. Gibt die neue Version zurück."""
        with self._bed:
            eintrag = self._k[kanal]
            jetzt = self._uhr()
            eintrag["version"] += 1
            eintrag["daten"] = json.loads(roh)
            eintrag["seit"] = jetzt
            eintrag["bis"] = jetzt + dauer if dauer > 0 else 0.0
            if modus:
                self._letzte[modus] = json.loads(roh)
            self._bed.notify_all()
            return eintrag["version"]

    def melden(self, kanal: str, daten: dict, dauer_s: float = 0.0) -> int:
        """Schreibt einen Kanal. Gibt die neue Version zurück oder ``-1``.

        ``dauer_s`` 0 heißt: gilt, bis etwas Neues kommt.
        """
        roh, fehler = self._pruefen(kanal, daten)
        if roh is None:
            print("[anzeige] %s" % fehler)
            return -1
        return self._ablegen(kanal, roh, self._dauer(dauer_s))

    def zeigen(self, modus: str, daten: dict = None, dauer_s: float = None,
               quelle: str = "") -> dict:
        """Schaltet die Bühne auf eine Ansicht.

        ``dauer_s`` ``None`` nimmt ``ANZEIGE_DAUER``, ``0`` hält die Ansicht,
        bis etwas Neues kommt. Danach kehrt die Zentrale zur Übersicht zurück.
        """
        modus = str(modus or "").strip()
        if modus not in ANZEIGE_MODI:
            return {"ok": False,
                    "fehler": "Diese Ansicht gibt es nicht: %s. Möglich sind: %s."
                              % (modus or "(leer)", ", ".join(ANZEIGE_MODI))}
        if daten is None:
            daten = {}
        if not isinstance(daten, dict):
            return {"ok": False, "fehler": "Die Anzeige-Daten müssen ein Wörterbuch sein."}
        nutzlast = dict(daten, modus=modus, quelle=str(quelle or ""))
        roh, fehler = self._pruefen("buehne", nutzlast)
        if roh is None:
            print("[anzeige] %s" % fehler)
            return {"ok": False, "fehler": fehler}
        dauer = ANZEIGE_DAUER if dauer_s is None else dauer_s
        version = self._ablegen("buehne", roh, self._dauer(dauer), modus)
        return {"ok": True, "modus": modus, "version": version}

    # -- Lesen --------------------------------------------------------------

    def letzte(self, modus: str):
        """Was zuletzt in dieser Ansicht gezeigt wurde - ``None``, wenn noch nichts.

        Nur für den Programmcode (zum erneuten Zeigen über :meth:`zeigen`): ungefiltert,
        nie direkt an eine Seite geben.
        """
        with self._bed:
            gespeichert = self._letzte.get(modus)
            return copy.deepcopy(gespeichert) if gespeichert is not None else None

    def _stand(self, kanal: str) -> dict:
        """Stand eines Kanals, schon gefiltert. Nur unter der Sperre aufrufen."""
        eintrag = self._k[kanal]
        daten = copy.deepcopy(eintrag["daten"])
        if ANZEIGE_DISKRET and kanal != "stimme":
            daten = diskret_filtern(kanal, daten)
        return {"version": eintrag["version"], "daten": daten,
                "seit": eintrag["seit"], "bis": eintrag["bis"]}

    def stand(self, kanal: str):
        """``{"version", "daten", "seit", "bis"}`` eines Kanals - ``None``, wenn es ihn
        nicht gibt."""
        if kanal not in self._k:
            return None
        with self._bed:
            return self._stand(kanal)

    def warten(self, nach: dict, timeout: float) -> dict:
        """Wartet, bis einer der Kanäle eine andere Version hat als in ``nach``.

        Gibt ``{kanal: stand}`` der geänderten Kanäle zurück, nach Ablauf
        ``{}``. Verglichen wird mit ``!=``, nicht ``>``: So fällt auch ein
        neu gestarteter Server auf, dessen Zähler wieder klein sind.
        """
        try:
            frist = min(3600.0, max(0.0, float(timeout or 0)))
        except (TypeError, ValueError):
            frist = 0.0
        if frist != frist:  # NaN
            frist = 0.0
        ende = time.monotonic() + frist
        gefragt = {k: v for k, v in (nach or {}).items() if k in self._k}
        with self._bed:
            while True:
                geaendert = {k: self._stand(k) for k, v in gefragt.items()
                             if self._k[k]["version"] != v}
                rest = ende - time.monotonic()
                if geaendert or rest <= 0:
                    return geaendert
                self._bed.wait(rest)

    def kurz(self) -> dict:
        """Kurzstand für ``/api/status``: Ansicht, Versionen, Ablauf, Start."""
        with self._bed:
            buehne = self._k["buehne"]
            modus = buehne["daten"].get("modus") or "uebersicht"
            if buehne["bis"] and self._uhr() >= buehne["bis"]:
                modus = "uebersicht"
            return {"modus": modus,
                    "versionen": {k: e["version"] for k, e in self._k.items()},
                    "bis": buehne["bis"], "start": self.start}


# =========================================================================
# freigabe  -  Freigaben mit Was, Warum und Wie - lesbar statt rohem JSON.
# 
# Vor allem mit Wirkung nach außen fragt Jarvis nach. Damit jemand Ja sagen
# kann, muss die Frage drei Dinge beantworten:
# 
# * **Was** passiert - "eine Mail an kunde@firma.at schicken, Betreff Angebot".
# * **Warum** - das schreibt Claude selbst ins Feld ``begruendung``. Fehlt es,
#   steht das sichtbar da, statt still zu fehlen.
# * **Wie** - über welchen Weg es hinausgeht, und was dabei bekannt wird.
# 
# Je Werkzeug gibt es dafür eine kleine Funktion in ``FREIGABE_ANGABEN``
# (Argumente rein, ``(was, wie)`` raus) - keine Vorlagensprache, die niemand
# lesen kann. Werkzeuge, die nur Kennungen bekommen (eine Termin-id, eine
# Message-ID), tragen in ``FREIGABE_AUFLOESEN`` einen Auflöser ein, der daraus
# Lesbares macht. Scheitert er, zeigt die Freigabe die rohen Argumente.
# 
# Die Beschreibung wandert als JSON durch die Freigabewege (Terminal,
# Telegram, Stimme, Browser). Wege, die nichts davon wissen, bekommen weiter den
# alten Text - ``freigabe_lesen`` erkennt beides.
# =========================================================================

#!/usr/bin/env python3
# -*- coding: utf-8 -*-



# Ein Wert in den Argumenten darf so lang sein, bevor er gekürzt wird.
# Adresse, Pfad und Empfänger bleiben immer ganz - die muss man sehen.
ARGUMENT_GRENZE = 400
NIE_KUERZEN = ("adresse", "url", "pfad", "an", "nummer")
# Die Begründung schreibt Claude - sie darf die eigentlichen Angaben nie verdrängen.
BEGRUENDUNG_GRENZE = 300

OHNE_BEGRUENDUNG = "(ohne Begründung – Jarvis hat keinen Grund genannt)"

# Diese Aktionen gibt keine Geste frei - nur Klick oder Stimme. Die Gestenprüfung
# selbst kommt später; die Liste steht schon hier, damit alle sie kennen.
GESTE_GESPERRT = {"skript_ausfuehren", "bildschirm_bedienen", "browser_auftrag", "browser_schritt",
                  "datei_schreiben", "ordnen_ausfuehren", "ordnen_rueckgaengig",
                  "autopilot_schalten",
                  # Was draußen etwas auslöst oder Termine ändert, bestätigt nur ein Klick oder die Stimme:
                  # Ein erhobener Daumen kann ein Vorschlag annehmen, aber keinen Anruf, Kurzbefehl
                  # oder keine Absage freigeben.
                  "kurzbefehl_ausfuehren", "restaurant_anrufen", "termine_absagen",
                  "termin_verschieben", "termin_wiederherstellen"}


def argumente_kuerzen(argumente: dict) -> dict:
    """Kürzt jedes lange Textfeld für sich - Empfänger, Pfad und Adresse nie."""
    kurz = {}
    for schluessel, wert in (argumente or {}).items():
        if isinstance(wert, str) and len(wert) > ARGUMENT_GRENZE and schluessel not in NIE_KUERZEN:
            kurz[schluessel] = "%s … (%d Zeichen insgesamt)" % (wert[:ARGUMENT_GRENZE], len(wert))
        else:
            kurz[schluessel] = wert
    return kurz


def _wert_kurz(wert, grenze: int = 120) -> str:
    """Ein Wert als eine Zeile, höchstens ``grenze`` Zeichen. Fehlt er: ``?``."""
    if wert is None or wert == "":
        return "?"
    text = " ".join(str(wert).split())
    return text if len(text) <= grenze else text[:grenze].rstrip() + " …"


def _voll(wert) -> str:
    """Ein Wert als eine Zeile, nie gekürzt - für Empfänger, Nummern, Adressen und Pfade."""
    if wert is None or wert == "":
        return "?"
    return " ".join(str(wert).split())


def lesbarer_name(name: str) -> str:
    """``mcp__kalender__loeschen`` wird ``kalender, loeschen``, ``mail_senden`` ``mail senden``."""
    return str(name or "").replace("mcp__", "").replace("__", ", ").replace("_", " ").strip()


def _argumente_zeile(argumente: dict, grenze: int = 160) -> str:
    """Die Argumente als kurze Zeile ``name: wert; name: wert`` - ohne die Begründung."""
    teile = ["%s: %s" % (k, _wert_kurz(v, 60)) for k, v in (argumente or {}).items()
             if k != "begruendung"]
    return _wert_kurz("; ".join(teile), grenze) if teile else ""


# -- Was und Wie je Werkzeug ------------------------------------------------
# Jede Funktion bekommt die Argumente (samt Zusatzfeldern eines Auflösers) und
# gibt (was, wie) zurück. "was" steht nach "Ich soll ..." - ohne Punkt am Ende.
# Der erste Satz von "wie" wird im Dienst laut gesagt.

def _angaben_mail_senden(a: dict) -> tuple:
    k = _wert_kurz
    return ("eine Mail an %s schicken, Betreff „%s“. Sie beginnt mit: %s"
            % (_voll(a.get("an")), k(a.get("betreff")), k(a.get("text"))),
            "Per SMTP vom eingerichteten Postfach. Der ganze Text steht in den Details.")


def _angaben_termin_anlegen(a: dict) -> tuple:
    k = _wert_kurz
    ort = " in %s" % k(a.get("ort")) if a.get("ort") else ""
    return ("den Termin „%s“ am %s (%s Minuten) eintragen%s"
            % (k(a.get("titel")), k(a.get("beginn")), a.get("dauer_minuten") or 60, ort),
            "Im Kalender %s über CalDAV."
            % (CALDAV_KALENDER or "des eingerichteten Kontos"))


NACHRICHT_WEGE = {
    "telegram": "Über den Telegram-Bot.",
    "mail": "Per SMTP vom eingerichteten Postfach.",
    "imessage": "Über die Nachrichten-App des Macs mit deiner eigenen Nummer.",
    "sms": "Über die Nachrichten-App des Macs mit deiner eigenen Nummer.",
    "whatsapp": "Über den angeschlossenen WhatsApp-Dienst.",
}


def _angaben_nachricht_senden(a: dict) -> tuple:
    k = _wert_kurz
    kanal = str(a.get("kanal") or "").strip().lower()
    an = a.get("an") or ("dich selbst" if kanal == "telegram" else None)
    art = " als Sprachnachricht" if a.get("als_sprache") else ""
    return ("per %s an %s%s schreiben: %s" % (k(kanal), _voll(an), art, k(a.get("text"))),
            NACHRICHT_WEGE.get(kanal, "Über den Kanal %s." % k(kanal)))


def _angaben_anrufen(a: dict) -> tuple:
    k = _wert_kurz
    return ("%s anrufen und ansagen: %s" % (_voll(a.get("nummer")), k(a.get("ansage"))),
            "Ein Twilio-Anruf von deiner Twilio-Nummer. Die Ansage wird zweimal vorgelesen.")


def _angaben_sms_senden(a: dict) -> tuple:
    k = _wert_kurz
    twilio = bool(TWILIO_SID and TWILIO_TOKEN and TWILIO_NUMMER)
    return ("%s eine SMS schicken: %s" % (_voll(a.get("nummer")), k(a.get("text"))),
            "Über Twilio von deiner Twilio-Nummer." if twilio
            else "Über die Nachrichten-App des Macs mit deiner eigenen Nummer.")


def _angaben_skript_ausfuehren(a: dict) -> tuple:
    k = _wert_kurz
    liste = a.get("argumente") or []
    zusatz = " mit %s" % k(" ".join(str(x) for x in liste), 80) if liste else ""
    return ("das Skript %s aus der Werkstatt ausführen%s" % (k(a.get("name")), zusatz),
            "Mit Python in der Werkstatt. Der Code steht vollständig in der Frage.")


def _angaben_bildschirm_bedienen(a: dict) -> tuple:
    return ("den Bildschirm bedienen: %s" % _wert_kurz(a.get("ziel"), 160),
            "Schritt für Schritt über Bildschirmfotos. Jeder Schritt wird einzeln bestätigt.")


def _angaben_browser_auftrag(a: dict) -> tuple:
    start = " Er beginnt bei %s." % _wert_kurz(a.get("start")) if a.get("start") else ""
    return ("im Browser: %s" % _wert_kurz(a.get("ziel"), 160),
            "Klickt nur Beschriftungen, meldet sich nirgends an und kauft nichts.%s" % start)


def _angaben_browser_oeffnen(a: dict) -> tuple:
    return ("die Adresse %s öffnen" % _voll(a.get("adresse")),
            "Im eingebauten Browser. Die Adresse selbst geht dabei ins Netz.")


def _angaben_autopilot_schalten(a: dict) -> tuple:
    if a.get("an"):
        return ("den Autopiloten einschalten",
                "Er arbeitet dann im Hintergrund, legt Entwürfe ins Postfach und schickt "
                "nichts ab.")
    return ("den Autopiloten ausschalten",
            "Bis du ihn wieder einschaltest, arbeitet er nicht mehr.")


def _angaben_datei_schreiben(a: dict) -> tuple:
    tun = "ersetzen" if a.get("ueberschreiben") else "neu anlegen"
    return ("die Datei %s %s, sie beginnt mit: %s"
            % (_voll(a.get("pfad")), tun, _wert_kurz(a.get("inhalt"), 80)),
            "Nur in den freigegebenen Ordnern deines Benutzerordners. Der Inhalt steht in "
            "den Details.")


FREIGABE_ANGABEN = {
    "mail_senden": _angaben_mail_senden,
    "termin_anlegen": _angaben_termin_anlegen,
    "nachricht_senden": _angaben_nachricht_senden,
    "anrufen": _angaben_anrufen,
    "sms_senden": _angaben_sms_senden,
    "skript_ausfuehren": _angaben_skript_ausfuehren,
    "bildschirm_bedienen": _angaben_bildschirm_bedienen,
    "browser_auftrag": _angaben_browser_auftrag,
    "browser_oeffnen": _angaben_browser_oeffnen,
    "autopilot_schalten": _angaben_autopilot_schalten,
    "datei_schreiben": _angaben_datei_schreiben,
}

# Werkzeugname -> funktion(werkzeuge, argumente) -> dict mit Zusatzfeldern, die
# "was" lesbar machen (etwa der Titel eines Termins statt seiner Kennung).
# Die Zusatzfelder landen nur in der Angaben-Funktion, nicht in den Argumenten.
# Sie tragen eigene Namen (termin_titel, nicht titel): Ein Zusatzfeld kann ein
# echtes Argument nie überschreiben - sonst könnte die Frage einen anderen
# Empfänger nennen, als hinterher wirklich bekommt.
FREIGABE_AUFLOESEN = {}

# Die Pakete tragen ihre Einträge zwischen ihren Marken ein, etwa
# FREIGABE_ANGABEN["termine_absagen"] = _angaben_termine_absagen.
# [P1 Bühne] Anfang
# [P1 Bühne] Ende
# [P2 Weltlage] Anfang
# [P2 Weltlage] Ende
# [P3 Telefon] Anfang
# [P3 Telefon] Ende
# [P4 Büro] Anfang
# [P4 Büro] Ende
# [P5 Sicht] Anfang
# [P5 Sicht] Ende
# [P6 Stimme] Anfang
# [P6 Stimme] Ende
# [P7 Start] Anfang
# [P7 Start] Ende


def _angaben_unbekannt(name: str, a: dict) -> tuple:
    """Für Werkzeuge ohne eigenen Eintrag, auch die von MCP-Diensten."""
    zeile = _argumente_zeile(a)
    if str(name).startswith("mcp__"):
        teile = str(name).split("__")
        dienst = teile[1] if len(teile) > 1 else "?"
        werkzeug = "__".join(teile[2:]) or "?"
        was = "beim Dienst „%s“ das Werkzeug „%s“ ausführen" % (dienst, werkzeug)
        wie = ("Über den angeschlossenen Dienst „%s“. Was das Werkzeug genau tut, "
               "bestimmt dieser Dienst." % dienst)
    else:
        was = "%s ausführen" % (lesbarer_name(name) or "ein Werkzeug")
        wie = "Über das Werkzeug %s." % name
    return (was + (", mit: %s" % zeile if zeile else ""), wie)


def freigabe_beschreiben(name: str, argumente: dict, zusatz: dict = None) -> dict:
    """Was, Warum und Wie einer Freigabe - plus die gekürzten Argumente.

    ``zusatz`` kommt von einem Auflöser (``FREIGABE_AUFLOESEN``) und macht
    "was" lesbar. Geht beim Beschreiben etwas schief, zeigt die Freigabe die
    rohen Argumente - eine Frage ganz ohne Inhalt darf es nie geben.
    """
    argumente = argumente if isinstance(argumente, dict) else {}
    felder = dict(zusatz) if isinstance(zusatz, dict) else {}
    felder.update(argumente)  # die echten Argumente gewinnen immer
    angaben = FREIGABE_ANGABEN.get(name)
    was, wie = "", ""
    if angaben is not None:
        try:
            was, wie = angaben(felder)
        except Exception as fehler:
            print("[freigabe] Beschreibung für %s fehlgeschlagen: %s" % (name, fehler))
            was, wie = "", ""
        if not was and zusatz:
            # Vielleicht lag es an den Zusatzfeldern - dann eben mit den rohen Argumenten.
            try:
                was, wie = angaben(dict(argumente))
            except Exception:
                was, wie = "", ""
    if not was:
        was, wie_unbekannt = _angaben_unbekannt(name, argumente)
        wie = wie or wie_unbekannt
    warum = _wert_kurz(argumente.get("begruendung"), BEGRUENDUNG_GRENZE) \
        if argumente.get("begruendung") else ""
    # Bei fremden Diensten ist "begruendung" vielleicht ein echtes Argument - dann bleibt es sichtbar.
    sichtbar = {k: v for k, v in argumente_kuerzen(argumente).items()
                if k != "begruendung" or str(name).startswith("mcp__")}
    return {"was": str(was), "warum": warum or OHNE_BEGRUENDUNG, "wie": str(wie or ""),
            "argumente": sichtbar}


# -- Lesen auf der anderen Seite --------------------------------------------

def freigabe_lesen(details) -> dict:
    """Erkennt eine Beschreibung aus :func:`freigabe_beschreiben`.

    Gibt ``{"was", "warum", "wie", "argumente"}`` zurück - oder ``None`` für
    alten Freitext (etwa den Code eines Skripts) und alte Argument-JSONs.
    """
    if isinstance(details, dict):
        daten = details
    else:
        text = str(details or "").strip()
        if not text.startswith("{"):
            return None
        try:
            daten = json.loads(text)
        except ValueError:
            return None
    if not isinstance(daten, dict) or not daten.get("was"):
        return None
    argumente = daten.get("argumente")
    return {"was": str(daten.get("was") or ""), "warum": str(daten.get("warum") or ""),
            "wie": str(daten.get("wie") or ""),
            "argumente": argumente if isinstance(argumente, dict) else {}}


def erster_satz(text: str) -> str:
    """Der erste Satz eines Textes - mit großem Anfang und Punkt am Ende."""
    text = " ".join(str(text or "").split())
    if not text:
        return ""
    for ende in (". ", "! ", "? "):
        stelle = text.find(ende)
        if stelle >= 0:
            text = text[:stelle + 1]
    text = text[0].upper() + text[1:]
    return text if text[-1] in ".!?" else text + "."


def freigabe_text(aktion: str, details) -> str:
    """Die Freigabe als Klartext für Terminal und Telegram.

    Neue Beschreibungen werden zu "Was / Warum / Wie / Details", alter Text
    bleibt, wie er ist.
    """
    lesbar = freigabe_lesen(details)
    if lesbar is None:
        return str(details or "")
    try:
        argumente = json.dumps(lesbar["argumente"], ensure_ascii=False, default=str)
    except (TypeError, ValueError):
        argumente = str(lesbar["argumente"])
    # Details vor Warum: Werden lange Nachrichten gekürzt, fehlt eher die Begründung als ein Empfänger.
    return ("Was:     %s\nWie:     %s\nDetails: %s\nWarum:   %s"
            % (lesbar["was"], lesbar["wie"], argumente, lesbar["warum"]))


# =========================================================================
# netzsocket  -  Kleiner WebSocket-Client (RFC 6455) aus der Standardbibliothek.
# 
# Jarvis braucht ihn für die Live-Mitschrift beim Telefonassistenten (Retell
# schickt sie über eine Verbindung, die der Mac selbst aufmacht). Es gibt keinen
# eingehenden Zugang zum Mac - dieser Client wählt sich immer nur aus.
# 
# Was er kann:
# 
# * ``ws://`` und ``wss://`` (TLS mit geprüftem Zertifikat), Kopfzeilen wie
#   ``Authorization`` werden mitgeschickt.
# * Handschlag mit Prüfung von ``Sec-WebSocket-Accept`` - ein Server, der nicht
#   wirklich WebSocket spricht, wird abgewiesen.
# * Alle Client-Rahmen sind maskiert, auch Pong und Close.
# * Ping wird mit einem Pong beantwortet, Fragmente werden zusammengesetzt
#   (auch wenn ein Ping dazwischenkommt), die erweiterten Längen 126 und 127
#   werden gelesen und geschrieben.
# * Close beendet den Erzeuger ``nachrichten()``; Code und Grund bleiben in
#   ``schliess_code`` und ``schliess_grund`` stehen.
# * Zeitgrenzen: ``timeout`` gilt fürs Verbinden, den Handschlag und jedes
#   Warten. Bleibt es länger still, schickt der Client einmal einen Ping; kommt
#   auch darauf nichts, bricht er mit ``WebSocketFehler`` ab. Zusätzlich gibt es
#   eine Gesamtfrist je ``nachrichten(frist=...)``.
# * Jeder Fehler kommt als ``WebSocketFehler`` mit deutscher Meldung. Die
#   Meldungen nennen nie Kopfzeilen, Schlüssel oder die Parameter der Adresse.
# * Die Verbindung ist einspeisbar: ``verbinden(host, port, tls) -> socket``.
#   So laufen Prüfungen mit ``socket.socketpair()`` ohne Netz.
# 
# Bewusste Nachsicht: Maskierte Rahmen vom Server und nicht minimal kodierte
# Längen werden angenommen (der RFC verbietet sie dem Sender, der Empfänger
# kann sie aber gefahrlos lesen). Erweiterungsbits, unbekannte Opcodes,
# zerrissene Fragmentfolgen, zu große Nachrichten und ungültiges UTF-8 führen
# dagegen zum Abbruch mit Close-Code 1002, 1009 bzw. 1007.
# 
# ``netzsocket_selbsttest()`` spielt alle Fälle gegen einen kleinen Server auf
# 127.0.0.1 durch (ohne Internet).
# =========================================================================

#!/usr/bin/env python3
# -*- coding: utf-8 -*-


# Feste Zeichenfolge aus RFC 6455, Abschnitt 1.3 (gehört in die Accept-Berechnung).
NETZSOCKET_GUID = "258EAFA5-E914-47DA-95CA-C5AB0DC85B11"
# Größte Nachricht (alle Fragmente zusammen), die der Client annimmt.
NETZSOCKET_MAX_NACHRICHT = 8 * 1024 * 1024
# Größter Antwortkopf beim Handschlag.
NETZSOCKET_MAX_KOPF = 65536
# So lange wartet schliessen() höchstens auf die Antwort des Servers (Sekunden).
NETZSOCKET_SCHLIESSWARTE = 2.0
# Kopfzeilen, die der Client selbst setzt und die der Aufrufer nicht ändern darf.
NETZSOCKET_RESERVIERT = ("host", "upgrade", "connection", "sec-websocket-key",
                         "sec-websocket-version", "sec-websocket-extensions",
                         "sec-websocket-protocol")
_NETZSOCKET_NAME = re.compile(r"^[!#$%&'*+.^_`|~0-9A-Za-z-]+$")
_NETZSOCKET_ZIEL_SICHER = "/%:@!$&'()*+,;=-._~"


class WebSocketFehler(Exception):
    """Alles, was beim WebSocket schiefgehen kann - die Meldung ist deutsch."""


class WebSocketLeser:
    """Eine WebSocket-Verbindung zum Lesen (und bei Bedarf Schreiben).

    ``WebSocketLeser(url, kopfzeilen=None, timeout=30, verbinden=None)`` baut die
    Verbindung auf und macht den Handschlag; Fehler dabei sind ``WebSocketFehler``.
    ``timeout`` gilt für Verbinden, Handschlag und jedes Warten (``None`` = ohne
    Grenze). ``verbinden(host, port, tls)`` liefert einen verbundenen Socket und
    ist für Prüfungen austauschbar; bei ``tls`` muss er selbst verschlüsseln.
    ``max_nachricht`` begrenzt die Größe einer Nachricht in Bytes.

        ws = WebSocketLeser("wss://host/pfad", {"Authorization": "Bearer ..."})
        for text in ws.nachrichten():
            ...
        ws.schliessen()
    """

    def __init__(self, url, kopfzeilen=None, timeout=30, verbinden=None, max_nachricht=None):
        if timeout is not None and not timeout > 0:
            raise WebSocketFehler("Die Zeitgrenze muss größer als 0 Sekunden sein.")
        self.timeout = timeout
        self.max_nachricht = int(max_nachricht or NETZSOCKET_MAX_NACHRICHT)
        self.schliess_code = None
        self.schliess_grund = ""
        self._sock = None
        self._puffer = bytearray()
        self._fertig = threading.Event()
        self._sende_sperre = threading.Lock()
        self._lese_sperre = threading.Lock()
        self._close_gesendet = False
        self._ich_schliesse = False
        host, port, tls, ziel, host_kopf = self._adresse_zerlegen(url)
        zeilen = self._kopfzeilen_pruefen(kopfzeilen)
        self._host = host
        sock = self._verbindung_aufbauen(verbinden or self._verbinden_standard, host, port, tls)
        self._sock = sock
        try:
            self._handschlag(ziel, host_kopf, zeilen)
        except BaseException:
            self._zumachen()
            raise

    # ------------------------------------------------------------ Aufbau
    @staticmethod
    def _adresse_zerlegen(url):
        """Zerlegt die Adresse in (host, port, tls, anfrageziel, host-kopf)."""
        if not isinstance(url, str) or not url.strip():
            raise WebSocketFehler("Es fehlt die Adresse der WebSocket-Verbindung.")
        try:
            teile = urllib.parse.urlsplit(url.strip())
            port = teile.port
            host = teile.hostname
        except ValueError:
            raise WebSocketFehler("Die Adresse der WebSocket-Verbindung ist ungültig.")
        if teile.scheme not in ("ws", "wss"):
            raise WebSocketFehler("Die Adresse muss mit ws:// oder wss:// beginnen.")
        if not host:
            raise WebSocketFehler("In der Adresse fehlt der Rechnername.")
        tls = teile.scheme == "wss"
        standard = 443 if tls else 80
        ziel = urllib.parse.quote(teile.path or "/", safe=_NETZSOCKET_ZIEL_SICHER)
        if teile.query:
            ziel += "?" + urllib.parse.quote(teile.query, safe=_NETZSOCKET_ZIEL_SICHER + "?")
        host_kopf = "[%s]" % host if ":" in host else host
        if port is not None and port != standard:
            host_kopf += ":%d" % port
        return host, port or standard, tls, ziel, host_kopf

    @staticmethod
    def _kopfzeilen_pruefen(kopfzeilen):
        """Prüft die Kopfzeilen des Aufrufers und liefert fertige Zeilen."""
        zeilen = []
        gesehen = set()
        for name, wert in (kopfzeilen or {}).items():
            name, wert = str(name), str(wert)
            if not _NETZSOCKET_NAME.match(name):
                raise WebSocketFehler("Der Name einer Kopfzeile ist ungültig.")
            if name.lower() in NETZSOCKET_RESERVIERT:
                raise WebSocketFehler("Die Kopfzeile %s setzt der Client selbst." % name)
            if (not wert.isascii()) or any(z in wert for z in "\r\n\x00"):
                raise WebSocketFehler("Der Wert der Kopfzeile %s ist ungültig." % name)
            gesehen.add(name.lower())
            zeilen.append("%s: %s" % (name, wert))
        if "user-agent" not in gesehen:  # manche Vorschaltdienste weisen Anfragen ohne Kennung ab
            zeilen.append("User-Agent: Jarvis-Netzsocket/1.0")
        return zeilen

    def _verbinden_standard(self, host, port, tls):
        """Echte Verbindung (mit TLS bei wss)."""
        try:
            roh = socket.create_connection((host, port), timeout=self.timeout)
        except socket.gaierror:
            raise WebSocketFehler("Den Rechnernamen %s finde ich nicht." % host)
        except socket.timeout:
            raise WebSocketFehler("Zeitüberschreitung beim Verbinden mit %s." % host)
        except OSError as fehler:
            raise WebSocketFehler("Die Verbindung zu %s ist nicht möglich (%s)."
                                  % (host, fehler.strerror or type(fehler).__name__))
        if not tls:
            return roh
        try:
            return ssl.create_default_context().wrap_socket(roh, server_hostname=host)
        except ssl.SSLCertVerificationError:
            roh.close()
            raise WebSocketFehler("Dem Zertifikat von %s traue ich nicht." % host)
        except socket.timeout:
            roh.close()
            raise WebSocketFehler("Zeitüberschreitung bei der verschlüsselten Verbindung mit %s." % host)
        except (ssl.SSLError, OSError):
            roh.close()
            raise WebSocketFehler("Die verschlüsselte Verbindung zu %s kommt nicht zustande." % host)

    @staticmethod
    def _verbindung_aufbauen(verbinden, host, port, tls):
        try:
            sock = verbinden(host, port, tls)
        except WebSocketFehler:
            raise
        except socket.timeout:
            raise WebSocketFehler("Zeitüberschreitung beim Verbinden mit %s." % host)
        except OSError as fehler:
            raise WebSocketFehler("Die Verbindung zu %s ist nicht möglich (%s)."
                                  % (host, getattr(fehler, "strerror", None) or type(fehler).__name__))
        if sock is None:
            raise WebSocketFehler("Die Verbindung zu %s ist nicht möglich." % host)
        return sock

    def _handschlag(self, ziel, host_kopf, zeilen):
        schluessel = base64.b64encode(os.urandom(16)).decode("ascii")
        anfrage = ["GET %s HTTP/1.1" % ziel, "Host: %s" % host_kopf, "Upgrade: websocket",
                   "Connection: Upgrade", "Sec-WebSocket-Key: " + schluessel,
                   "Sec-WebSocket-Version: 13"] + zeilen
        frist = None if self.timeout is None else time.monotonic() + self.timeout
        try:
            self._sock.sendall(("\r\n".join(anfrage) + "\r\n\r\n").encode("ascii"))
        except socket.timeout:
            raise WebSocketFehler("Zeitüberschreitung beim Handschlag.")
        except OSError:
            raise WebSocketFehler("Handschlag nicht möglich: Die Verbindung ist abgebrochen.")
        kopf = bytearray()
        while b"\r\n\r\n" not in kopf:
            if len(kopf) > NETZSOCKET_MAX_KOPF:
                raise WebSocketFehler("Handschlag abgelehnt: Die Antwort des Servers ist zu lang.")
            try:
                stueck = self._empfangen(4096, frist)
            except socket.timeout:
                raise WebSocketFehler("Zeitüberschreitung beim Handschlag.")
            kopf += stueck
        kopf, _, rest = bytes(kopf).partition(b"\r\n\r\n")
        self._puffer += rest  # was nach dem Kopf schon da ist, gehört zu den Rahmen
        zeilen = kopf.decode("latin-1").split("\r\n")
        status = zeilen[0].split(" ", 2)
        if len(status) < 2 or not status[0].startswith("HTTP/1.") or not status[1].isdigit():
            raise WebSocketFehler("Handschlag abgelehnt: Das ist keine gültige HTTP-Antwort.")
        code = int(status[1])
        if code != 101:
            raise WebSocketFehler(self._handschlag_meldung(code))
        antwort = {}
        for zeile in zeilen[1:]:
            name, doppelpunkt, wert = zeile.partition(":")
            if doppelpunkt:
                name = name.strip().lower()
                antwort[name] = (antwort[name] + ", " if name in antwort else "") + wert.strip()
        if antwort.get("upgrade", "").lower() != "websocket":
            raise WebSocketFehler("Handschlag abgelehnt: Der Server wechselt nicht zu WebSocket.")
        if "upgrade" not in [t.strip().lower() for t in antwort.get("connection", "").split(",")]:
            raise WebSocketFehler("Handschlag abgelehnt: Der Server bestätigt den Wechsel nicht.")
        erwartet = base64.b64encode(hashlib.sha1(
            (schluessel + NETZSOCKET_GUID).encode("ascii")).digest()).decode("ascii")
        if antwort.get("sec-websocket-accept", "") != erwartet:
            raise WebSocketFehler("Handschlag abgelehnt: Sec-WebSocket-Accept stimmt nicht - "
                                  "das ist kein gültiger WebSocket-Server.")
        if "sec-websocket-extensions" in antwort or "sec-websocket-protocol" in antwort:
            raise WebSocketFehler("Handschlag abgelehnt: Der Server will eine Erweiterung, "
                                  "die nicht vereinbart wurde.")

    @staticmethod
    def _handschlag_meldung(code):
        if code in (401, 403):
            return ("Handschlag abgelehnt: Der Server verweigert den Zugang (HTTP %d) - "
                    "Schlüssel und Berechtigung prüfen." % code)
        if code == 404:
            return "Handschlag abgelehnt: Diese Adresse gibt es dort nicht (HTTP 404)."
        if code == 429:
            return "Handschlag abgelehnt: Zu viele Anfragen (HTTP 429)."
        if 300 <= code < 400:
            return "Handschlag abgelehnt: Der Server leitet um (HTTP %d); Umleitungen folge ich nicht." % code
        if code >= 500:
            return "Handschlag abgelehnt: Der Server hat einen Fehler (HTTP %d)." % code
        return "Handschlag abgelehnt: Der Server antwortet mit HTTP %d statt 101." % code

    # ------------------------------------------------------------ Lesen
    @property
    def offen(self):
        return not self._fertig.is_set()

    def _empfangen(self, groesse, frist):
        """Ein Stück vom Socket. ``socket.timeout`` bei Stille, sonst WebSocketFehler."""
        grenze = self.timeout
        if frist is not None:
            rest = frist - time.monotonic()
            if rest <= 0:
                raise socket.timeout()
            grenze = rest if grenze is None else min(grenze, rest)
        try:
            self._sock.settimeout(grenze)
        except (OSError, AttributeError):
            pass
        try:
            stueck = self._sock.recv(groesse)
        except socket.timeout:
            raise
        except OSError:
            raise WebSocketFehler("Die Verbindung ist abgebrochen.")
        if not stueck:
            raise WebSocketFehler("Der Server hat die Verbindung beendet, ohne sich zu verabschieden.")
        return stueck

    def _bytes_holen(self, n, frist):
        """Genau ``n`` Bytes. Bei Stille bleibt das Gelesene im Puffer (Wiederaufnahme möglich)."""
        while len(self._puffer) < n:
            fehlt = n - len(self._puffer)
            self._puffer += self._empfangen(min(max(fehlt, 4096), 1 << 20), frist)
        daten = bytes(self._puffer[:n])
        del self._puffer[:n]
        return daten

    def _kopf_holen(self, frist):
        """Die ersten zwei Bytes eines Rahmens. Bei Stille: einmal anpingen, dann aufgeben."""
        stille = 0
        while True:
            try:
                return self._bytes_holen(2, frist)
            except socket.timeout:
                if frist is not None and time.monotonic() >= frist:
                    raise WebSocketFehler("Die Zeitgrenze für das Warten auf Nachrichten ist erreicht.")
                if stille or self._close_gesendet:
                    raise WebSocketFehler("Der Server antwortet nicht mehr (Zeitüberschreitung).")
                stille += 1
                self.ping(b"jarvis")

    def _rahmen_lesen(self, frist):
        """Ein Rahmen als (fin, opcode, nutzlast), oder ``None`` wenn schon zu."""
        with self._lese_sperre:
            if self._fertig.is_set():
                return None
            b1, b2 = self._kopf_holen(frist)
            try:
                fin, opcode, laenge = bool(b1 & 0x80), b1 & 0x0F, b2 & 0x7F
                if b1 & 0x70:
                    self._protokollfehler("Der Server benutzt Erweiterungen, die nicht vereinbart wurden.")
                if laenge == 126:
                    laenge = struct.unpack("!H", self._bytes_holen(2, frist))[0]
                elif laenge == 127:
                    laenge = struct.unpack("!Q", self._bytes_holen(8, frist))[0]
                    if laenge >> 63:
                        self._protokollfehler("Der Server schickt eine ungültige Rahmenlänge.")
                if opcode & 0x8 and (not fin or laenge > 125):
                    self._protokollfehler("Der Server schickt einen ungültigen Steuerrahmen.")
                if laenge > self.max_nachricht:
                    self._protokollfehler("Der Server schickt eine zu große Nachricht.", 1009)
                maske = self._bytes_holen(4, frist) if b2 & 0x80 else None
                nutzlast = self._bytes_holen(laenge, frist)
            except socket.timeout:
                if frist is not None and time.monotonic() >= frist:
                    raise WebSocketFehler("Die Zeitgrenze für das Warten auf Nachrichten ist erreicht.")
                raise WebSocketFehler("Der Server hat einen Rahmen nicht zu Ende gesendet (Zeitüberschreitung).")
            if maske:
                nutzlast = self._maskieren(nutzlast, maske)
            return fin, opcode, nutzlast

    def nachrichten_roh(self, frist=None):
        """Erzeugt ``(art, daten)``: ``'text'`` mit str oder ``'binaer'`` mit bytes.

        Beantwortet Ping, setzt Fragmente zusammen und endet beim Close des Servers.
        ``frist`` ist die Gesamtdauer in Sekunden; danach ``WebSocketFehler``.
        """
        ende = None if frist is None else time.monotonic() + frist
        art, teile, gesamt = None, [], 0
        while True:
            try:
                rahmen = self._rahmen_lesen(ende)
            except WebSocketFehler:
                self._zumachen()
                if self._ich_schliesse:
                    return  # selbst geschlossen: kein Fehler
                raise
            if rahmen is None:
                return
            fin, opcode, nutzlast = rahmen
            if opcode == 0x8:  # Close
                self._close_empfangen(nutzlast)
                return
            if opcode == 0x9:  # Ping -> maskiertes Pong mit denselben Daten
                if not self._close_gesendet:
                    self._senden(0xA, nutzlast)
                continue
            if opcode == 0xA:  # Pong: nichts zu tun
                continue
            if opcode not in (0x0, 0x1, 0x2):
                self._protokollfehler("Der Server benutzt einen unbekannten Rahmentyp.")
            if self._close_gesendet:
                continue  # wir haben schon Close geschickt: Nachrichten verfallen
            if opcode == 0x0:
                if art is None:
                    self._protokollfehler("Der Server schickt ein Fragment ohne Anfang.")
            elif art is not None:
                self._protokollfehler("Der Server fängt eine neue Nachricht an, obwohl die alte nicht zu Ende ist.")
            else:
                art, teile, gesamt = ("text" if opcode == 0x1 else "binaer"), [], 0
            gesamt += len(nutzlast)
            if gesamt > self.max_nachricht:
                self._protokollfehler("Der Server schickt eine zu große Nachricht.", 1009)
            teile.append(nutzlast)
            if not fin:
                continue
            daten = b"".join(teile)
            fertig_art, art, teile, gesamt = art, None, [], 0
            if fertig_art == "text":
                try:
                    daten = daten.decode("utf-8")
                except UnicodeDecodeError:
                    self._protokollfehler("Der Server schickt Text, der kein gültiges UTF-8 ist.", 1007)
            yield fertig_art, daten

    def nachrichten(self, frist=None):
        """Erzeugt die Textnachrichten (str). Binärrahmen werden übersprungen.

        Beantwortet Ping, setzt Fragmente zusammen und endet beim Close des Servers.
        ``frist`` ist die Gesamtdauer in Sekunden; danach ``WebSocketFehler``.
        """
        for art, daten in self.nachrichten_roh(frist):
            if art == "text":
                yield daten

    # ------------------------------------------------------------ Schreiben
    @staticmethod
    def _maskieren(daten, maske):
        """XOR mit der 4-Byte-Maske (gilt zum Maskieren wie zum Entmaskieren)."""
        n = len(daten)
        if not n:
            return b""
        schluessel = (maske * (n // 4 + 1))[:n]
        return (int.from_bytes(daten, "big") ^ int.from_bytes(schluessel, "big")).to_bytes(n, "big")

    def _senden(self, opcode, nutzlast=b""):
        """Schickt einen vollständigen, MASKIERTEN Rahmen."""
        n = len(nutzlast)
        kopf = bytearray([0x80 | opcode])
        if n < 126:
            kopf.append(0x80 | n)
        elif n < 65536:
            kopf.append(0x80 | 126)
            kopf += struct.pack("!H", n)
        else:
            kopf.append(0x80 | 127)
            kopf += struct.pack("!Q", n)
        maske = os.urandom(4)
        rahmen = bytes(kopf) + maske + self._maskieren(nutzlast, maske)
        with self._sende_sperre:
            if self._fertig.is_set():
                raise WebSocketFehler("Die Verbindung ist schon geschlossen.")
            try:
                self._sock.sendall(rahmen)
            except socket.timeout:
                raise WebSocketFehler("Zeitüberschreitung beim Senden.")
            except OSError:
                raise WebSocketFehler("Senden nicht möglich: Die Verbindung ist abgebrochen.")

    def senden(self, daten):
        """Schickt eine Nachricht: ``str`` als Text, ``bytes`` als Binärrahmen."""
        if isinstance(daten, str):
            self._senden(0x1, daten.encode("utf-8"))
        else:
            self._senden(0x2, bytes(daten))

    def ping(self, daten=b""):
        """Schickt einen Ping (höchstens 125 Bytes); der Server muss mit Pong antworten."""
        daten = bytes(daten)
        if len(daten) > 125:
            raise WebSocketFehler("Die Daten eines Pings dürfen höchstens 125 Bytes lang sein.")
        self._senden(0x9, daten)

    # ------------------------------------------------------------ Ende
    def _close_senden(self, code=1000, grund=""):
        """Schickt Close (einmal). Fehler dabei sind egal - wir wollen ja ohnehin zu."""
        if self._close_gesendet or self._fertig.is_set():
            return
        self._close_gesendet = True
        nutzlast = b"" if code is None else struct.pack("!H", int(code)) + str(grund).encode("utf-8")[:123]
        try:
            self._senden(0x8, nutzlast)
        except WebSocketFehler:
            pass

    def _close_empfangen(self, nutzlast):
        """Der Server hat Close geschickt: merken, bestätigen, zumachen."""
        if len(nutzlast) >= 2:
            self.schliess_code = struct.unpack("!H", nutzlast[:2])[0]
            self.schliess_grund = nutzlast[2:].decode("utf-8", "replace")
        if not self._close_gesendet:
            self._close_senden(self.schliess_code if len(nutzlast) >= 2 and 1000 <= self.schliess_code < 5000
                               and self.schliess_code not in (1004, 1005, 1006, 1015) else None)
        self._zumachen()

    def _protokollfehler(self, text, code=1002):
        """Der Server verstößt gegen das Protokoll: Close mit Code schicken, zumachen, melden."""
        self._close_senden(code)
        self._zumachen()
        raise WebSocketFehler(text)

    def _zumachen(self):
        """Socket zu und alle Wartenden wecken (mehrfach aufrufbar)."""
        if self._fertig.is_set():
            return
        self._fertig.set()
        sock = self._sock
        if sock is None:
            return
        for aktion in (lambda: sock.shutdown(socket.SHUT_RDWR), sock.close):
            try:
                aktion()
            except Exception:
                pass

    def _auf_close_warten(self):
        """Liest und verwirft Rahmen, bis der Server Close bestätigt oder die Wartezeit um ist."""
        warte = NETZSOCKET_SCHLIESSWARTE if self.timeout is None else min(self.timeout, NETZSOCKET_SCHLIESSWARTE)
        frist = time.monotonic() + warte
        try:
            while True:
                rahmen = self._rahmen_lesen(frist)
                if rahmen is None or rahmen[1] == 0x8:
                    if rahmen is not None and len(rahmen[2]) >= 2:
                        self.schliess_code = struct.unpack("!H", rahmen[2][:2])[0]
                        self.schliess_grund = rahmen[2][2:].decode("utf-8", "replace")
                    return
        except (WebSocketFehler, OSError):
            return

    def schliessen(self, code=1000, grund=""):
        """Schickt einen maskierten Close-Rahmen, wartet kurz auf die Antwort und macht zu.

        Darf auch aus einem anderen Faden kommen, während ``nachrichten()`` liest:
        dann beendet sich der Erzeuger ohne Fehler.
        """
        if self._fertig.is_set():
            return
        self._ich_schliesse = True
        self._close_senden(code, grund)
        if self._lese_sperre.acquire(False):  # niemand liest gerade: Antwort selbst abwarten
            try:
                self._auf_close_warten()
            finally:
                self._lese_sperre.release()
        else:  # ein Leser läuft: er sieht die Antwort und meldet sich über _fertig
            self._fertig.wait(NETZSOCKET_SCHLIESSWARTE)
        self._zumachen()

    def __enter__(self):
        return self

    def __exit__(self, *_):
        self.schliessen()
        return False


def netzsocket_selbsttest():
    """Spielt alle Fälle gegen einen kleinen WebSocket-Server auf 127.0.0.1 durch.

    Kein Internet nötig, dauert unter zwei Sekunden. Liefert eine Liste von
    ``(Fall, bestanden, Einzelheit)``; alles bestanden, wenn jedes ``bestanden`` wahr ist.
    """
    ergebnisse = []

    class Gegenstelle:
        """Die Serverseite eines Falls: liest Client-Rahmen, schreibt Server-Rahmen."""

        def __init__(self, conn):
            self.conn = conn
            self.puffer = b""
            self.kopf = {}

        def genau(self, n):
            while len(self.puffer) < n:
                stueck = self.conn.recv(65536)
                if not stueck:
                    raise EOFError("Client weg")
                self.puffer += stueck
            daten, self.puffer = self.puffer[:n], self.puffer[n:]
            return daten

        def begruessen(self, accept_falsch=False, status="101 Switching Protocols"):
            while b"\r\n\r\n" not in self.puffer:
                stueck = self.conn.recv(4096)
                if not stueck:
                    raise EOFError("Client weg")
                self.puffer += stueck
            kopf, _, self.puffer = self.puffer.partition(b"\r\n\r\n")
            zeilen = kopf.decode("latin-1").split("\r\n")
            self.kopf = {"_anfrage": zeilen[0]}
            for zeile in zeilen[1:]:
                name, _, wert = zeile.partition(":")
                self.kopf[name.strip().lower()] = wert.strip()
            accept = base64.b64encode(hashlib.sha1(
                (self.kopf.get("sec-websocket-key", "") + NETZSOCKET_GUID).encode()).digest())
            if accept_falsch:
                accept = base64.b64encode(hashlib.sha1(b"falsch").digest())
            self.conn.sendall(b"HTTP/1.1 " + status.encode() + b"\r\nUpgrade: websocket\r\n"
                              b"Connection: Upgrade\r\nSec-WebSocket-Accept: " + accept + b"\r\n\r\n")

        def senden(self, opcode, daten=b"", fin=True, rsv=0):
            n = len(daten)
            kopf = bytes([(0x80 if fin else 0) | rsv | opcode])
            if n < 126:
                kopf += bytes([n])
            elif n < 65536:
                kopf += bytes([126]) + struct.pack("!H", n)
            else:
                kopf += bytes([127]) + struct.pack("!Q", n)
            self.conn.sendall(kopf + daten)

        def lesen(self):
            """Ein Client-Rahmen: (opcode, maskiert, nutzlast, fin)."""
            b1, b2 = self.genau(2)
            n = b2 & 0x7F
            if n == 126:
                n = struct.unpack("!H", self.genau(2))[0]
            elif n == 127:
                n = struct.unpack("!Q", self.genau(8))[0]
            maske = self.genau(4) if b2 & 0x80 else None
            daten = self.genau(n)
            if maske:
                daten = WebSocketLeser._maskieren(daten, maske)
            return b1 & 0x0F, bool(b2 & 0x80), daten, bool(b1 & 0x80)

    def fall(name, server, client, **optionen):
        """Startet den Server-Teil in einem Faden und führt den Client-Teil aus."""
        lauscher = socket.socket()
        lauscher.bind(("127.0.0.1", 0))
        lauscher.listen(1)
        notiz = {}

        def dienst():
            try:
                conn, _ = lauscher.accept()
                conn.settimeout(5)
                try:
                    server(Gegenstelle(conn), notiz)
                finally:
                    conn.close()
            except Exception as fehler:
                notiz["serverfehler"] = "%s: %s" % (type(fehler).__name__, fehler)
            finally:
                lauscher.close()

        faden = threading.Thread(target=dienst, daemon=True)
        faden.start()
        url = "ws://127.0.0.1:%d/ws?x=1" % lauscher.getsockname()[1]
        try:
            ok, detail = client(url, notiz, lambda: faden.join(5), optionen)
        except Exception as fehler:
            ok, detail = False, "%s: %s" % (type(fehler).__name__, fehler)
        faden.join(5)
        if "serverfehler" in notiz:
            ok, detail = False, "Server: " + notiz["serverfehler"]
        ergebnisse.append((name, bool(ok), detail or ""))

    def fehler_von(url, **kw):
        """Baut die Verbindung und liest alles; liefert den WebSocketFehler oder None."""
        try:
            ws = WebSocketLeser(url, **kw)
            list(ws.nachrichten())
        except WebSocketFehler as fehler:
            return fehler
        return None

    gross = bytes(i % 251 for i in range(70000))

    # 1. Handschlag, Kopfzeilen, Text, Close
    def s1(g, n):
        g.begruessen()
        g.senden(0x1, '{"a": "Grüße"}'.encode())
        g.senden(0x8, struct.pack("!H", 1000) + b"fertig")
        n["echo"] = g.lesen()

    def c1(url, n, warten, o):
        ws = WebSocketLeser(url, {"Authorization": "Bearer geheim"})
        texte = list(ws.nachrichten())
        warten()
        return (texte == ['{"a": "Grüße"}'] and ws.schliess_code == 1000 and ws.schliess_grund == "fertig"
                and not ws.offen and n["echo"][0] == 0x8 and n["echo"][1] and n["echo"][2][:2] == b"\x03\xe8"), \
            "Text %r, Close %s %r" % (texte, ws.schliess_code, ws.schliess_grund)

    fall("Handschlag, Text, Close mit Antwort", s1, c1)

    # 2. Kopf des Handschlags
    def s2(g, n):
        g.begruessen()
        n["kopf"] = g.kopf
        g.senden(0x8, struct.pack("!H", 1000))

    def c2(url, n, warten, o):
        WebSocketLeser(url, {"Authorization": "Bearer geheim"}).schliessen()
        warten()
        k = n["kopf"]
        ok = (k["_anfrage"] == "GET /ws?x=1 HTTP/1.1" and k["upgrade"] == "websocket"
              and k["sec-websocket-version"] == "13" and k["authorization"] == "Bearer geheim"
              and len(base64.b64decode(k["sec-websocket-key"])) == 16 and k["host"].startswith("127.0.0.1:"))
        return ok, k["_anfrage"]

    fall("Handschlag-Kopf (Schlüssel, Version, Kopfzeile)", s2, c2)

    # 3. Ping -> maskiertes Pong; Fragmente mit Ping dazwischen; 126- und 127-Länge
    def s3(g, n):
        g.begruessen()
        g.senden(0x9, b"hallo")
        n["pong"] = g.lesen()
        text = ("x" * 40 + "ä" * 30).encode()
        g.senden(0x1, text[:20], fin=False)
        g.senden(0x9, b"mitten")
        g.senden(0x0, text[20:61], fin=False)
        g.senden(0x0, text[61:])
        n["pong2"] = g.lesen()
        g.senden(0x1, b"y" * 200)
        g.senden(0x1, gross.hex().encode()[:70000])
        g.senden(0x2, b"\x00\x01\xff")  # Binärrahmen wird übersprungen
        g.senden(0x8, struct.pack("!H", 1001))
        n["close"] = g.lesen()

    def c3(url, n, warten, o):
        ws = WebSocketLeser(url)
        texte = list(ws.nachrichten())
        warten()
        erwartet = ["x" * 40 + "ä" * 30, "y" * 200, gross.hex()[:70000]]
        ok = (texte == erwartet and n["pong"][0] == 0xA and n["pong"][1] and n["pong"][2] == b"hallo"
              and n["pong2"][0] == 0xA and n["pong2"][2] == b"mitten" and n["close"][1]
              and ws.schliess_code == 1001)
        return ok, "%d Nachrichten (%s Zeichen)" % (len(texte), ", ".join(str(len(t)) for t in texte))

    fall("Ping/Pong, Fragmente, Länge 126 und 127", s3, c3)

    # 4. Der Client schickt große Nachrichten maskiert (126 und 127)
    def s4(g, n):
        g.begruessen()
        n["rahmen"] = [g.lesen(), g.lesen(), g.lesen()]
        g.senden(0x8, struct.pack("!H", 1000))
        n["close"] = g.lesen()

    def c4(url, n, warten, o):
        ws = WebSocketLeser(url)
        ws.senden("k" * 5)
        ws.senden("b" * 300)
        ws.senden(gross)
        list(ws.nachrichten())
        warten()
        r = n["rahmen"]
        ok = (all(x[1] for x in r) and r[0][2] == b"kkkkk" and r[1][2] == b"b" * 300
              and r[1][0] == 0x1 and r[2][0] == 0x2 and r[2][2] == gross)
        return ok, "Client-Rahmen alle maskiert: %s" % [len(x[2]) for x in r]

    fall("Client-Rahmen maskiert (125, 126, 127)", s4, c4)

    # 5. schliessen() schickt einen maskierten Close und wartet auf die Antwort
    def s5(g, n):
        g.begruessen()
        n["close"] = g.lesen()
        g.senden(0x8, struct.pack("!H", 1000))

    def c5(url, n, warten, o):
        ws = WebSocketLeser(url)
        ws.schliessen()
        warten()
        c = n["close"]
        return (c[0] == 0x8 and c[1] and c[2][:2] == b"\x03\xe8" and not ws.offen), "Close-Code %s" % c[2][:2].hex()

    fall("schliessen() schickt maskiertes Close", s5, c5)

    # 6. falscher Accept, falscher Status
    def s6(g, n):
        g.begruessen(accept_falsch=True)

    def c6(url, n, warten, o):
        f = fehler_von(url)
        return f is not None and "Handschlag abgelehnt" in str(f), str(f)

    fall("Falscher Accept wird abgewiesen", s6, c6)

    def s7(g, n):
        g.begruessen(status="403 Forbidden")

    def c7(url, n, warten, o):
        f = fehler_von(url)
        return f is not None and "403" in str(f) and "geheim" not in str(f), str(f)

    fall("HTTP 403 beim Handschlag", s7, c7)

    # 8. Stille: erst Ping, dann Abbruch
    def s8(g, n):
        g.begruessen()
        n["ping"] = g.lesen()
        time.sleep(0.6)

    def c8(url, n, warten, o):
        t0 = time.monotonic()
        f = fehler_von(url, timeout=0.25)
        dauer = time.monotonic() - t0
        warten()
        return (f is not None and "antwortet nicht mehr" in str(f) and n["ping"][0] == 0x9 and n["ping"][1]
                and dauer < 2), "%s nach %.2f s" % (f, dauer)

    fall("Stille: Ping, dann Abbruch", s8, c8)

    # 9. Gesamtfrist
    def s9(g, n):
        g.begruessen()
        for _ in range(8):
            time.sleep(0.1)
            g.senden(0xA)  # Pong hält die Verbindung am Leben, bringt aber keine Nachricht

    def c9(url, n, warten, o):
        ws = WebSocketLeser(url, timeout=5)
        t0 = time.monotonic()
        try:
            list(ws.nachrichten(frist=0.4))
        except WebSocketFehler as fehler:
            dauer = time.monotonic() - t0
            return "Zeitgrenze" in str(fehler) and dauer < 1.5, "%s nach %.2f s" % (fehler, dauer)
        return False, "kein Fehler"

    fall("Gesamtfrist nachrichten(frist=…)", s9, c9)

    # 10. Verbindung ohne Close abgerissen
    def s10(g, n):
        g.begruessen()
        g.conn.sendall(b"\x81\x05ab")  # halber Rahmen, dann Ende

    def c10(url, n, warten, o):
        f = fehler_von(url)
        return f is not None, str(f)

    fall("Abbruch mitten im Rahmen", s10, c10)

    # 11. Protokollverstöße: Erweiterungsbit, unbekannter Opcode, Fragment ohne Anfang, ungültiges UTF-8
    for name, rahmenfolge, wort in (
            ("Erweiterungsbit", lambda g: g.senden(0x1, b"x", rsv=0x40), "Erweiterungen"),
            ("unbekannter Opcode", lambda g: g.senden(0x3, b"x"), "unbekannten"),
            ("Fragment ohne Anfang", lambda g: g.senden(0x0, b"x"), "ohne Anfang"),
            ("ungültiges UTF-8", lambda g: g.senden(0x1, b"\xff\xfe"), "UTF-8"),
            ("zerrissener Ping", lambda g: g.senden(0x9, b"x", fin=False), "Steuerrahmen")):
        def sv(g, n, rahmenfolge=rahmenfolge):
            g.begruessen()
            rahmenfolge(g)
            try:
                n["close"] = g.lesen()
            except EOFError:
                pass

        def cv(url, n, warten, o, wort=wort):
            f = fehler_von(url)
            warten()
            code = n.get("close", (0, 0, b"\0\0"))[2][:2]
            return f is not None and wort in str(f) and code in (b"\x03\xea", b"\x03\xef"), \
                "%s / Close-Code %s" % (f, code.hex())

        fall("Protokollverstoß: " + name, sv, cv)

    # 12. zu große Nachricht
    def s12(g, n):
        g.begruessen()
        g.senden(0x1, b"z" * 5000)
        try:
            n["close"] = g.lesen()
        except EOFError:
            pass

    def c12(url, n, warten, o):
        f = fehler_von(url, max_nachricht=1000)
        warten()
        return f is not None and "zu große" in str(f) and n.get("close", (0, 0, b""))[2][:2] == b"\x03\xf1", str(f)

    fall("zu große Nachricht (Close 1009)", s12, c12)

    # 13. schliessen() aus einem zweiten Faden beendet den Leser ohne Fehler
    def s13(g, n):
        g.begruessen()
        n["close"] = g.lesen()
        g.senden(0x8, struct.pack("!H", 1000))

    def c13(url, n, warten, o):
        ws = WebSocketLeser(url)
        ergebnis = {}

        def lesen():
            try:
                ergebnis["texte"] = list(ws.nachrichten())
            except Exception as fehler:
                ergebnis["fehler"] = fehler

        leser = threading.Thread(target=lesen, daemon=True)
        leser.start()
        time.sleep(0.15)
        ws.schliessen()
        leser.join(3)
        warten()
        return ("texte" in ergebnis and not leser.is_alive() and n["close"][0] == 0x8), str(ergebnis)

    fall("schliessen() aus anderem Faden", s13, c13)

    # 14. eingespeiste Verbindung (socketpair), kein Netz
    paar_server, paar_client = socket.socketpair()
    notiz14 = {}

    def s14():
        try:
            paar_server.settimeout(5)
            g = Gegenstelle(paar_server)
            g.begruessen()
            g.senden(0x1, b"eins")
            g.senden(0x8, struct.pack("!H", 1000))
            notiz14["close"] = g.lesen()
        except Exception as fehler:
            notiz14["serverfehler"] = repr(fehler)

    faden14 = threading.Thread(target=s14, daemon=True)
    faden14.start()
    aufrufe = []
    try:
        ws14 = WebSocketLeser("wss://beispiel.test:8443/live", verbinden=lambda h, p, t: (aufrufe.append((h, p, t)),
                                                                                         paar_client)[1])
        texte14 = list(ws14.nachrichten())
        faden14.join(5)
        ergebnisse.append(("Eingespeiste Verbindung (socketpair)",
                           texte14 == ["eins"] and aufrufe == [("beispiel.test", 8443, True)]
                           and notiz14.get("close", (0, 0))[1] is True and "serverfehler" not in notiz14,
                           "aufgerufen mit %s" % (aufrufe,)))
    except Exception as fehler:
        ergebnisse.append(("Eingespeiste Verbindung (socketpair)", False, repr(fehler)))
    finally:
        paar_server.close()
        paar_client.close()

    # 15. Adressen und Kopfzeilen werden geprüft
    schlecht = []
    for url, kopf in (("http://x.test/", None), ("wss://", None), ("", None), ("ws://x.test:abc/", None),
                      ("ws://x.test/", {"Host": "a"}), ("ws://x.test/", {"X": "a\r\nB: c"})):
        try:
            WebSocketLeser(url, kopf, verbinden=lambda h, p, t: (_ for _ in ()).throw(AssertionError("verbunden")))
            schlecht.append(url)
        except WebSocketFehler:
            pass
        except Exception as fehler:
            schlecht.append("%s -> %r" % (url, fehler))
    ergebnisse.append(("Ungültige Adressen und Kopfzeilen", not schlecht, ", ".join(schlecht) or "alle abgewiesen"))
    return ergebnisse


# =========================================================================
# stimmanbieter  -  Die Anbieterkette der Sprachausgabe mit Pegel für den Orb – wird in Paket P6 gebaut.
# =========================================================================

#!/usr/bin/env python3
# -*- coding: utf-8 -*-


# =========================================================================
# voice  -  Sprache - Mikrofon rein, Stimme raus.
# 
# Beides ist mehrstufig aufgebaut, damit **ein einziger Schlüssel** genügt:
# 
#     Stimme raus:  ElevenLabs (falls Schlüssel) -> macOS ``say`` (immer da, gratis)
#     Sprache rein: faster-whisper lokal (gratis) -> Whisper-API (falls Schlüssel)
# 
# Aufgenommen wird bis zur Sprechpause, nicht in festen Blöcken. Feste Blöcke
# schneiden entweder mitten im Satz ab oder lassen den Nutzer nach dem letzten
# Wort warten - beides fällt im Alltag sofort unangenehm auf.
# =========================================================================

#!/usr/bin/env python3
# -*- coding: utf-8 -*-






# Die Spracherkennung schreibt den Namen selten korrekt. Alle diese Formen
# werden als Weckwort akzeptiert.
WECKWOERTER = ["hey jarvis", "hey javis", "hey dscharvis", "hey charvis",
               "hey travis", "hey jervis", "hey dscharvis", "jarvis", "javis"]

# Bevorzugte deutsche Systemstimmen, in dieser Reihenfolge.
WUNSCHSTIMMEN = ["Markus", "Yannick", "Petra", "Anna", "Viktor"]


def beste_deutsche_stimme(liste: str) -> str:
    """Wählt aus der Ausgabe von ``say -v ?`` die natürlichste deutsche Stimme."""
    stimmen = []
    for zeile in (liste or "").splitlines():
        treffer = re.match(r"^(.+?)\s+([a-z]{2}_[A-Z]{2})\s+#", zeile)
        if treffer:
            stimmen.append((treffer.group(1).strip(), treffer.group(2)))
    deutsch = [name for name, sprache in stimmen if sprache in ("de_DE", "de_AT", "de_CH")]
    if not deutsch:
        return ""

    def rang(name):
        klein = name.lower()
        guete = 0 if "premium" in klein else 1 if ("erweitert" in klein or "enhanced" in klein) else 2
        grund = name.split(" (")[0]
        wunsch = WUNSCHSTIMMEN.index(grund) if grund in WUNSCHSTIMMEN else len(WUNSCHSTIMMEN)
        return (guete, wunsch)

    return sorted(deutsch, key=rang)[0]

# Kurze Signaltöne - der Nutzer hört so, in welchem Zustand Jarvis ist.
SIGNALTOENE = {
    "zuhoeren": "/System/Library/Sounds/Tink.aiff",
    "verstanden": "/System/Library/Sounds/Pop.aiff",
    "fehler": "/System/Library/Sounds/Basso.aiff",
}

# Aufnahmeparameter
ABTASTRATE = 16000
BLOCK_SEKUNDEN = 0.1
STILLE_BIS_ENDE = 1.2
MAX_AUFNAHME = 25.0
MIN_AUFNAHME = 0.4
PEGEL_UNTERGRENZE = 0.004
PEGEL_FAKTOR = 3.5

ELEVENLABS_URL = "https://api.elevenlabs.io/v1"
WHISPER_URL = "https://api.openai.com/v1/audio/transcriptions"


def mikrofon_fehlermeldung() -> str:
    """Sagt genau, was fuer die Aufnahme fehlt - Paket oder Tonbibliothek.

    ``sounddevice`` laesst sich zwar installieren, wirft beim Import aber
    ``OSError``, wenn die Bibliothek PortAudio fehlt. Wer dann liest, das
    Paket fehle, installiert es ein zweites Mal und wundert sich. Deshalb
    wird nachgesehen, ob das Paket da ist, und nur der wirklich fehlende
    Teil genannt.
    """
    if np is None:
        return "Es fehlt das Paket numpy."
    if sd is not None:
        return ""
    try:
        vorhanden = importlib.util.find_spec("sounddevice") is not None
    except (ImportError, ValueError):
        vorhanden = False
    if vorhanden:
        return ("Die Tonbibliothek PortAudio fehlt. Im Terminal eingeben: "
                "brew install portaudio")
    return "Es fehlt das Paket sounddevice."


def text_fuers_sprechen(text: str) -> str:
    """Der Text, so wie ein Mensch ihn sagen würde (siehe ``sprechtext``)."""
    return sprechtext(text)


def weckwort_pruefen(text: str):
    """Prüft auf das Weckwort und schneidet es ab.

    Gibt ``(erkannt, restlicher_befehl)`` zurück.
    """
    if not text:
        return False, ""
    roh = str(text).strip()
    klein = re.sub(r"[^a-zä-ü0-9 ]+", " ", roh.lower())
    klein = re.sub(r"\s+", " ", klein).strip()
    for weckwort in WECKWOERTER:
        if klein == weckwort:
            return True, ""
        if klein.startswith(weckwort + " "):
            rest = klein[len(weckwort):].strip(" ,.")
            # Den Rest aus dem Originaltext holen, damit Groß- und Kleinschreibung bleibt.
            stelle = roh.lower().find(rest[:20].lower()) if rest else -1
            return True, (roh[stelle:].strip(" ,.") if stelle >= 0 else rest)
    return False, ""


class Stimme:
    """Sprachausgabe und Spracheingabe mit jeweils zwei Ebenen."""

    def __init__(self):
        self.macos_stimme = ""
        self._whisper_modell = None
        self._temp = tempfile.mkdtemp(prefix="jarvis_audio_")
        self.letzter_fehler = ""
        self._stopp = threading.Event()
        self._abspiel_prozess = None
        # Nur die Aufnahme setzt das: Mikrofon fehlt oder lässt sich nicht öffnen.
        self.mikro_fehler = ""
        if self.ist_macos():
            self.macos_stimme = MACOS_STIMME or self.deutsche_stimme_suchen()

    # -- Umgebung -----------------------------------------------------------

    @staticmethod
    def ist_macos() -> bool:
        """Läuft das hier auf einem Mac?"""
        return shutil.which("say") is not None and os.uname().sysname == "Darwin"

    def deutsche_stimme_suchen(self) -> str:
        """Sucht die natürlichste vorhandene deutsche Systemstimme.

        Die Premium- und erweiterten Stimmen (zum Beispiel "Anna (Premium)")
        klingen deutlich menschlicher als die kompakten. Ihre Namen enthalten
        Leerzeichen und Klammern - deshalb wird die Zeile von ``say -v ?`` am
        Sprachkürzel getrennt, nicht am ersten Leerzeichen.
        """
        try:
            ergebnis = subprocess.run(["say", "-v", "?"], capture_output=True,
                                      text=True, timeout=10, shell=False)
        except (OSError, subprocess.SubprocessError):
            return ""
        if ergebnis.returncode != 0:
            return ""
        return beste_deutsche_stimme(ergebnis.stdout)

    def zustand(self) -> dict:
        """Was ist verfügbar, was fehlt - für den Selbsttest."""
        return {
            "macos_say": self.ist_macos(),
            "macos_stimme": self.macos_stimme or "keine deutsche gefunden",
            "elevenlabs": bool(ELEVENLABS_API_KEY),
            "mikrofon": sd is not None and np is not None,
            "mikrofon_grund": mikrofon_fehlermeldung(),
            "whisper_lokal": WhisperModel is not None,
            "whisper_api": bool(OPENAI_API_KEY),
        }

    # -- Ausgabe ------------------------------------------------------------

    def sprich(self, text: str) -> bool:
        """Spricht einen Text so, wie ein Mensch ihn sagen würde.

        Der Text wird zuerst ins Gesprochene übersetzt (Zahlen, Beträge, Daten
        ausgeschrieben, kein Markdown) und in Atemabschnitte geteilt. Mit
        ElevenLabs wird der nächste Abschnitt schon geholt, während der
        vorige läuft: kein Warten dazwischen, und jeder Abschnitt kennt den
        Satz davor und danach, damit die Betonung durchläuft. Ohne ElevenLabs
        spricht die Systemstimme.
        """
        stuecke = sprechstuecke(text)
        if not stuecke:
            return False
        print("Jarvis: %s" % " ".join(stuecke))
        self._stopp.clear()
        gesprochen = 0
        if ELEVENLABS_API_KEY:
            gesprochen = self._elevenlabs_sprechen(stuecke)
            if gesprochen >= len(stuecke):
                return True
            if self._stopp.is_set():
                return True
        # Was ElevenLabs nicht geschafft hat, übernimmt die Systemstimme: der
        # Satz, bei dem es abbrach, wird nicht noch einmal von vorn gesprochen.
        return self._systemstimme_sprechen(" ".join(stuecke[gesprochen:]))

    def stoppen(self):
        """Hält die Sprachausgabe sofort an - etwa wenn der Nutzer dazwischenredet."""
        self._stopp.set()
        prozess = self._abspiel_prozess
        if prozess is not None and prozess.poll() is None:
            try:
                prozess.terminate()
            except OSError:
                pass

    def _elevenlabs_holen(self, text: str, vorher: str = "", nachher: str = "", vorige=None):
        """Holt die Sprachdatei für einen Abschnitt. ``None`` bei Fehler.

        ``vorige`` sind die Kennungen der Abschnitte davor (höchstens drei). Damit
        setzt ElevenLabs Tonfall und Tempo nahtlos fort - die Antwort klingt wie
        in einem Atemzug gesprochen statt wie aneinandergereihte Ansagen.
        """
        self._anfrage_id = None
        ziel = "%s/text-to-speech/%s" % (ELEVENLABS_URL, ELEVENLABS_VOICE_ID)
        inhalt = {
            "text": text[:2500],
            "model_id": ELEVENLABS_MODEL,
            "voice_settings": {
                "stability": ELEVENLABS_STABILITY,
                "similarity_boost": ELEVENLABS_SIMILARITY,
                "style": ELEVENLABS_STYLE,
                "use_speaker_boost": True,
            },
        }
        # Der Satz davor und danach: so wird eine Stimme, die in Stücken
        # spricht, nicht zu lauter einzelnen Ansagen.
        if vorher:
            inhalt["previous_text"] = vorher[-300:]
        if nachher:
            inhalt["next_text"] = nachher[:300]
        if vorige:
            inhalt["previous_request_ids"] = list(vorige)[-3:]
        anfrage = urllib.request.Request(
            ziel, data=json.dumps(inhalt).encode("utf-8"), method="POST", headers={
                "xi-api-key": ELEVENLABS_API_KEY,
                "Content-Type": "application/json",
                "Accept": "audio/mpeg",
            })
        try:
            with urllib.request.urlopen(anfrage, timeout=45) as antwort:
                daten = antwort.read()
                self._anfrage_id = antwort.headers.get("request-id") or None
                return daten
        except (urllib.error.URLError, OSError, http.client.HTTPException, ValueError) as fehler:
            self.letzter_fehler = "ElevenLabs nicht erreichbar: %s" % fehler
            print("[stimme] %s - ich nehme die Systemstimme." % self.letzter_fehler)
            return None

    def _elevenlabs_sprechen(self, stuecke: list) -> int:
        """Spricht Abschnitt für Abschnitt. Gibt zurück, wie viele gesprochen wurden."""
        fertig = queue.Queue(maxsize=2)
        ende = threading.Event()

        def ablegen(eintrag):
            while not ende.is_set():
                try:
                    fertig.put(eintrag, timeout=0.2)
                    return
                except queue.Full:
                    continue

        def holer():
            # Was auch passiert: am Ende liegt immer ein Abschluss in der Warteschlange,
            # sonst wartet die Wiedergabe für immer.
            try:
                kennungen = []
                for nummer, stueck in enumerate(stuecke):
                    if ende.is_set() or self._stopp.is_set():
                        break
                    self._anfrage_id = None
                    zusatz = {"vorige": kennungen[-3:]} if kennungen else {}
                    daten = self._elevenlabs_holen(
                        stueck, stuecke[nummer - 1] if nummer else "",
                        stuecke[nummer + 1] if nummer + 1 < len(stuecke) else "", **zusatz)
                    if getattr(self, "_anfrage_id", None):
                        kennungen.append(self._anfrage_id)
                    ablegen((nummer, daten))
                    if daten is None:
                        return
            except Exception as fehler:
                self.letzter_fehler = "ElevenLabs: %s" % fehler
                ablegen((-1, None))
                return
            finally:
                ablegen(None)

        faden = threading.Thread(target=holer, daemon=True, name="jarvis-stimme-holen")
        faden.start()
        gesprochen = 0
        try:
            while True:
                try:
                    eintrag = fertig.get(timeout=1)
                except queue.Empty:
                    if not faden.is_alive() and fertig.empty():
                        break
                    if self._stopp.is_set():
                        break
                    continue
                if eintrag is None:
                    break
                nummer, daten = eintrag
                if daten is None or self._stopp.is_set():
                    break
                pfad = os.path.join(self._temp, "antwort_%d_%d.mp3"
                                    % (int(time.time() * 1000), nummer))
                try:
                    with open(pfad, "wb") as datei:
                        datei.write(daten)
                except OSError:
                    break
                erfolg = self.abspielen(pfad)
                try:
                    os.remove(pfad)
                except OSError:
                    pass
                if not erfolg:
                    break
                gesprochen += 1
        finally:
            ende.set()
        return gesprochen

    def _systemstimme_sprechen(self, text: str) -> bool:
        """Sprachausgabe über das eingebaute ``say`` von macOS."""
        if not shutil.which("say"):
            return False
        befehl = ["say", "-r", str(int(SPEECH_RATE))]
        if self.macos_stimme:
            befehl += ["-v", self.macos_stimme]
        befehl.append(text[:6000])
        try:
            subprocess.run(befehl, timeout=180, shell=False,
                           stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            return True
        except (OSError, subprocess.SubprocessError) as fehler:
            self.letzter_fehler = "Systemstimme fehlgeschlagen: %s" % fehler
            return False

    def abspielen(self, pfad: str) -> bool:
        """Spielt eine Audiodatei ab: afplay, sonst mpg123, sonst ffplay."""
        if not os.path.exists(pfad):
            return False
        varianten = [["afplay", pfad], ["mpg123", "-q", pfad],
                     ["ffplay", "-nodisp", "-autoexit", "-loglevel", "quiet", pfad]]
        for befehl in varianten:
            if not shutil.which(befehl[0]):
                continue
            try:
                self._abspiel_prozess = subprocess.Popen(
                    befehl, shell=False, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
                rueckgabe = self._abspiel_prozess.wait(timeout=300)
                if rueckgabe == 0 or self._stopp.is_set():
                    return True
            except (OSError, subprocess.SubprocessError):
                continue
            finally:
                self._abspiel_prozess = None
        return False

    def signal(self, name: str):
        """Spielt einen kurzen Signalton - Zustand hörbar machen."""
        pfad = SIGNALTOENE.get(name)
        if not pfad or not os.path.exists(pfad) or not shutil.which("afplay"):
            return
        try:
            subprocess.Popen(["afplay", pfad], shell=False,
                             stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        except (OSError, subprocess.SubprocessError):
            pass

    def _elevenlabs_datei(self, text: str) -> str:
        """Die ganze Antwort mit ElevenLabs als eine MP3-Datei - Abschnitt für Abschnitt,
        nahtlos verbunden. Leer, wenn es nicht klappt."""
        stuecke = sprechstuecke(text)
        teile, kennungen = [], []
        for nummer, stueck in enumerate(stuecke):
            zusatz = {"vorige": kennungen[-3:]} if kennungen else {}
            daten = self._elevenlabs_holen(
                stueck, stuecke[nummer - 1] if nummer else "",
                stuecke[nummer + 1] if nummer + 1 < len(stuecke) else "", **zusatz)
            if not daten:
                return ""
            teile.append(daten)
            if getattr(self, "_anfrage_id", None):
                kennungen.append(self._anfrage_id)
        if not teile:
            return ""
        ziel = os.path.join(self._temp, "nachricht_%d.mp3" % int(time.time() * 1000))
        try:
            with open(ziel, "wb") as datei:
                datei.write(b"".join(teile))
        except OSError:
            return ""
        return ziel

    def sprachdatei_erzeugen(self, text: str, ziel: str = "") -> str:
        """Erzeugt eine Audiodatei aus Text - für Sprachnachrichten per Telegram.

        Mit ElevenLabs klingt auch die Sprachnachricht wie ein Mensch (Telegram
        nimmt MP3 an). Sonst spricht die beste deutsche Mac-Stimme.
        """
        if ELEVENLABS_API_KEY and not ziel:
            datei = self._elevenlabs_datei(text)
            if datei:
                return datei
        sauber = text_fuers_sprechen(text)
        if not sauber or not shutil.which("say"):
            return ""
        ziel = ziel or os.path.join(self._temp, "nachricht_%d.m4a" % int(time.time()))
        befehl = ["say", "-r", str(int(SPEECH_RATE)), "-o", ziel]
        if self.macos_stimme:
            befehl += ["-v", self.macos_stimme]
        befehl.append(sauber[:4000])
        try:
            subprocess.run(befehl, timeout=180, shell=False,
                           stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        except (OSError, subprocess.SubprocessError):
            return ""
        if not os.path.exists(ziel):
            return ""
        # Telegram will für Sprachnachrichten OGG/Opus.
        if shutil.which("ffmpeg"):
            ogg = os.path.splitext(ziel)[0] + ".ogg"
            try:
                subprocess.run(["ffmpeg", "-y", "-i", ziel, "-c:a", "libopus",
                                "-b:a", "32k", ogg], timeout=120, shell=False,
                               stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
                if os.path.exists(ogg):
                    return ogg
            except (OSError, subprocess.SubprocessError):
                pass
        return ziel

    # -- Aufnahme -----------------------------------------------------------

    def mikrofon_bereit(self) -> bool:
        """Ist eine Aufnahme technisch möglich?"""
        return sd is not None and np is not None

    def aufnehmen_bis_pause(self, still_signal: bool = False) -> str:
        """Nimmt auf, bis der Nutzer 1,2 Sekunden nichts mehr sagt.

        Der Raumpegel wird zu Beginn gemessen, damit ein lauter Raum nicht
        dauernd als Sprache gilt und ein leiser nicht überhört wird.
        """
        self.mikro_fehler = ""
        if not self.mikrofon_bereit():
            self.letzter_fehler = self.mikro_fehler = "Kein Mikrofonzugriff. %s" % mikrofon_fehlermeldung()
            return ""
        blockgroesse = int(ABTASTRATE * BLOCK_SEKUNDEN)
        gesammelt = []
        raumpegel_proben = []
        spricht = False
        stille_seit = 0.0
        beginn = time.time()

        try:
            strom = sd.InputStream(samplerate=ABTASTRATE, channels=1, dtype="float32",
                                   blocksize=blockgroesse)
        except Exception as fehler:
            self.letzter_fehler = self.mikro_fehler = (
                "Das Mikrofon lässt sich nicht öffnen: %s. In den Systemeinstellungen unter "
                "Datenschutz das Mikrofon für das Terminal freigeben." % fehler)
            return ""

        try:
            with strom:
                if not still_signal:
                    self.signal("zuhoeren")
                while True:
                    if time.time() - beginn > MAX_AUFNAHME + 6:
                        break
                    block, ueberlauf = strom.read(blockgroesse)
                    del ueberlauf
                    pegel = float(np.sqrt(np.mean(np.square(block))))

                    if len(raumpegel_proben) < 8:
                        raumpegel_proben.append(pegel)
                        if len(raumpegel_proben) == 8:
                            grundpegel = float(np.median(raumpegel_proben))
                            self._schwelle = max(grundpegel * PEGEL_FAKTOR,
                                                 PEGEL_UNTERGRENZE)
                        continue

                    if pegel >= self._schwelle:
                        spricht = True
                        stille_seit = 0.0
                        gesammelt.append(block.copy())
                    elif spricht:
                        stille_seit += BLOCK_SEKUNDEN
                        gesammelt.append(block.copy())
                        if stille_seit >= STILLE_BIS_ENDE:
                            break
                    if spricht and (time.time() - beginn) > MAX_AUFNAHME:
                        break
        except Exception as fehler:
            self.letzter_fehler = self.mikro_fehler = "Die Aufnahme ist abgebrochen: %s" % fehler
            return ""

        if not gesammelt:
            return ""
        daten = np.concatenate(gesammelt, axis=0)
        dauer = len(daten) / float(ABTASTRATE)
        if dauer < MIN_AUFNAHME:
            return ""  # Zu kurz - das war ein Geräusch, kein Satz.

        pfad = os.path.join(self._temp, "aufnahme_%d.wav" % int(time.time() * 1000))
        try:
            ganzzahlen = (np.clip(daten, -1.0, 1.0) * 32767).astype("int16")
            with wave.open(pfad, "wb") as datei:
                datei.setnchannels(1)
                datei.setsampwidth(2)
                datei.setframerate(ABTASTRATE)
                datei.writeframes(ganzzahlen.tobytes())
        except (OSError, ValueError) as fehler:
            self.letzter_fehler = "Die Aufnahme ließ sich nicht speichern: %s" % fehler
            return ""
        return pfad

    # -- Erkennung ----------------------------------------------------------

    def transkribieren(self, wav_pfad: str) -> str:
        """Wandelt eine Audiodatei in Text - lokal, sonst über die Whisper-API."""
        if not wav_pfad or not os.path.exists(wav_pfad):
            return ""
        text = self._whisper_lokal(wav_pfad)
        if text:
            return text
        return self._whisper_api(wav_pfad)

    def _whisper_lokal(self, wav_pfad: str) -> str:
        """Spracherkennung mit faster-whisper direkt auf dem Rechner (kostenlos)."""
        if WhisperModel is None:
            return ""
        try:
            if self._whisper_modell is None:
                print("[stimme] Lade das Spracherkennungsmodell, das dauert einmalig ...")
                self._whisper_modell = WhisperModel(
                    WHISPER_MODELL, device="cpu", compute_type="int8")
            teile, _ = self._whisper_modell.transcribe(wav_pfad, language="de",
                                                       beam_size=1, vad_filter=True)
            return " ".join(teil.text.strip() for teil in teile).strip()
        except Exception as fehler:
            self.letzter_fehler = "Lokale Spracherkennung fehlgeschlagen: %s" % fehler
            print("[stimme] %s" % self.letzter_fehler)
            return ""

    def _whisper_api(self, wav_pfad: str) -> str:
        """Rückfallebene: Whisper über die OpenAI-Schnittstelle."""
        if not OPENAI_API_KEY:
            return ""
        grenze = "----jarvis%d" % int(time.time() * 1000)
        try:
            with open(wav_pfad, "rb") as datei:
                audio = datei.read()
        except OSError:
            return ""
        teile = []
        for name, wert in (("model", "whisper-1"), ("language", "de")):
            teile.append(("--%s\r\nContent-Disposition: form-data; name=\"%s\"\r\n\r\n%s\r\n"
                          % (grenze, name, wert)).encode("utf-8"))
        teile.append(("--%s\r\nContent-Disposition: form-data; name=\"file\"; "
                      "filename=\"audio.wav\"\r\nContent-Type: audio/wav\r\n\r\n"
                      % grenze).encode("utf-8"))
        teile.append(audio)
        teile.append(("\r\n--%s--\r\n" % grenze).encode("utf-8"))

        anfrage = urllib.request.Request(WHISPER_URL, data=b"".join(teile), method="POST",
                                         headers={
                                             "Authorization": "Bearer %s" % OPENAI_API_KEY,
                                             "Content-Type":
                                                 "multipart/form-data; boundary=%s" % grenze})
        try:
            with urllib.request.urlopen(anfrage, timeout=90) as antwort:
                return json.loads(antwort.read().decode("utf-8")).get("text", "").strip()
        except (urllib.error.URLError, OSError, ValueError) as fehler:
            self.letzter_fehler = "Whisper-API fehlgeschlagen: %s" % fehler
            return ""

    def zuhoeren(self) -> str:
        """Einmal aufnehmen und in Text wandeln."""
        pfad = self.aufnehmen_bis_pause()
        if not pfad:
            return ""
        try:
            text = self.transkribieren(pfad)
        finally:
            try:
                os.remove(pfad)
            except OSError:
                pass
        if text:
            print("Du: %s" % text)
        return text


# =========================================================================
# speaker  -  Stimmprofil - erkennt, ob gerade der Nutzer spricht.
# 
# **Ehrliche Einordnung, die auch so in der Anleitung steht:** Das unterscheidet
# Sprecher im Alltag zuverlässig, ist aber *kein* Schutz gegen eine abgespielte
# Aufnahme. Wer eine Sprachaufnahme des Nutzers besitzt, kommt hier durch.
# 
# Deshalb gilt im ganzen Programm: Die Stimme entscheidet nur, **ob Jarvis
# zuhört**. Sie gibt niemals eine Mail, eine Buchung oder eine Bildschirmaktion
# frei - dafür ist ausschließlich die ausdrückliche Freigabe zuständig.
# =========================================================================

#!/usr/bin/env python3
# -*- coding: utf-8 -*-





PROFIL_DATEI = "stimmprofil.json"
PROBEN_ANZAHL = 5

# Sätze, die der Nutzer beim Einlernen nachspricht - unterschiedlich lang und
# klanglich verschieden, das macht das Profil stabiler.
LERNSAETZE = [
    "Hey Jarvis, wie sieht mein Tag aus?",
    "Ich war heute bei einem Kunden und wir haben über den Preis gesprochen.",
    "Erfass bitte die Quittung von der Tankstelle.",
    "Was ist diese Woche noch offen bei mir?",
    "Feierabend, mach den Abendrückblick.",
]


class Sprecherprofil:
    """Legt ein Stimmprofil an und vergleicht spätere Aufnahmen damit."""

    def __init__(self, verzeichnis=None):
        self.verzeichnis = str(verzeichnis or PROFIL_VERZEICHNIS)
        self.pfad = os.path.join(self.verzeichnis, PROFIL_DATEI)
        self._encoder = None
        self.profil = self._profil_laden()

    # -- Verfügbarkeit ------------------------------------------------------

    def verfuegbar(self) -> bool:
        """Ist die Stimmerkennung technisch nutzbar?"""
        return VoiceEncoder is not None and np is not None

    def eingelernt(self) -> bool:
        """Liegt bereits ein Profil vor?"""
        return bool(self.profil)

    def zustand(self) -> dict:
        """Kurzer Überblick für den Selbsttest."""
        return {"paket_da": self.verfuegbar(), "profil_da": self.eingelernt(),
                "schwelle": STIMM_SCHWELLE, "pfad": self.pfad,
                "aktiv": bool(STIMMPRUEFUNG_AN)}

    # -- Profil laden und speichern ----------------------------------------

    def _profil_laden(self):
        """Liest ein vorhandenes Profil von der Platte."""
        try:
            if os.path.exists(self.pfad):
                with open(self.pfad, "r", encoding="utf-8") as datei:
                    daten = json.load(datei)
                vektor = daten.get("vektor")
                if vektor and np is not None:
                    return np.array(vektor, dtype="float32")
                return vektor
        except (OSError, ValueError) as fehler:
            print("[stimme] Stimmprofil nicht lesbar: %s" % fehler)
        return None

    def _profil_speichern(self, vektor) -> bool:
        """Schreibt das Profil auf die Platte."""
        try:
            os.makedirs(self.verzeichnis, exist_ok=True)
            with open(self.pfad, "w", encoding="utf-8") as datei:
                json.dump({"vektor": [float(wert) for wert in vektor],
                           "angelegt": time.strftime("%Y-%m-%d %H:%M:%S")},
                          datei)
            return True
        except (OSError, ValueError) as fehler:
            print("[stimme] Stimmprofil nicht speicherbar: %s" % fehler)
            return False

    def profil_loeschen(self) -> bool:
        """Verwirft das Stimmprofil."""
        self.profil = None
        try:
            if os.path.exists(self.pfad):
                os.remove(self.pfad)
            return True
        except OSError:
            return False

    # -- Einlernen ----------------------------------------------------------

    def _encoder_holen(self):
        """Lädt das Sprechermodell einmalig."""
        if self._encoder is None and VoiceEncoder is not None:
            self._encoder = VoiceEncoder()
        return self._encoder

    def vektor_aus_datei(self, wav_pfad: str):
        """Rechnet eine Aufnahme in einen Stimmvektor um."""
        if not self.verfuegbar() or not wav_pfad or not os.path.exists(wav_pfad):
            return None
        try:
            welle = preprocess_wav(wav_pfad)
            return self._encoder_holen().embed_utterance(welle)
        except Exception as fehler:
            print("[stimme] Aufnahme nicht auswertbar: %s" % fehler)
            return None

    def einlernen(self, stimme=None) -> dict:
        """Nimmt fünf Proben auf, mittelt die Vektoren und legt das Profil ab."""
        if not self.verfuegbar():
            return {"ok": False,
                    "fehler": "Für die Stimmerkennung fehlt das Paket resemblyzer. "
                              "Ohne sie funktioniert alles andere weiter."}
        if stimme is None:
            return {"ok": False, "fehler": "Zum Einlernen brauche ich das Mikrofon."}
        if not stimme.mikrofon_bereit():
            return {"ok": False,
                    "fehler": "Das Mikrofon ist nicht verfügbar. Bitte in den "
                              "Systemeinstellungen unter Datenschutz freigeben."}

        vektoren = []
        stimme.sprich("Ich lerne jetzt deine Stimme. Sprich mir bitte fünf Sätze nach.")
        for nummer in range(PROBEN_ANZAHL):
            satz = LERNSAETZE[nummer % len(LERNSAETZE)]
            stimme.sprich("Satz %d von %d. %s" % (nummer + 1, PROBEN_ANZAHL, satz))
            pfad = stimme.aufnehmen_bis_pause()
            if not pfad:
                stimme.sprich("Da war nichts zu hören. Ich versuche es noch einmal.")
                pfad = stimme.aufnehmen_bis_pause()
            vektor = self.vektor_aus_datei(pfad) if pfad else None
            if pfad:
                try:
                    os.remove(pfad)
                except OSError:
                    pass
            if vektor is None:
                stimme.sprich("Diese Probe war unbrauchbar, ich überspringe sie.")
                continue
            vektoren.append(vektor)

        if len(vektoren) < 3:
            return {"ok": False,
                    "fehler": "Ich habe nur %d brauchbare Proben bekommen. Bitte in "
                              "einer ruhigeren Umgebung noch einmal versuchen."
                              % len(vektoren)}

        gemittelt = np.mean(np.stack(vektoren), axis=0)
        gemittelt = gemittelt / (np.linalg.norm(gemittelt) + 1e-9)
        self.profil = gemittelt
        gespeichert = self._profil_speichern(gemittelt)
        return {"ok": gespeichert, "proben": len(vektoren),
                "text": "Stimmprofil aus %d Proben angelegt. Ab jetzt reagiere ich "
                        "bevorzugt auf deine Stimme." % len(vektoren)}

    # -- Prüfen -------------------------------------------------------------

    def aehnlichkeit(self, wav_pfad: str):
        """Kosinus-Ähnlichkeit einer Aufnahme zum Profil, oder ``None``."""
        if self.profil is None or not self.verfuegbar():
            return None
        vektor = self.vektor_aus_datei(wav_pfad)
        if vektor is None:
            return None
        try:
            a = np.asarray(vektor, dtype="float32")
            b = np.asarray(self.profil, dtype="float32")
            wert = float(np.dot(a, b) / ((np.linalg.norm(a) * np.linalg.norm(b)) + 1e-9))
            return wert
        except Exception:
            return None

    def ist_der_nutzer(self, wav_pfad: str) -> dict:
        """Entscheidet, ob die Aufnahme vom Nutzer stammt.

        Ohne Profil oder ohne Paket lautet die Antwort immer ja - die Prüfung
        darf niemand aussperren, den sie gar nicht beurteilen kann.
        """
        if not STIMMPRUEFUNG_AN or self.profil is None or not self.verfuegbar():
            return {"erkannt": True, "wert": None, "grund": "Stimmprüfung ist nicht aktiv."}
        wert = self.aehnlichkeit(wav_pfad)
        if wert is None:
            return {"erkannt": True, "wert": None,
                    "grund": "Die Aufnahme war nicht auswertbar - ich höre trotzdem zu."}
        erkannt = wert >= float(STIMM_SCHWELLE)
        return {"erkannt": erkannt, "wert": round(wert, 3),
                "grund": ("Stimme passt (%.2f)" % wert) if erkannt
                         else ("Fremde Stimme (%.2f unter Schwelle %.2f)"
                               % (wert, STIMM_SCHWELLE))}


# =========================================================================
# mail  -  E-Mail - ungelesene Nachrichten holen, vorsortieren, antworten und Entwürfe ablegen.
# 
# Die Vorsortierung hier ist grob und arbeitet nur mit Wortlisten. Das ist
# Absicht: Sie läuft ohne Netz und ohne Kosten und schafft die Vorauswahl. Die
# feine Bewertung übernimmt Claude im Briefing, wo er den Zusammenhang kennt.
# 
# Jede Mail in den Listen trägt ``kennung`` (die Message-ID) und ``uid``. Mit der
# Kennung antwortet Jarvis im selben Faden (:meth:`Mail.antworten`) oder legt einen
# Entwurf an (:meth:`Mail.entwurf_ablegen`). Was Claude liefert (Empfänger,
# Betreff, Kennung), landet nie ungeprüft in einer Kopfzeile: Zeilenumbrüche
# würden dort weitere Kopfzeilen einschleusen (Bcc, Empfänger), also werden sie
# abgelehnt. Was aus fremden Mails kommt, wird einzeilig gemacht.
# 
# Für Tests nimmt :class:`Mail` die Netzklassen als Argumente: ``imap_klasse``
# (wie ``imaplib.IMAP4_SSL``, Aufruf ``klasse(host, port, ssl_context=...)``),
# ``smtp_klasse`` (wie ``smtplib.SMTP``) und ``smtp_ssl_klasse`` (wie
# ``smtplib.SMTP_SSL``). Ohne Angabe werden ``imaplib``/``smtplib`` erst beim
# Aufruf nachgeschlagen - Tests dürfen das Modul also auch austauschen.
# =========================================================================

#!/usr/bin/env python3
# -*- coding: utf-8 -*-



IMAP_MONATE = ("Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec")

# Grobe Wortlisten für die Vorsortierung.
WICHTIG_WOERTER = ["dringend", "frist", "mahnung", "rechnung", "angebot", "auftrag",
                   "kündigung", "kuendigung", "vertrag", "termin", "zahlung",
                   "überfällig", "ueberfaellig", "reklamation", "beschwerde",
                   "anfrage", "auftragsbestätigung", "letzte erinnerung"]
RAUSCHEN_WOERTER = ["newsletter", "unsubscribe", "abmelden", "no-reply", "noreply",
                    "werbung", "rabatt", "gewinnspiel", "webinar", "sale",
                    "black friday", "prospekt", "marketing", "digest"]


def kopf_dekodieren(roh) -> str:
    """Macht aus einem kodierten Mail-Kopf lesbaren Text."""
    if not roh:
        return ""
    try:
        teile = email.header.decode_header(roh)
    except (ValueError, TypeError):
        return str(roh)
    ergebnis = []
    for inhalt, kodierung in teile:
        if isinstance(inhalt, bytes):
            try:
                ergebnis.append(inhalt.decode(kodierung or "utf-8", errors="replace"))
            except (LookupError, UnicodeDecodeError):
                ergebnis.append(inhalt.decode("utf-8", errors="replace"))
        else:
            ergebnis.append(str(inhalt))
    return "".join(ergebnis).strip()


def klartext_aus_mail(nachricht) -> str:
    """Holt den lesbaren Text aus einer Mail, notfalls aus dem HTML-Teil."""
    if nachricht.is_multipart():
        for teil in nachricht.walk():
            if teil.get_content_type() == "text/plain" and \
                    "attachment" not in str(teil.get("Content-Disposition", "")):
                try:
                    return teil.get_payload(decode=True).decode(
                        teil.get_content_charset() or "utf-8", errors="replace")
                except (AttributeError, LookupError, UnicodeDecodeError):
                    continue
        for teil in nachricht.walk():
            if teil.get_content_type() == "text/html":
                try:
                    roh = teil.get_payload(decode=True).decode(
                        teil.get_content_charset() or "utf-8", errors="replace")
                except (AttributeError, LookupError, UnicodeDecodeError):
                    continue
                import re as _re_html
                return _re_html.sub(r"<[^>]+>", " ", roh)
    else:
        try:
            return nachricht.get_payload(decode=True).decode(
                nachricht.get_content_charset() or "utf-8", errors="replace")
        except (AttributeError, LookupError, UnicodeDecodeError):
            return str(nachricht.get_payload())
    return ""


def triage(betreff: str, absender: str, text: str) -> str:
    """Sortiert eine Mail grob in wichtig, spaeter oder rauschen ein."""
    zusammen = ("%s %s %s" % (betreff or "", absender or "", (text or "")[:800])).lower()
    for wort in RAUSCHEN_WOERTER:
        if wort in zusammen:
            return "rauschen"
    for wort in WICHTIG_WOERTER:
        if wort in zusammen:
            return "wichtig"
    return "spaeter"


# -- Antworten und Entwürfe: Helfer -----------------------------------------

# Wie viele Zeilen der Original-Mail eine Antwort zitiert.
ZITAT_ZEILEN = 20
ZITAT_ZEICHEN = 4000
# Mehr Empfänger als das schickt Jarvis nie in einer Mail.
MAX_EMPFAENGER = 20
# Ältere Bezüge einer Kette werden gekürzt, damit die Kopfzeile nicht ausufert.
MAX_BEZUEGE = 20

# Der Entwürfe-Ordner heißt je nach Anbieter und Sprache anders. Zuerst gilt das
# \Drafts-Merkmal aus LIST, danach diese Namen in dieser Reihenfolge.
ENTWURF_ORDNER_RUECKFALL = ("Drafts", "Entwürfe", "[Gmail]/Entwürfe")
ENTWURF_ORDNER_WEITERE = ("[Gmail]/Drafts", "INBOX.Drafts", "INBOX.Entwürfe", "Entwurf",
                          "Entwürfe und Notizen", "Draft")

_KENNUNG_MUSTER = re.compile(r"<[^<>\s]+>")
_UID_MUSTER = re.compile(rb"\bUID\s+(\d+)", re.IGNORECASE)
_ANTWORT_VORSATZ = re.compile(r"^\s*(re|aw|antw|sv)(\[\d+\])?\s*:", re.IGNORECASE)
_ADRESSE_MUSTER = re.compile(r"^[^@\s<>(),;:\\\"\[\]]+@[^@\s<>(),;:\\\"\[\]]+$")
_LIST_ZEILE = re.compile(r'^\((?P<flags>[^)]*)\)\s+(?P<trenner>"(?:[^"\\]|\\.)*"|NIL)\s+(?P<name>.+)$',
                         re.DOTALL)


def hat_zeilenumbruch(wert) -> bool:
    """Steckt in dem Wert ein Zeilenumbruch (oder Verwandtes) - Angriffsfläche für Kopfzeilen?"""
    text = str(wert if wert is not None else "")
    return any(zeichen in text for zeichen in "\r\n\x00") or len(text.splitlines()) > 1


def _umbruch_fehler(*paare) -> str:
    """Deutscher Fehlertext für das erste Feld mit Zeilenumbruch, sonst ''."""
    for bezeichnung, wert in paare:
        if hat_zeilenumbruch(wert):
            return "%s darf keinen Zeilenumbruch enthalten." % bezeichnung
    return ""


def _einzeilig(wert) -> str:
    """Macht Fremdtext zu einer Zeile - Umbrüche und Steuerzeichen werden zu Leerzeichen."""
    return " ".join(str(wert if wert is not None else "").replace("\x00", "").split())


def kennung_normalisieren(kennung) -> str:
    """Bringt eine Message-ID in die Form ``<id@host>`` - leer, wenn keine zu erkennen ist."""
    text = _einzeilig(kennung)
    if not text:
        return ""
    treffer = _KENNUNG_MUSTER.search(text)
    if treffer:
        return treffer.group(0)[:998]
    if " " in text or "<" in text or ">" in text:
        return ""
    return ("<%s>" % text)[:998]


def kennung_aus_nachricht(nachricht) -> str:
    """Die Message-ID einer eingelesenen Mail, normalisiert - oder ''."""
    return kennung_normalisieren(nachricht.get("Message-ID"))


def _adressen_aus_kopf(wert) -> list:
    """Liest (Name, Adresse)-Paare aus einer Kopfzeile; der Name ist dekodiert."""
    if not wert:
        return []
    ergebnis = []
    for name, adresse in email.utils.getaddresses([_einzeilig(wert)]):
        adresse = adresse.strip()
        if adresse and "@" in adresse:
            ergebnis.append((_einzeilig(kopf_dekodieren(name)), adresse))
    return ergebnis


def _adresse_anzeigen(name: str, adresse: str) -> str:
    """Lesbar, nicht kodiert: ``Anna Weber <anna@weber.at>``."""
    return "%s <%s>" % (name, adresse) if name else adresse


def empfaenger_pruefen(an) -> tuple:
    """Prüft eine Empfängerangabe. Gibt ``(paare, fehler)`` zurück: Paare aus (Name, Adresse).

    Jede Adresse muss genau so in der Angabe stehen, wie sie versendet wird - sonst
    könnte die Freigabe einen anderen Empfänger nennen, als hinterher wirklich eine
    Mail bekommt.
    """
    text = str(an if an is not None else "").strip()
    fehler = "'%s' ist keine gültige Mailadresse." % text[:120]
    if not text or hat_zeilenumbruch(text):
        return [], (fehler if text else "Ich brauche eine Empfängeradresse.")
    paare = []
    for name, adresse in email.utils.getaddresses([text]):
        adresse = adresse.strip()
        if not name.strip() and not adresse:
            continue  # ein überzähliges Komma
        if not _ADRESSE_MUSTER.match(adresse) or adresse.lower() not in text.lower():
            return [], fehler
        paare.append((_einzeilig(kopf_dekodieren(name)), adresse))
    if not paare:
        return [], fehler
    if len(paare) > MAX_EMPFAENGER:
        return [], "Das sind zu viele Empfänger (mehr als %d in einer Mail)." % MAX_EMPFAENGER
    return paare, ""


def _adressliste(paare) -> list:
    """Macht aus (Name, Adresse)-Paaren Adress-Objekte, die der Kopf sauber quotet und kodiert."""
    return [Address(display_name=name, addr_spec=adresse) for name, adresse in paare]


def _eigene_adressen() -> set:
    """Die Adressen des eigenen Postfachs (kleingeschrieben)."""
    eigene = set()
    for wert in (SMTP_ABSENDER, SMTP_USER,
                 IMAP_USER):
        for _name, adresse in email.utils.getaddresses([str(wert or "")]):
            if "@" in adresse:
                eigene.add(adresse.strip().lower())
    return eigene


def _absender_adresse(auch_imap: bool = False) -> str:
    """Absender für ausgehende Mails: SMTP_ABSENDER, sonst SMTP_USER (bei Entwürfen auch IMAP_USER)."""
    erste = SMTP_ABSENDER or SMTP_USER
    if erste:
        return str(erste)
    return str(IMAP_USER or "") if auch_imap else ""


def _nachricht_id(absender: str = "") -> str:
    """Eine neue Message-ID. Die Domain stammt vom Absender, nicht vom Rechnernamen des Macs."""
    domain = None
    for _name, adresse in email.utils.getaddresses([str(absender or "")]):
        if "@" in adresse:
            domain = adresse.rsplit("@", 1)[1].strip() or None
            break
    return email.utils.make_msgid(domain=domain)


def _kopf_wert(kopf: dict, *namen) -> str:
    """Liest ein Feld aus dem Kopf-Dict - Groß-/Kleinschreibung und ``-``/``_`` sind egal."""
    if not isinstance(kopf, dict):
        return ""
    glatt = {}
    for schluessel, wert in kopf.items():
        glatt[str(schluessel).strip().lower().replace("-", "_").replace(" ", "_")] = wert
    for name in namen:
        wert = glatt.get(name)
        if wert not in (None, "", [], ()):
            if isinstance(wert, (list, tuple)):
                wert = " ".join(str(w) for w in wert)
            return str(wert)
    return ""


def antwort_betreff(original) -> str:
    """``Re: <Betreff>`` - ohne ein zweites ``Re:`` (auch ``AW:`` und ``Antw:`` zählen mit)."""
    betreff = _einzeilig(original)
    if not betreff:
        return "Re: (ohne Betreff)"
    if _ANTWORT_VORSATZ.match(betreff):
        return betreff
    return "Re: " + betreff


def zitat_bauen(original_text, datum: str = "", absender: str = "") -> str:
    """Zitiert die ersten Zeilen der Original-Mail mit ``> ``, mit einer Kopfzeile davor."""
    zeilen = str(original_text or "").replace("\r\n", "\n").replace("\r", "\n").split("\n")
    while zeilen and not zeilen[-1].strip():
        zeilen.pop()
    while zeilen and not zeilen[0].strip():
        zeilen.pop(0)
    zeilen = zeilen[:ZITAT_ZEILEN]
    if not zeilen:
        return ""
    gezeigt = []
    for zeile in zeilen:
        zeile = zeile.replace("\x00", "").rstrip()[:1000]
        gezeigt.append("> " + zeile if zeile else ">")
    wer = _einzeilig(absender)
    wann = _einzeilig(datum)
    if wann and wer:
        vorspann = "Am %s schrieb %s:" % (wann, wer)
    elif wer:
        vorspann = "%s schrieb:" % wer
    else:
        vorspann = "Die ursprüngliche Nachricht:"
    return (vorspann + "\n" + "\n".join(gezeigt))[:ZITAT_ZEICHEN]


def bezuege_bauen(alte_bezuege, kennung: str) -> str:
    """Die References-Kette: alte Bezüge plus die Kennung der Mail, auf die geantwortet wird."""
    alte = _einzeilig(alte_bezuege)
    ids = _KENNUNG_MUSTER.findall(alte)
    if not ids and alte:
        ids = [alte]
    if kennung and (not ids or ids[-1] != kennung):
        ids.append(kennung)
    if len(ids) > MAX_BEZUEGE:
        ids = ids[:1] + ids[-(MAX_BEZUEGE - 1):]
    return " ".join(ids)


def antwort_bauen(kopf: dict, text, absender: str = "") -> EmailMessage:
    """Baut die Antwort auf eine Mail im selben Faden.

    ``kopf`` beschreibt die Original-Mail. Gelesen werden (Alternativen in Klammern):
    ``betreff``, ``kennung`` (message_id), ``references`` (referenzen),
    ``antwort_an`` (reply_to, absender, von, an) für den Empfänger, ``datum``,
    ``absender`` für die Zitatzeile und ``text`` (original, auszug) für das Zitat.

    * Betreff ``Re: <Original>`` - ohne zweites ``Re:``,
    * ``In-Reply-To`` = Kennung, ``References`` = alte Bezüge + Kennung,
    * unter dem Antworttext die ersten 20 Zeilen der Original-Mail mit ``> ``.

    Was aus ``kopf`` kommt, gilt als Fremdtext und wird einzeilig gemacht. Der Antworttext
    selbst steht nur im Rumpf. Eine nicht lesbare Empfängerangabe bleibt einfach leer
    (kein ``To``) - geprüft wird sie vor dem Versenden.
    """
    kennung = kennung_normalisieren(_kopf_wert(kopf, "kennung", "message_id", "messageid"))
    betreff = antwort_betreff(_kopf_wert(kopf, "betreff", "subject"))
    ziel = _kopf_wert(kopf, "antwort_an", "reply_to", "absender", "von", "from", "an")
    anzeige_absender = _kopf_wert(kopf, "absender", "von", "from") or ziel
    von = str(absender or "") or _absender_adresse()

    nachricht = EmailMessage()
    if von:
        try:
            nachricht["From"] = von
        except ValueError:
            pass
    paare = [(n, a) for n, a in _adressen_aus_kopf(ziel) if _ADRESSE_MUSTER.match(a)]
    if paare:
        nachricht["To"] = _adressliste(paare[:MAX_EMPFAENGER])
    nachricht["Subject"] = betreff
    nachricht["Date"] = email.utils.formatdate(localtime=True)
    nachricht["Message-ID"] = _nachricht_id(von)
    if kennung:
        nachricht["In-Reply-To"] = kennung
        nachricht["References"] = bezuege_bauen(_kopf_wert(kopf, "references", "referenzen"),
                                                kennung)
    zitat = zitat_bauen(_kopf_wert(kopf, "text", "original", "klartext", "auszug", "body"),
                        _kopf_wert(kopf, "datum", "date"), anzeige_absender)
    rumpf = str(text if text is not None else "").rstrip()
    nachricht.set_content(rumpf + ("\n\n" + zitat if zitat else "") + "\n")
    return nachricht


# -- IMAP-Ordnernamen (modifiziertes UTF-7, RFC 3501) -------------------------

def imap_utf7_kodieren(name: str) -> str:
    """``Entwürfe`` -> ``Entw&APw-rfe`` - so nennen IMAP-Server Ordner mit Umlauten."""
    ergebnis, puffer = [], ""

    def leeren():
        if puffer:
            roh = base64.b64encode(puffer.encode("utf-16-be")).decode("ascii")
            ergebnis.append("&" + roh.rstrip("=").replace("/", ",") + "-")

    for zeichen in str(name):
        if 0x20 <= ord(zeichen) <= 0x7e:
            leeren()
            puffer = ""
            ergebnis.append("&-" if zeichen == "&" else zeichen)
        else:
            puffer += zeichen
    leeren()
    return "".join(ergebnis)


def imap_utf7_dekodieren(name: str) -> str:
    """Umkehrung von :func:`imap_utf7_kodieren`; was sich nicht lesen lässt, bleibt stehen."""
    def ersetzen(treffer):
        innen = treffer.group(1)
        if not innen:
            return "&"
        try:
            roh = innen.replace(",", "/")
            roh += "=" * (-len(roh) % 4)
            return base64.b64decode(roh).decode("utf-16-be")
        except (ValueError, UnicodeDecodeError):
            return treffer.group(0)

    return re.sub(r"&([^-]*)-", ersetzen, str(name))


def _imap_name_quoten(roh: str) -> str:
    """Ein Ordnername als IMAP-Anführungstext (APPEND und SELECT nehmen ihn nicht von allein)."""
    return '"%s"' % str(roh).replace("\\", "\\\\").replace('"', '\\"')


def _ordner_aus_liste(daten) -> list:
    """Liest die Antwort auf LIST: Liste aus ``{'flags', 'roh', 'name'}`` (roh = Name wie vom Server)."""
    eintraege = []
    teile = list(daten or [])
    index = 0
    while index < len(teile):
        stueck = teile[index]
        index += 1
        if isinstance(stueck, tuple):
            # Ein Name als Literal: Kopf in [0], Name in [1].
            zeile = (stueck[0] if isinstance(stueck[0], (bytes, bytearray)) else b"")
            kopf = bytes(zeile).decode("utf-8", errors="replace")
            kopf = re.sub(r"\{\d+\}$", "", kopf).rstrip()
            name = bytes(stueck[1]).decode("utf-8", errors="replace") \
                if isinstance(stueck[1], (bytes, bytearray)) else str(stueck[1])
            zeile_text = kopf + ' "' + name.replace("\\", "\\\\").replace('"', '\\"') + '"'
        elif isinstance(stueck, (bytes, bytearray)):
            zeile_text = bytes(stueck).decode("utf-8", errors="replace")
        elif isinstance(stueck, str):
            zeile_text = stueck
        else:
            continue
        treffer = _LIST_ZEILE.match(zeile_text.strip())
        if not treffer:
            continue
        roh = treffer.group("name").strip()
        if len(roh) >= 2 and roh[0] == '"' and roh[-1] == '"':
            roh = re.sub(r"\\(.)", r"\1", roh[1:-1])
        flags = {f.lower() for f in treffer.group("flags").split()}
        eintraege.append({"flags": flags, "roh": roh, "name": imap_utf7_dekodieren(roh)})
    return eintraege


def entwurf_ordner_kandidaten(daten) -> list:
    """Die Namen (so wie der Server sie kennt), in die ein Entwurf passen könnte - beste zuerst.

    1. Ordner mit dem Merkmal ``\\Drafts`` (der Server sagt selbst, welcher es ist),
    2. Ordner aus LIST, deren Name zu den bekannten passt,
    3. die bekannten Namen blind, falls LIST nichts Brauchbares geliefert hat.
    """
    eintraege = _ordner_aus_liste(daten)
    kandidaten = []

    def vormerken(roh):
        if roh and roh not in kandidaten:
            kandidaten.append(roh)

    for eintrag in eintraege:
        if "\\drafts" in eintrag["flags"] and "\\noselect" not in eintrag["flags"]:
            vormerken(eintrag["roh"])
    bekannt = [n.lower() for n in ENTWURF_ORDNER_RUECKFALL + ENTWURF_ORDNER_WEITERE]
    for gesucht in bekannt:
        for eintrag in eintraege:
            if eintrag["name"].lower() == gesucht and "\\noselect" not in eintrag["flags"]:
                vormerken(eintrag["roh"])
    for name in ENTWURF_ORDNER_RUECKFALL:
        vormerken(imap_utf7_kodieren(name))
    return kandidaten


class Mail:
    """Liest über IMAP und versendet über SMTP.

    Die Netzklassen sind einspeisbar (siehe Modul-Docstring); ohne Angabe nimmt die Klasse
    ``imaplib.IMAP4_SSL``, ``smtplib.SMTP`` und ``smtplib.SMTP_SSL``.
    """

    def __init__(self, imap_klasse=None, smtp_klasse=None, smtp_ssl_klasse=None):
        self.letzter_fehler = ""
        self.imap_klasse = imap_klasse
        self.smtp_klasse = smtp_klasse
        self.smtp_ssl_klasse = smtp_ssl_klasse

    # -- Verfügbarkeit ------------------------------------------------------

    def lesen_moeglich(self) -> bool:
        """Ist der Posteingang eingerichtet?"""
        return bool(IMAP_HOST and IMAP_USER and IMAP_PASSWORT)

    def senden_moeglich(self) -> bool:
        """Ist der Versand eingerichtet?"""
        return bool(SMTP_HOST and SMTP_USER and SMTP_PASSWORT)

    def zustand(self) -> dict:
        """Kurzer Überblick für den Selbsttest."""
        return {"lesen": self.lesen_moeglich(), "senden": self.senden_moeglich(),
                "imap": IMAP_HOST or "nicht gesetzt",
                "smtp": SMTP_HOST or "nicht gesetzt"}

    # -- Lesen --------------------------------------------------------------

    def _verbinden(self, auswaehlen: bool = True):
        """Meldet sich im Postfach an und öffnet - wenn gewünscht - INBOX nur lesend."""
        klasse = self.imap_klasse or imaplib.IMAP4_SSL
        verbindung = klasse(IMAP_HOST, IMAP_PORT,
                            ssl_context=ssl.create_default_context())
        try:
            verbindung.login(IMAP_USER, IMAP_PASSWORT)
            if auswaehlen:
                verbindung.select("INBOX", readonly=True)
        except BaseException:
            self._trennen(verbindung)
            raise
        return verbindung

    @staticmethod
    def _trennen(verbindung):
        if verbindung is None:
            return
        try:
            verbindung.close()
        except (imaplib.IMAP4.error, OSError):
            pass
        try:
            verbindung.logout()
        except (imaplib.IMAP4.error, OSError):
            pass

    @staticmethod
    def _fetch_auswerten(teil) -> tuple:
        """Zerlegt die Antwort auf FETCH: ``(rohe Mail als bytes oder None, uid als Text)``.

        Die UID steht je nach Server vor oder nach dem Rumpf; gesucht wird nur in den
        Kopfstücken der Antwort, nie in der Mail selbst.
        """
        roh, uid = None, ""
        for stueck in teil or []:
            if isinstance(stueck, tuple) and len(stueck) >= 2:
                if roh is None and isinstance(stueck[1], (bytes, bytearray)):
                    roh = bytes(stueck[1])
                kopfstueck = stueck[0]
            else:
                kopfstueck = stueck
            if not uid and isinstance(kopfstueck, (bytes, bytearray)):
                treffer = _UID_MUSTER.search(bytes(kopfstueck))
                if treffer:
                    uid = treffer.group(1).decode("ascii")
        return roh, uid

    @staticmethod
    def _holen(verbindung, nummern) -> list:
        """Holt Mails, neueste zuerst - ohne sie als gelesen zu markieren."""
        mails = []
        for nummer in reversed(nummern):
            # BODY.PEEK lässt die Mail ungelesen - er soll sie selbst noch sehen.
            status, teil = verbindung.fetch(nummer, "(UID BODY.PEEK[])")
            if status != "OK" or not teil or not teil[0]:
                continue
            roh, uid = Mail._fetch_auswerten(teil)
            if roh is None:
                continue
            nachricht = email.message_from_bytes(roh)
            betreff = kopf_dekodieren(nachricht.get("Subject"))
            absender = kopf_dekodieren(nachricht.get("From"))
            text = klartext_aus_mail(nachricht)
            mails.append({
                "id": nummer.decode("ascii", errors="replace"),
                # Die Kennung (Message-ID) trägt eine Mail über Sitzungen hinweg; mit ihr
                # antwortet Jarvis im Faden. Die UID gilt nur im Ordner (und dessen UIDVALIDITY).
                "kennung": kennung_aus_nachricht(nachricht),
                "uid": uid,
                "betreff": betreff or "(ohne Betreff)",
                "absender": absender,
                "datum": kopf_dekodieren(nachricht.get("Date")),
                "auszug": " ".join((text or "").split())[:400],
                "einstufung": triage(betreff, absender, text),
            })
        return mails

    def ungelesene(self, limit: int = 15) -> dict:
        """Holt ungelesene Mails und sortiert sie vor - ohne sie als gelesen zu markieren."""
        if not self.lesen_moeglich():
            return {"ok": False,
                    "fehler": "Der Posteingang ist nicht eingerichtet. Richte ihn ein mit: "
                              "python3 jarvis.py zugang mail"}
        verbindung = None
        try:
            verbindung = self._verbinden()
            status, daten = verbindung.search(None, "UNSEEN")
            if status != "OK":
                return {"ok": False, "fehler": "Der Posteingang antwortet nicht wie erwartet."}
            nummern = daten[0].split()[-limit:] if daten and daten[0] else []
            mails = self._holen(verbindung, nummern)
            return {"ok": True, "anzahl": len(mails), "mails": mails,
                    "wichtig": [m for m in mails if m["einstufung"] == "wichtig"],
                    "spaeter": [m for m in mails if m["einstufung"] == "spaeter"],
                    "rauschen": [m for m in mails if m["einstufung"] == "rauschen"]}
        except (imaplib.IMAP4.error, ssl.SSLError, OSError) as fehler:
            self.letzter_fehler = str(fehler)
            return {"ok": False,
                    "fehler": "Der Posteingang ist nicht erreichbar: %s" % fehler}
        finally:
            self._trennen(verbindung)

    def suchen(self, begriff: str, tage: int = 180, limit: int = 10) -> dict:
        """Sucht im Posteingang nach Absender, Betreff oder Text - auch in gelesenen Mails."""
        if not self.lesen_moeglich():
            return {"ok": False,
                    "fehler": "Der Posteingang ist nicht eingerichtet. Richte ihn ein mit: "
                              "python3 jarvis.py zugang mail"}
        begriff = " ".join(str(begriff or "").split())[:100]
        if len(begriff) < 2:
            return {"ok": False, "fehler": "Wonach soll ich suchen?"}
        tage = max(1, min(int(tage or 180), 3650))
        limit = max(1, min(int(limit or 10), 25))
        # IMAP will englische Monatsnamen, unabhängig von der Spracheinstellung des Macs.
        tag = datetime.now() - timedelta(days=tage)
        seit = "%d-%s-%d" % (tag.day, IMAP_MONATE[tag.month - 1], tag.year)
        verbindung = None
        try:
            verbindung = self._verbinden()
            if begriff.isascii():
                # Anführungszeichen und Rückstriche würden die Suchanfrage aufbrechen.
                sauber = begriff.replace("\\", " ").replace('"', " ")
                status, daten = verbindung.search(None, "SINCE", seit, "TEXT", '"%s"' % sauber)
            else:
                # Umlaute gehen nur als Literal mit Zeichensatz.
                verbindung.literal = begriff.encode("utf-8")
                status, daten = verbindung.search("UTF-8", "SINCE", seit, "TEXT")
            if status != "OK":
                return {"ok": False, "fehler": "Die Suche im Posteingang hat nicht geklappt."}
            nummern = daten[0].split()[-limit:] if daten and daten[0] else []
            mails = self._holen(verbindung, nummern)
            return {"ok": True, "anzahl": len(mails), "begriff": begriff, "tage": tage,
                    "mails": mails}
        except (imaplib.IMAP4.error, ssl.SSLError, OSError) as fehler:
            self.letzter_fehler = str(fehler)
            return {"ok": False,
                    "fehler": "Der Posteingang ist nicht erreichbar: %s" % fehler}
        finally:
            self._trennen(verbindung)

    def zusammenfassung(self, limit: int = 15) -> str:
        """Ein gesprochener Satz über den Posteingang."""
        ergebnis = self.ungelesene(limit)
        if not ergebnis.get("ok"):
            return ergebnis.get("fehler", "Der Posteingang ist nicht erreichbar.")
        if ergebnis["anzahl"] == 0:
            return "Im Posteingang ist nichts Ungelesenes."
        teile = ["%d ungelesene Mails, davon %d wichtig."
                 % (ergebnis["anzahl"], len(ergebnis["wichtig"]))]
        for mail in ergebnis["wichtig"][:4]:
            teile.append("Von %s: %s." % (mail["absender"].split("<")[0].strip(),
                                          mail["betreff"]))
        return " ".join(teile)

    # -- Original-Mail zu einer Kennung ---------------------------------------

    def _original_aus(self, verbindung, kennung: str) -> tuple:
        """Sucht die Mail mit dieser Message-ID im geöffneten Ordner: ``(kopf, fehler)``.

        ``kopf`` ist das Dict für :func:`antwort_bauen` (siehe dort). Gefunden wird per
        ``SEARCH HEADER Message-ID``; weil das eine Teilstring-Suche ist, wird die Kennung
        der gefundenen Mail noch einmal verglichen.
        """
        if kennung.isascii():
            sauber = kennung.replace("\\", "\\\\").replace('"', '\\"')
            status, daten = verbindung.search(None, "HEADER", "Message-ID", '"%s"' % sauber)
        else:
            verbindung.literal = kennung.encode("utf-8")
            status, daten = verbindung.search("UTF-8", "HEADER", "Message-ID")
        if status != "OK":
            return None, "Die Suche nach der Mail im Posteingang hat nicht geklappt."
        nummern = daten[0].split() if daten and daten[0] else []
        for nummer in reversed(nummern[-5:]):
            status, teil = verbindung.fetch(nummer, "(UID BODY.PEEK[])")
            if status != "OK" or not teil or not teil[0]:
                continue
            roh, uid = self._fetch_auswerten(teil)
            if roh is None:
                continue
            nachricht = email.message_from_bytes(roh)
            gefunden = kennung_aus_nachricht(nachricht)
            if gefunden and gefunden.lower() != kennung.lower():
                continue  # nur ein Teilstring-Treffer, nicht diese Mail
            return self._kopf_aus_nachricht(nachricht, kennung, uid), ""
        return None, ("Diese Mail finde ich im Posteingang nicht (mehr). Lies die Mails noch "
                      "einmal, dann nehme ich die Kennung von dort.")

    @staticmethod
    def _kopf_aus_nachricht(nachricht, kennung: str, uid: str = "") -> dict:
        """Das Kopf-Dict einer eingelesenen Original-Mail (alles einzeilig, Adressen geprüft)."""
        absender_paare = _adressen_aus_kopf(nachricht.get("From"))
        antwort_paare = _adressen_aus_kopf(nachricht.get("Reply-To")) or absender_paare
        empfaenger_paare = _adressen_aus_kopf(nachricht.get("To"))
        eigene = _eigene_adressen()
        if antwort_paare and antwort_paare[0][1].lower() in eigene:
            # Die Mail stammt von uns selbst - dann geht die Antwort an den, dem sie galt.
            fremde = [p for p in empfaenger_paare if p[1].lower() not in eigene]
            if fremde:
                antwort_paare = fremde
        absender = ", ".join(_adresse_anzeigen(n, a) for n, a in absender_paare) \
            or _einzeilig(kopf_dekodieren(nachricht.get("From")))
        antwort_an = ", ".join(_adresse_anzeigen(n, a) for n, a in antwort_paare[:1])
        referenzen = nachricht.get("References") or nachricht.get("In-Reply-To") or ""
        return {
            "kennung": kennung,
            "uid": uid,
            "betreff": _einzeilig(kopf_dekodieren(nachricht.get("Subject"))) or "(ohne Betreff)",
            "absender": absender,
            "empfaenger": ", ".join(_adresse_anzeigen(n, a) for n, a in empfaenger_paare)
            or _einzeilig(kopf_dekodieren(nachricht.get("To"))),
            "antwort_an": antwort_an,
            "references": _einzeilig(referenzen),
            "datum": _einzeilig(kopf_dekodieren(nachricht.get("Date"))),
            "text": klartext_aus_mail(nachricht) or "",
        }

    def _original_holen(self, kennung) -> tuple:
        """Öffnet das Postfach und holt die Original-Mail: ``(kopf, fehler)``."""
        kennung = kennung_normalisieren(kennung)
        if not kennung:
            return None, ("Ich brauche die Kennung (Message-ID) der Mail - sie steht in den "
                          "Ergebnissen von mails_lesen und mails_suchen.")
        verbindung = None
        try:
            verbindung = self._verbinden()
            return self._original_aus(verbindung, kennung)
        except (imaplib.IMAP4.error, ssl.SSLError, OSError) as fehler:
            self.letzter_fehler = str(fehler)
            return None, "Der Posteingang ist nicht erreichbar: %s" % fehler
        finally:
            self._trennen(verbindung)

    def kopf_zu_kennung(self, kennung) -> dict:
        """Wer schrieb, an wen, welcher Betreff - für die Freigabe, die nie nur eine Kennung zeigen darf.

        Gibt bei Erfolg ``{"ok": True, "kennung", "absender", "empfaenger", "antwort_an",
        "betreff", "antwort_betreff", "datum", "hinweis"}`` zurück:

        * ``absender`` - von wem die Original-Mail kam (``Name <adresse>``),
        * ``empfaenger`` - an wen sie ging (also meist an das eigene Postfach),
        * ``antwort_an`` - wohin die Antwort wirklich geht (Reply-To, sonst Absender),
        * ``betreff`` - Betreff der Original-Mail, ``antwort_betreff`` - der mit ``Re:``,
        * ``hinweis`` - leer, oder eine Warnung (Antwortadresse weicht vom Absender ab, noreply).

        Sonst ``{"ok": False, "fehler": <deutscher Text>}``. Das Postfach wird nur gelesen.
        """
        fehler = _umbruch_fehler(("Die Kennung", kennung))
        if fehler:
            return {"ok": False, "fehler": fehler}
        if not self.lesen_moeglich():
            return {"ok": False,
                    "fehler": "Die Original-Mail lässt sich nicht nachschlagen: Der Posteingang "
                              "ist nicht eingerichtet. Richte ihn ein mit: "
                              "python3 jarvis.py zugang mail"}
        kopf, fehler = self._original_holen(kennung)
        if fehler:
            return {"ok": False, "fehler": fehler}
        hinweise = []
        absender_adr = {a.lower() for _n, a in _adressen_aus_kopf(kopf["absender"])}
        antwort_adr = [a for _n, a in _adressen_aus_kopf(kopf["antwort_an"])]
        if antwort_adr and absender_adr and antwort_adr[0].lower() not in absender_adr:
            hinweise.append("Die Antwort geht an %s und nicht an den Absender." % antwort_adr[0])
        if antwort_adr and re.search(r"no[-_.]?reply|do[-_.]?not[-_.]?reply", antwort_adr[0], re.I):
            hinweise.append("Diese Adresse nimmt vermutlich keine Antworten an.")
        return {"ok": True, "kennung": kopf["kennung"], "absender": kopf["absender"],
                "empfaenger": kopf["empfaenger"], "antwort_an": kopf["antwort_an"],
                "betreff": kopf["betreff"], "antwort_betreff": antwort_betreff(kopf["betreff"]),
                "datum": kopf["datum"], "hinweis": " ".join(hinweise)}

    # -- Senden -------------------------------------------------------------

    @staticmethod
    def antwort_bauen(kopf: dict, text, absender: str = "") -> EmailMessage:
        """Siehe :func:`antwort_bauen` (gleiche Funktion, hier auch als Methode erreichbar)."""
        return antwort_bauen(kopf, text, absender)

    def _smtp_senden(self, nachricht) -> dict:
        """Schickt eine fertige Nachricht über SMTP: ``{"ok": True}`` oder ``{"ok": False, "fehler"}``."""
        server = None
        try:
            kontext = ssl.create_default_context()
            if int(SMTP_PORT) == 465:
                klasse = self.smtp_ssl_klasse or smtplib.SMTP_SSL
                server = klasse(SMTP_HOST, SMTP_PORT, context=kontext, timeout=30)
            else:
                klasse = self.smtp_klasse or smtplib.SMTP
                server = klasse(SMTP_HOST, SMTP_PORT, timeout=30)
                server.starttls(context=kontext)
            server.login(SMTP_USER, SMTP_PASSWORT)
            abgelehnt = server.send_message(nachricht)
        except smtplib.SMTPAuthenticationError:
            return {"ok": False,
                    "fehler": "Der Mailserver lehnt Benutzer oder Passwort ab. Bei Gmail "
                              "und ähnlichen Anbietern braucht es ein App-Passwort."}
        except (smtplib.SMTPException, ssl.SSLError, OSError, ValueError) as fehler:
            return {"ok": False, "fehler": "Die Mail ging nicht raus: %s" % fehler}
        finally:
            self._smtp_schliessen(server)
        if isinstance(abgelehnt, dict) and abgelehnt:
            return {"ok": True, "abgelehnt": sorted(str(a) for a in abgelehnt),
                    "hinweis": "Der Mailserver hat diese Empfänger abgelehnt: %s."
                               % ", ".join(sorted(str(a) for a in abgelehnt))}
        return {"ok": True}

    @staticmethod
    def _smtp_schliessen(server):
        if server is None:
            return
        for name in ("quit", "close"):
            aufruf = getattr(server, name, None)
            if aufruf is None:
                continue
            try:
                aufruf()
                return
            except (smtplib.SMTPException, OSError):
                continue

    def senden(self, an: str, betreff: str, text: str) -> dict:
        """Verschickt eine Mail über SMTP mit STARTTLS.

        Achtung: Die Freigabe wird **nicht** hier eingeholt, sondern im
        Werkzeugkatalog, bevor diese Methode überhaupt aufgerufen wird.
        """
        fehler = _umbruch_fehler(("Der Empfänger", an), ("Der Betreff", betreff))
        if fehler:
            return {"ok": False, "fehler": fehler}
        if not self.senden_moeglich():
            return {"ok": False,
                    "fehler": "Der Mailversand ist nicht eingerichtet. In der Einrichtung "
                              "SMTP-Server, Benutzer und Passwort hinterlegen."}
        an = (an or "").strip()
        if "@" not in an:
            return {"ok": False, "fehler": "'%s' ist keine gültige Mailadresse." % an}
        paare, fehler = empfaenger_pruefen(an)
        if fehler:
            return {"ok": False, "fehler": fehler}

        von = SMTP_ABSENDER or SMTP_USER
        nachricht = EmailMessage()
        try:
            nachricht["From"] = von
            nachricht["To"] = _adressliste(paare)
            nachricht["Subject"] = betreff or "(ohne Betreff)"
            nachricht["Date"] = email.utils.formatdate(localtime=True)
            nachricht["Message-ID"] = _nachricht_id(von)
            nachricht.set_content(text or "")
        except ValueError as problem:
            return {"ok": False, "fehler": "Die Mail lässt sich so nicht bauen: %s" % problem}

        ergebnis = self._smtp_senden(nachricht)
        if not ergebnis.get("ok"):
            return ergebnis
        antwort = {"ok": True, "text": "Mail an %s ist raus." % an}
        if ergebnis.get("hinweis"):
            antwort["hinweis"] = ergebnis["hinweis"]
        return antwort

    def antworten(self, kennung, text) -> dict:
        """Antwortet auf eine gelesene Mail im selben Faden.

        Sucht die Mail per ``SEARCH HEADER Message-ID``, liest ihre Kopfzeilen und baut mit
        :func:`antwort_bauen` die Antwort (Betreff ``Re:``, ``In-Reply-To``, ``References``,
        Zitat), die dann über SMTP rausgeht. Die Freigabe holt der Werkzeugkatalog vorher
        ein - nicht diese Methode.
        """
        fehler = _umbruch_fehler(("Die Kennung", kennung))
        if fehler:
            return {"ok": False, "fehler": fehler}
        if not self.lesen_moeglich():
            return {"ok": False,
                    "fehler": "Zum Antworten muss ich die Original-Mail im Postfach finden - dafür "
                              "ist der Posteingang nicht eingerichtet. Richte ihn ein mit: "
                              "python3 jarvis.py zugang mail"}
        if not self.senden_moeglich():
            return {"ok": False,
                    "fehler": "Der Mailversand ist nicht eingerichtet. In der Einrichtung "
                              "SMTP-Server, Benutzer und Passwort hinterlegen."}
        kennung = kennung_normalisieren(kennung)
        if not kennung:
            return {"ok": False,
                    "fehler": "Ich brauche die Kennung (Message-ID) der Mail - sie steht in den "
                              "Ergebnissen von mails_lesen und mails_suchen."}
        rumpf = str(text if text is not None else "").strip()
        if not rumpf:
            return {"ok": False, "fehler": "Die Antwort hat keinen Text."}
        kopf, fehler = self._original_holen(kennung)
        if fehler:
            return {"ok": False, "fehler": fehler}
        paare, fehler = empfaenger_pruefen(kopf.get("antwort_an"))
        if fehler:
            return {"ok": False,
                    "fehler": "Auf diese Mail kann ich nicht antworten: Es ist keine "
                              "Antwortadresse zu erkennen."}
        try:
            nachricht = antwort_bauen(kopf, rumpf, SMTP_ABSENDER or SMTP_USER)
        except ValueError as problem:
            return {"ok": False, "fehler": "Die Antwort lässt sich so nicht bauen: %s" % problem}
        ergebnis = self._smtp_senden(nachricht)
        if not ergebnis.get("ok"):
            return ergebnis
        an = ", ".join(_adresse_anzeigen(n, a) for n, a in paare)
        antwort = {"ok": True, "an": an, "betreff": str(nachricht["Subject"]),
                   "text": "Antwort an %s ist raus." % an}
        if ergebnis.get("hinweis"):
            antwort["hinweis"] = ergebnis["hinweis"]
        return antwort

    # -- Entwürfe -----------------------------------------------------------

    def entwurf_ablegen(self, an, betreff, text, antwort_auf="") -> dict:
        """Legt eine Mail als Entwurf im Entwürfe-Ordner des Postfachs ab. Verschickt wird nichts.

        Der Ordner kommt aus LIST (Merkmal ``\\\\Drafts``), sonst aus bekannten Namen
        (``Drafts``, ``Entwürfe``, ``[Gmail]/Entwürfe`` ...). Mit ``antwort_auf`` (einer
        Message-ID) wird der Entwurf eine Antwort im Faden; leere Felder ``an`` und
        ``betreff`` kommen dann aus der Original-Mail. Ohne ``antwort_auf`` darf ``an`` leer
        bleiben - der Entwurf ist dann ohne Empfänger.
        """
        fehler = _umbruch_fehler(("Der Empfänger", an), ("Der Betreff", betreff),
                                 ("Die Kennung", antwort_auf))
        if fehler:
            return {"ok": False, "fehler": fehler}
        if not self.lesen_moeglich():
            return {"ok": False, "fehler": "Für Entwürfe im Postfach fehlt der IMAP-Zugang."}
        an = str(an if an is not None else "").strip()
        betreff = str(betreff if betreff is not None else "").strip()
        rumpf = str(text if text is not None else "").rstrip()
        if not rumpf:
            return {"ok": False, "fehler": "Der Entwurf braucht einen Text."}
        paare = []
        if an:
            paare, fehler = empfaenger_pruefen(an)
            if fehler:
                return {"ok": False, "fehler": fehler}
        faden = kennung_normalisieren(antwort_auf) if str(antwort_auf or "").strip() else ""
        if str(antwort_auf or "").strip() and not faden:
            return {"ok": False,
                    "fehler": "Die Kennung der Mail, auf die der Entwurf antwortet, ist nicht lesbar."}

        verbindung = None
        try:
            verbindung = self._verbinden(auswaehlen=bool(faden))
            von = _absender_adresse(auch_imap=True)
            if "@" not in von:
                von = str(IMAP_USER or "") if "@" in str(IMAP_USER or "") else ""
            if faden:
                kopf, fehler = self._original_aus(verbindung, faden)
                if fehler:
                    return {"ok": False, "fehler": fehler}
                nachricht = antwort_bauen(kopf, rumpf, von)
                if paare:
                    del nachricht["To"]
                    nachricht["To"] = _adressliste(paare)
                elif nachricht["To"] is None:
                    return {"ok": False,
                            "fehler": "Auf diese Mail ist keine Antwortadresse zu erkennen - "
                                      "nenne mir den Empfänger."}
                if betreff:
                    del nachricht["Subject"]
                    nachricht["Subject"] = betreff
            else:
                nachricht = EmailMessage()
                if von:
                    nachricht["From"] = von
                if paare:
                    nachricht["To"] = _adressliste(paare)
                nachricht["Subject"] = betreff or "(ohne Betreff)"
                nachricht["Date"] = email.utils.formatdate(localtime=True)
                nachricht["Message-ID"] = _nachricht_id(von)
                nachricht.set_content(rumpf + "\n")
            daten_bytes = nachricht.as_bytes()
            ordner, problem = self._entwurf_ablegen_in(verbindung, daten_bytes)
        except ValueError as problem_wert:
            return {"ok": False, "fehler": "Der Entwurf lässt sich so nicht bauen: %s" % problem_wert}
        except (imaplib.IMAP4.error, ssl.SSLError, OSError) as fehler:
            self.letzter_fehler = str(fehler)
            return {"ok": False, "fehler": "Das Postfach ist nicht erreichbar: %s" % fehler}
        finally:
            self._trennen(verbindung)
        if not ordner:
            self.letzter_fehler = problem
            return {"ok": False, "fehler": problem}
        betreff_gesetzt = str(nachricht["Subject"] or "")
        return {"ok": True, "ordner": imap_utf7_dekodieren(ordner), "betreff": betreff_gesetzt,
                "an": ", ".join(_adresse_anzeigen(n, a) for n, a in paare) if paare
                else _einzeilig(nachricht["To"] or ""),
                "text": "Der Entwurf „%s“ liegt im Ordner %s. Verschickt ist nichts."
                        % (betreff_gesetzt, imap_utf7_dekodieren(ordner))}

    def _entwurf_ablegen_in(self, verbindung, daten_bytes: bytes) -> tuple:
        """Legt die Mail per APPEND mit ``\\\\Draft`` ab: ``(ordnername, fehler)``."""
        try:
            status, daten = verbindung.list()
        except (imaplib.IMAP4.error, OSError):
            status, daten = "NO", []
        kandidaten = entwurf_ordner_kandidaten(daten if status == "OK" else [])
        letzter = "Der Entwürfe-Ordner ließ sich im Postfach nicht finden."
        for roh in kandidaten:
            try:
                status, antwort = verbindung.append(_imap_name_quoten(roh), "(\\Draft)", None,
                                                    daten_bytes)
            except imaplib.IMAP4.abort:
                raise
            except imaplib.IMAP4.error as fehler:
                letzter = "Der Server nimmt keinen Entwurf an: %s" % fehler
                continue
            if status == "OK":
                return roh, ""
            text = " ".join(
                (a.decode("utf-8", errors="replace") if isinstance(a, (bytes, bytearray)) else str(a))
                for a in (antwort or []))[:200]
            letzter = ("Der Entwürfe-Ordner ließ sich nicht beschreiben%s."
                       % (": " + text if text else ""))
        return "", letzter


# =========================================================================
# calendar_mod  -  Kalender über CalDAV - Termine lesen, Konflikte erkennen, anlegen, absagen, verschieben.
# 
# Bewusst ohne Fremdpaket: CalDAV ist HTTP mit zwei zusätzlichen Methoden. Das
# spart eine Abhängigkeit, die sonst bei jeder Installation schiefgehen kann.
# 
# Die Konflikterkennung ist der eigentliche Nutzen: Termine nach Beginn sortieren
# und jeden mit dem Ende des vorherigen vergleichen. Überlappt etwas, sagt Jarvis
# es von sich aus - bei einem Einzelunternehmer, der selbst zu den Objekten fährt,
# ist eine Doppelbuchung ein verlorener Tag.
# 
# Worauf es beim Lesen ankommt:
# 
# * **Zeiten.** Alles, was nach außen zeigt, ist lokale Zeit (Zeitzone aus
#   ``CALDAV_ZEITZONE``, sonst die des Rechners). Der Kalender liefert UTC (``Z``),
#   Ortszeit mit ``TZID`` (auch Windows-Namen), schwebende Zeit oder Tage ohne
#   Uhrzeit; ``ics_zeit_lesen`` macht daraus immer eine einfache lokale Zeit.
#   Geschrieben wird immer UTC mit ``Z`` - das versteht jeder Server gleich.
# * **Serien.** Der Server wird gebeten, Serien auszudehnen (``expand``). Tut er
#   es nicht, dehnt ``regel_ausdehnen`` die Wiederholungsregel selbst aus (täglich,
#   wöchentlich mit Wochentagen, monatlich am Tag oder am n-ten Wochentag,
#   jährlich; Intervall, Anzahl, Ende, ausgenommene Tage, einzeln geänderte oder
#   abgesagte Termine). Was darüber hinausgeht, wird nicht geraten: Jarvis sagt
#   es in einem Hinweis.
# * **Kennungen.** Jeder gelesene Termin bekommt eine kurze ``id``. Nur mit einer
#   frisch gelesenen ``id`` lässt sich etwas absagen oder verschieben - Jarvis
#   soll nie einen Termin ändern, den er nicht gerade gesehen hat.
# 
# Absagen ist zurücknehmbar: Der Termin wird vor dem Löschen im Papierkorb
# (Tabelle ``kalender_papierkorb``) gesichert. Gelöscht wird nur mit ``If-Match``
# auf den Stand, den Jarvis gelesen hat; hat sich der Termin inzwischen geändert,
# passiert nichts. Serientermine fasst Jarvis nie an.
# =========================================================================

#!/usr/bin/env python3
# -*- coding: utf-8 -*-




# Mit expand: der Server rechnet Serien selbst in einzelne Termine aus.
CALDAV_ABFRAGE = """<?xml version="1.0" encoding="utf-8" ?>
<C:calendar-query xmlns:D="DAV:" xmlns:C="urn:ietf:params:xml:ns:caldav">
  <D:prop><D:getetag/><C:calendar-data><C:expand start="%s" end="%s"/></C:calendar-data></D:prop>
  <C:filter>
    <C:comp-filter name="VCALENDAR">
      <C:comp-filter name="VEVENT">
        <C:time-range start="%s" end="%s"/>
      </C:comp-filter>
    </C:comp-filter>
  </C:filter>
</C:calendar-query>"""

# Für Server, die expand nicht können: Serien kommen unausgedehnt, Jarvis rechnet selbst.
CALDAV_ABFRAGE_OHNE_EXPAND = """<?xml version="1.0" encoding="utf-8" ?>
<C:calendar-query xmlns:D="DAV:" xmlns:C="urn:ietf:params:xml:ns:caldav">
  <D:prop><D:getetag/><C:calendar-data/></D:prop>
  <C:filter>
    <C:comp-filter name="VCALENDAR">
      <C:comp-filter name="VEVENT">
        <C:time-range start="%s" end="%s"/>
      </C:comp-filter>
    </C:comp-filter>
  </C:filter>
</C:calendar-query>"""

SCHEMA_KALENDER = """
CREATE TABLE IF NOT EXISTS kalender_papierkorb (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    href TEXT NOT NULL,
    ics TEXT NOT NULL,
    titel TEXT DEFAULT '',
    beginn TEXT DEFAULT '',
    geloescht_am TEXT NOT NULL,
    wiederhergestellt_am TEXT DEFAULT ''
);
"""

